// ==========================================
// ★ K 의 방 — C등급 직업 갈림길 · 회피
// ==========================================

// ── 곡예사 (acrobat) · 무력 ──────────────────
kJob('acrobat', 'C', [
  { at:'C', t:'사냥터 — 낮게 오는 등',
    x:`그것은 낮게 달린다. 배가 바닥에 닿을 만큼.<br><br>
    등이 넓다. 등뼈를 따라 딱딱한 판이 줄지어 솟았다. 배는 희고 무르다.<br>
    동료들이 무기를 든다. 그런데 배가 안 보인다. 바닥에 붙어 있다.<br><br>
    누가 그것을 한 번 뒤집어 주거나, 한 번 고개를 들게 해야 한다.`,
    o:[
      { l:'① 덤비는 등을 짚고 넘는다.', k:'evade', dc:14, wake:1,
        ok:`그것이 이쪽으로 왔다. 한 걸음 남기고 뛰었다.<br><br>등판 사이 홈에 손을 짚었다. 짚을 자리가 처음부터 거기 있었던 것처럼 손이 갔다. 넘었다.<br>그것이 이쪽을 찾느라 고개를 들었다. 흰 배가 드러났다. 동료들의 날이 거기로 들어갔다.<br><br>내려서서 손바닥을 봤다. 남의 등이 디딤돌로 보인 건 처음이다. 이제 다르게는 안 보일 것 같다.`,
        ng:`짚은 판이 움직였다. 판이 아니라 비늘이었다.<br><br>손이 미끄러졌다. 그것의 옆구리를 타고 굴러떨어졌다.<br>꼬리가 정강이를 쳤다. 동료들이 그 틈에 배를 찔렀지만 이쪽은 한참 못 일어났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 무력을 실어 옆으로 굴러 꼬리를 피한다.', k:'evade', dc:14, cost:{ might:18 },
        ok:`정면에 서 있다가 마지막에 옆으로 굴렀다. 다리에 힘을 다 실었다.<br><br>그것이 이쪽 자리를 지나 벽을 받았다. 꼬리가 뒤늦게 휘었다. 그 아래로 한 번 더 굴렀다.<br>벽에 머리를 박은 것이 잠깐 섰다. 동료들에게는 그 잠깐이면 됐다.<br><br>일어나니 무릎이 다 까졌다. 그 정도 값이다.`,
        ng:`구르는 방향을 꼬리가 먼저 알았다.<br><br>꼬리가 등을 내리쳤다. 바닥에 납작하게 붙었다. 숨이 한 번에 빠졌다.<br>동료가 끌어냈다. 등에 판 자국이 그대로 찍혔다.`,
        win:{ exp:16, dream:1 }, lose:{ hp:-18, mind:-4 } }
    ] },

  { at:'C', t:'굴 — 천장에 붙은 것들',
    x:`천장에 주머니가 매달려 있다. 사람 몸통만 하다. 여럿이다.<br><br>
    가끔 하나가 떨어진다. 떨어진 주머니가 바닥에서 펴진다. 다리가 나온다. 그리고 달린다.<br>
    곡예사는 위를 본다. 남들이 앞을 볼 때.<br><br>
    주머니들이 매달린 줄기가 한 군데로 모인다. 들보 하나다.`,
    o:[
      { l:'① 거꾸로 매달려 주머니를 하나씩 끊어 낸다.', k:'evade', dc:15,
        ok:`들보에 다리를 걸고 거꾸로 매달렸다.<br><br>주머니가 펴지기 전에 줄기를 끊었다. 떨어진 것은 아래에서 동료들이 기다렸다가 찔렀다. 펴질 틈이 없다.<br>여섯을 끊었다. 일곱째가 이쪽 얼굴 앞에서 눈을 떴다. 줄기를 끊었다. 같이 떨어졌다.<br><br>떨어지는 동안 몸을 돌려 발로 내렸다. 그것은 등으로 떨어졌다.`,
        ng:`거꾸로 매달리자 피가 머리로 몰렸다.<br><br>한 박자 늦었다. 주머니 하나가 매달린 채 펴졌다. 다리가 이쪽 목을 감았다.<br>들보에서 떨어졌다. 동료가 그것을 떼어 냈다. 목에 가는 줄이 여럿 남았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-14, spirit:-8 } },
      { l:'② 동료들을 엎드리게 하고 떨어지는 것을 알린다.', k:'bond', dc:14,
        ok:`엎드리라고 했다. 이쪽만 섰다. 위를 봤다.<br><br>주머니가 흔들리면 이름을 불렀다. 그 사람이 비켰다. 떨어진 것은 나머지가 둘러쌌다.<br>위를 보는 사람이 하나 있으면 아래는 싸움이 된다.<br><br>굴을 다 지났다. 목이 뻣뻣하다.`,
        ng:`두 개가 한꺼번에 흔들렸다. 이름을 하나만 불렀다.<br><br>못 부른 사람 위로 떨어졌다. 다리가 펴지며 그 사람 팔을 물었다.<br>떼어 냈다. 이쪽 손도 물렸다.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-10, mind:-8 } },
      { l:'③ 무력을 실어 들보 위로 올라가 통째로 흔든다.', k:'break', dc:14, cost:{ might:20 },
        ok:`벽을 차고 들보 위에 올라섰다. 두 발로 들보를 굴렀다. 힘을 다 실었다.<br><br>주머니가 한꺼번에 떨어졌다. 펴지기 전이다. 덜 자란 것들이다. 바닥에서 꿈틀대다 터졌다.<br>몇 개는 펴졌다. 그건 동료들 몫이다.<br><br>들보 위에서 다리가 떨렸다. 힘을 너무 썼다.`,
        ng:`굴렀는데 들보가 먼저 울었다. 금이 갔다.<br><br>들보째 내려앉았다. 주머니들 사이로 떨어졌다.<br>펴지는 소리 속에서 기어 나왔다. 등에 다리 자국이 셋.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C', t:'구덩이 — 걸쳐 쓰러진 것',
    x:`잡은 것이 쓰러지면서 구덩이 위에 걸쳤다.<br><br>
    머리가 이쪽, 꼬리가 건너편이다. 다리가 될 만큼 길다.<br>
    구덩이는 깊다. 바닥에서 뭔가 젖은 소리가 난다.<br><br>
    등뼈가 마디마디 솟아 있다. 디딜 자리는 된다. 아직 따뜻하다.`,
    o:[
      { l:'① 등뼈를 디디며 건넌다.', k:'evade', dc:15,
        doom:{ title:'등뼈', what:'구덩이 아래로 떨어졌습니다', dc:15, sec:60,
          text:`마디 하나에 한 발씩. 다섯째 마디까지 갔다.<br><br>여섯째 마디가 움직였다. 숨을 쉰 것이다. 덜 죽었다.<br>등이 한 번 크게 들썩였다. 발이 떴다. 구덩이 벽을 손으로 긁으며 미끄러졌다.<br><br>아래에서 젖은 소리가 가까워진다. 손톱 끝만 벽에 걸렸다.`,
          dieText:`곡예사는 디딜 자리를 고른다.<br><br>죽은 것을 골랐다. 덜 죽은 것이었다.<br>건너편에서 그것이 숨을 한 번 더 쉬고 그쳤다. 이번에는 다 죽었다.` },
        ok:`첫 마디에 무게를 반만 실었다. 마디가 조금 내려갔다가 올라왔다.<br><br>숨이다. 덜 죽었다. 그렇다면 숨 쉬는 박자에 맞추면 된다.<br>내쉴 때 디디고 들이쉴 때 떴다. 등이 들썩이는 대로 같이 들썩였다. 건넜다.<br><br>건너편에 내려서자 그것이 마지막 숨을 내쉬었다. 기다려 준 것처럼.`,
        win:{ exp:22, dream:3 } },
      { l:'② 구덩이 가장자리 턱을 따라 돈다.', k:'sense', dc:13,
        ok:`가장자리를 따라 손끝으로 벽을 짚었다. 턱이 이어진다.<br><br>오래 걸렸다. 등뼈 다리는 안 밟았다.<br>건너편에 닿았을 때 그것이 꿈틀했다. 덜 죽었던 것이다.<br><br>밟았으면 어떻게 됐을지는 생각 안 하기로 했다.`,
        ng:`턱이 젖어 있었다. 아래에서 올라온 것이 핥고 간 자리다.<br><br>발이 미끄러졌다. 팔꿈치로 걸었다. 기어 올라왔다.<br>팔꿈치가 다 벗겨졌다. 아래의 것은 아직 이쪽을 기억한다.`,
        win:{ exp:14, dream:1 }, lose:{ hp:-12, spirit:-6 } }
    ] },

  { at:'C', t:'외길 — 맞은편에서 오는 것',
    x:`돌다리다. 폭이 한 발이다. 양옆은 아래가 없다.<br><br>
    반쯤 왔을 때 맞은편에서 그것이 들어섰다. 네 발이다. 이쪽보다 크다. 돌아갈 생각이 없다.<br>
    물러나면 뒤에 동료들이 있다. 그것은 동료들까지 밀고 올 것이다.<br><br>
    곡예사는 비킬 데가 없을 때도 비킨다. 위로든 아래로든.`,
    o:[
      { l:'① 그것을 넘는다.', k:'evade', dc:15, wake:1,
        ok:`그것이 고개를 숙이고 왔다. 숙인 머리를 짚었다. 짚은 손을 축으로 몸을 넘겼다.<br><br>발이 그것의 엉덩이를 지나 다리 위에 내렸다. 그것은 이쪽이 사라진 줄 안다. 그대로 달려가 동료들 창끝에 걸렸다.<br>돌아서서 다리 위를 봤다. 폭이 한 발이다. 넘는 동안은 그게 넓었다.<br><br>발밑으로 지나가는 것이 무엇이든 상관이 없어졌다. 지나가기만 하면 된다.`,
        ng:`머리를 짚으려는데 그것이 머리를 들었다.<br><br>손이 빈 데를 짚었다. 그것의 어깨에 부딪혀 다리 가장자리로 밀렸다. 한 손으로 매달렸다.<br>그것이 이쪽 손가락 위를 밟고 지나갔다. 동료들이 막았다. 손가락이 안 펴진다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-8 } },
      { l:'② 무력으로 다리 밑에 매달려 흘려보낸다.', k:'steady', dc:14, cost:{ might:16 },
        ok:`다리 옆으로 몸을 내리고 두 손으로 모서리를 잡았다. 매달렸다.<br><br>그것이 머리 위로 지나간다. 발톱이 손가락 한 마디 옆을 찍는다. 버텼다.<br>지나간 것은 동료들이 맞았다. 이쪽은 다시 올라왔다.<br><br>손가락이 하얗게 질렸다. 힘으로 매달린 손이다.`,
        ng:`매달린 손 위를 그것이 정확히 밟았다.<br><br>한 손이 떨어졌다. 남은 손 하나로 버텼다. 아래에서 찬 기운이 올라온다.<br>동료가 끌어올렸다. 손등이 터졌다.`,
        win:{ exp:16, dream:1 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C1', t:'도살 라인 — 도는 갈고리',
    x:`천장 레일을 따라 갈고리가 돈다. 멈추지 않는다.<br><br>
    갈고리마다 고깃덩이가 걸렸다. 잘린 자리가 아물어 있다. 어떤 것은 잘린 자리에서 새 살이 손가락만큼 자랐다.<br>
    바닥은 피와 기름이다. 걸어서 건너면 미끄러지고, 미끄러지면 고깃덩이 아래로 들어간다. 고깃덩이 아래는 따뜻하다.<br><br>
    갈고리는 일정한 간격으로 온다. 곡예사에게는 그게 줄이다.`,
    o:[
      { l:'① 갈고리를 잡아 갈아타며 건넌다.', k:'evade', dc:15, wake:1,
        ok:`첫 갈고리 자루를 잡았다. 몸이 레일을 따라 실려 간다. 다음 갈고리가 오는 박자에 손을 바꿨다.<br><br>세 번, 네 번. 고깃덩이가 어깨를 스친다. 미지근하다. 하나가 이쪽 쪽으로 몸을 틀었다. 그 전에 손을 놓고 다음 것을 잡았다.<br>건너편에 내려섰다. 손이 아직 다음 갈고리를 찾아 쥐었다 폈다 한다.<br><br>매달리는 게 아니라 옮겨 다니는 것이다. 손이 그걸 먼저 알고, 몸이 뒤에서 따라왔다.`,
        ng:`넷째 갈고리 자루가 기름에 젖어 있었다.<br><br>손이 미끄러졌다. 고깃덩이를 껴안고 매달렸다. 고깃덩이가 이쪽 팔을 껴안았다. 살이 살에 붙는다.<br>떼어 내고 떨어졌다. 팔에 남의 살갗이 한 겹 붙어 왔다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-14, spirit:-10 } },
      { l:'② 바닥에 몸을 붙이고 미끄러져 지난다.', k:'evade', dc:14,
        ok:`기름 바닥에 등을 대고 발로 밀었다. 미끄러진다. 막지 않았다.<br><br>고깃덩이 아래로 지나갔다. 위에서 뭔가 떨어진다. 핏방울인지 다른 것인지 모른다. 얼굴을 돌렸다.<br>배수구 턱에서 몸을 접어 일어섰다.<br><br>등이 다 젖었다. 냄새는 오래 갈 것이다.`,
        ng:`미끄러지다 고깃덩이 하나 바로 아래서 멈췄다. 바닥에 턱이 있었다.<br><br>위에서 고깃덩이가 내려왔다. 갈고리가 늘어난 것이다. 얼굴을 덮었다. 따뜻하다.<br>밀어내고 기어 나왔다. 숨이 한참 비렸다.`,
        win:{ exp:16, dream:1 }, lose:{ hp:-10, mind:-10 } },
      { l:'③ 지나가며 덜 자란 덩이를 하나 떼어 온다.', k:'luck', dc:14,
        ok:`갈고리를 하나 타고 가며 덜 자란 덩이를 골랐다. 새 살이 안 난 것.<br><br>갈고리에서 비틀어 뺐다. 묵직하다. 아직 그냥 고기다. 칼로 끝을 잘라 봤다. 안 아문다.<br>건너편에 내려서 품에 넣었다.<br><br>먹을 수 있을지는 요리사가 볼 것이다. 이건 다시 안 자랐다. 아직은.`,
        ng:`고른 덩이가 떼어지는 순간 꿈틀했다.<br><br>덜 자란 게 아니라 막 자라기 시작한 것이었다. 손을 물었다. 이가 없는데 물었다.<br>놓았다. 덩이가 바닥에 떨어져 배수구 쪽으로 기어갔다.`,
        win:{ exp:15, item:'짐승 고기' }, lose:{ hp:-12, spirit:-6 } }
    ] },

  { at:'C1', t:'정육실 — 기름 바닥의 작업대',
    x:`긴 작업대가 줄지어 있다. 바닥은 기름이 두껍게 굳었다가 다시 녹았다.<br><br>
    작업대 위에서 잘린 것들이 움직인다. 다리 하나, 갈비 한 짝. 제자리로 돌아가려고 서로를 찾는다.<br>
    방 끝 선반에 염장용 소금 자루가 있다. 바닥으로 가면 잘린 것들 사이를 지나야 한다.<br><br>
    작업대 위로 가면 잘린 것들 위를 지나야 한다.`,
    o:[
      { l:'① 기름 바닥을 미끄러져 지난다.', k:'evade', dc:14,
        ok:`첫 걸음에 미끄러졌다. 넘어지지 않고 그대로 밀고 나갔다. 발바닥 전체로.<br><br>작업대 다리 사이를 빠져나갔다. 위에서 다리 하나가 떨어지며 이쪽을 차려 했다. 한 바퀴 돌아 비켰다.<br>선반 앞에서 섰다. 자루를 잡고 끌어내렸다.<br><br>미끄러운 바닥은 서 있으려는 사람만 넘어뜨린다.`,
        ng:`미끄러지다 바닥에 떨어진 갈비에 걸렸다.<br><br>갈비가 이쪽 발목을 감았다. 뼈가 손가락처럼 굽는다. 넘어졌다.<br>칼로 쳐서 떼어 냈다. 발목에 갈비 자국이 둥글게 났다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } },
      { l:'② 무력을 실어 작업대 위를 뛰어 건넌다.', k:'evade', dc:15, cost:{ might:18 },
        ok:`작업대 끝을 디디고 뛰었다. 다음 작업대, 그다음. 잘린 것들 사이 빈 데만 디뎠다.<br><br>다리 하나가 이쪽 발을 따라 일어섰다. 그 위를 디디고 더 높이 뛰었다. 디딤돌이 하나 늘었다.<br>선반 위 소금 자루를 내려 들었다. 자루가 터진 데로 굳은 덩이가 굴러 나왔다.<br><br>소금 닿은 고기는 안 움직인다. 이 방에서 그걸 아는 건 선반뿐이었다.`,
        ng:`셋째 작업대에서 발 밑의 것이 뒤집혔다.<br><br>갈비 한 짝이었다. 이쪽 발을 물고 같이 넘어졌다. 작업대 모서리에 옆구리를 찧었다.<br>숨이 안 쉬어진다. 갈비는 칼로 떼어 냈다.`,
        win:{ exp:18, item:'소금 덩이' }, lose:{ hp:-16, mind:-4 } }
    ] },

  { at:'C1', t:'출하장 — 반장의 칼',
    x:`라인 끝에 그것이 서 있다. 앞치마를 둘렀다. 앞치마 아래로 팔이 여럿이다.<br><br>
    팔마다 칼이다. 라인에서 내려오는 것을 자르고, 잘린 것을 갈고리에 다시 건다. 멈추지 않는다.<br>
    동료들이 옆에서 칠 틈을 노린다. 그것은 앞만 본다. 앞에 뭔가 있으면 자른다.<br><br>
    앞에 뭔가 있어야 한다. 잘리지 않는 것이.`,
    o:[
      { l:'① 칼 앞에서 뛰며 눈을 끈다.', k:'evade', dc:15,
        doom:{ title:'갈고리 줄', what:'갈고리에 걸려 라인으로 끌려갑니다', dc:15, sec:60,
          text:`칼 앞에서 뛰었다. 첫 칼, 둘째 칼. 다 넘었다.<br><br>셋째 팔은 칼이 아니었다. 갈고리였다. 넘는 이쪽 허리띠에 걸렸다.<br>몸이 들려 레일에 걸렸다. 라인이 이쪽을 싣고 돈다. 다음 칼 쪽으로.<br><br>동료들이 레일을 따라 뛰어온다. 칼까지 갈고리 열 개 거리다.`,
          dieText:`곡예사는 칼을 넘는다. 칼은 넘으라고 있는 것이 아니었다.<br><br>라인은 멈추지 않는다. 잘린 것은 다시 걸린다.<br>며칠 뒤 그 갈고리에 걸린 덩이에서 새 살이 자라기 시작했다.` },
        ok:`칼 앞에서 뛰었다. 첫 칼, 둘째 칼. 넘을 때마다 다음 칼이 어디서 올지 봤다.<br><br>셋째 팔이 갈고리라는 걸 넘기 전에 봤다. 넘지 않고 밑으로 굴렀다. 갈고리가 빈 데를 걸었다.<br>그것이 걸린 것이 없는 갈고리를 들여다봤다. 처음으로 앞이 아닌 데를 봤다.<br><br>옆에서 동료들이 앞치마 끈을 끊었다. 팔들이 한꺼번에 늘어졌다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 무력을 실어 레일에 올라 사슬을 끊는다.', k:'break', dc:15, cost:{ might:20 },
        ok:`기둥을 차고 레일 위에 올라섰다. 갈고리를 끄는 사슬이 발밑으로 흐른다.<br><br>사슬 고리 하나에 칼을 끼우고 온 힘으로 비틀었다. 끊어졌다. 라인이 멈췄다.<br>그것이 멈춘 라인을 올려다봤다. 팔들이 갈 데를 잃었다. 동료들이 그 사이로 들어갔다.<br><br>레일 위에서 내려다보니 앞치마가 얼마나 넓은지 보였다. 옆에서는 안 보이는 넓이다.`,
        ng:`사슬이 끊기기 전에 이쪽 칼이 먼저 부러졌다.<br><br>사슬이 튀어 이쪽 다리를 감았다. 레일에서 떨어졌다. 앞치마 바로 앞에.<br>동료들이 그것을 막는 사이 기어서 빠졌다. 종아리가 갈라졌다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-18, mind:-6 } }
    ] },

  { at:'C2', t:'실 감는 방 — 늘어진 실',
    x:`천장에서 실이 내려온다. 수백 가닥이다. 방 전체가 실이다.<br><br>
    실 끝마다 사기 인형이 매달렸다. 고개를 숙이고 있다. 실 하나가 흔들리면 그 인형이 고개를 든다.<br>
    고개를 든 인형은 입을 연다. 입 안에 이가 있다. 사람 이다. 다 다른 사람 것이다.<br><br>
    실과 실 사이는 한 뼘이다. 곡예사의 몸은 한 뼘을 지나갈 수 있다. 짐은 못 지나간다.`,
    o:[
      { l:'① 짐을 내려놓고 몸을 접어 실 사이로 빠진다.', k:'evade', dc:15,
        ok:`짐을 내려놓았다. 숨을 내쉬어 가슴을 줄였다. 어깨를 안으로 말았다.<br><br>실과 실 사이로 몸을 밀어 넣었다. 한 뼘. 실이 귀 옆을 지난다. 안 흔들렸다.<br>건너편에서 실 감는 물레를 멈췄다. 실이 늘어졌다. 인형들이 고개를 숙인 채 바닥에 내려앉았다.<br><br>동료들이 짐을 들고 늘어진 실을 헤치고 왔다. 인형은 한 번도 고개를 안 들었다.`,
        ng:`반쯤 왔을 때 숨이 찼다. 가슴이 부풀었다.<br><br>실 하나가 흔들렸다. 바로 옆 인형이 고개를 들었다. 입이 이쪽 귀 옆에서 열렸다.<br>귓바퀴를 물렸다. 뜯어내고 빠져나왔다. 인형 입 안에 이쪽 피가 묻었다. 인형이 웃는 것처럼 보였다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-12, spirit:-10 } },
      { l:'② 실을 따라 위를 보고 묶인 자리를 찾는다.', k:'gaze', dc:14,
        ok:`실을 따라 눈을 올렸다. 천장 가까이에서 실들이 모인다. 몇 다발로.<br><br>다발마다 매듭이 하나다. 매듭 하나를 끊으면 그 다발 인형이 전부 떨어진다.<br>동료에게 활로 매듭을 쏘게 했다. 한 다발이 바닥에 쏟아졌다. 사기가 깨지는 소리가 오래 났다.<br><br>깨진 사기 사이에 이가 흩어졌다. 아무도 줍지 않았다.`,
        ng:`위를 보는 동안 발이 실을 건드렸다.<br><br>그 실 끝 인형이 고개를 들었다. 옆 실도, 그 옆 실도. 차례로 고개를 든다.<br>뒷걸음질 쳐 나왔다. 정강이에 작은 이 자국이 줄을 지었다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-10, mind:-8 } }
    ] },

  { at:'C2', t:'진열장 — 맨 위 칸',
    x:`벽 하나가 진열장이다. 천장까지 칸이 이어진다.<br><br>
    칸마다 인형이 앉아 있다. 다 이쪽을 본다. 눈은 유리다. 유리 눈이 이쪽이 움직이는 대로 따라 돈다.<br>
    맨 위 칸에는 인형 대신 단지가 하나 있다. 도장할 때 물감에 섞던 꿀이다. 인형이 못 닿는 데 둔 것이다.<br><br>
    곡예사는 칸을 사다리로 본다. 인형이 앉은 칸을.`,
    o:[
      { l:'① 인형 사이 빈 데만 딛고 오른다.', k:'evade', dc:14,
        ok:`인형과 인형 사이 손가락 두 개 너비를 딛고 올랐다.<br><br>유리 눈이 따라 돈다. 한 칸 오를 때마다 인형들 고개가 한 칸씩 든다. 손은 안 뻗는다. 아직.<br>맨 위 칸에서 단지를 품에 넣고 뒤로 넘어 내렸다. 두 바퀴. 바닥에 섰다.<br><br>올려다보니 인형들 고개가 다 맨 위 칸을 보고 있다. 빈 칸을.`,
        ng:`일곱째 칸에서 발끝이 인형 무릎을 밀었다.<br><br>그 인형이 손을 뻗어 이쪽 발목을 잡았다. 사기 손이 차갑고 세다. 옆 칸 인형들도 손을 뻗는다.<br>발을 빼며 떨어졌다. 등으로 떨어졌다. 발목에 손가락 자국이 다섯.`,
        win:{ exp:16, item:'꿀 한 줌' }, lose:{ hp:-14, mind:-6 } },
      { l:'② 무력을 실어 진열장을 차 넘어뜨린다.', k:'break', dc:14, cost:{ might:18 },
        ok:`진열장 아래 칸을 힘껏 찼다. 한 번, 두 번. 진열장이 앞으로 기운다.<br><br>뒤로 굴러 비켰다. 진열장이 통째로 엎어졌다. 사기 깨지는 소리가 방을 채웠다.<br>잔해 위로 단지가 굴러 나왔다. 뚜껑이 닫혀 있다. 안 깨졌다.<br><br>깨진 인형들의 입이 바닥에서 아직 열렸다 닫혔다 한다. 하나씩 밟고 지났다.`,
        ng:`진열장이 기울다 멈췄다. 벽에 박혀 있었다.<br><br>흔들린 칸에서 인형들이 쏟아졌다. 이쪽 위로. 깨지면서도 문다.<br>털어 내고 기어 나왔다. 팔뚝에 이 자국이 촘촘하다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, spirit:-6 } }
    ] },

  { at:'C2', t:'다락 — 손목에 붙은 실',
    x:`다락 계단을 오르는데 손목이 당긴다.<br><br>
    보니 실이 붙어 있다. 언제 붙었는지 모른다. 실은 위로 이어진다. 다락 어둠 속으로.<br>
    실이 한 번 당겼다. 이쪽 팔이 저절로 들렸다. 위에서 누가 이쪽을 움직여 본다.<br><br>
    곡예사는 남이 당기는 줄에 올라 본 적이 있다. 남이 당기는 줄이 된 적은 없다.`,
    o:[
      { l:'① 당기는 쪽보다 먼저 몸을 돌린다.', k:'evade', dc:16, wake:1,
        ok:`실이 당길 때 이쪽이 먼저 갔다. 당기는 방향으로 반 박자 빨리.<br><br>실이 느슨해졌다. 위에서 당긴 힘이 갈 데가 없다. 실이 휘청했다. 그 틈에 몸을 한 바퀴 돌려 실을 팔에 감았다. 감은 채 당겼다.<br>위에서 뭔가 휘청하는 소리가 났다. 실이 끊어졌다. 위의 것이 끊었다.<br><br>남의 줄 위에서도 무게 중심은 이쪽 것이다. 그걸 손목이 기억했다. 이제는 줄이 이쪽에 붙어도 안 무섭다.`,
        ng:`먼저 돌았는데 위에서 그걸 기다렸다.<br><br>실이 이쪽 회전을 따라 감겼다. 두 팔이 등 뒤로 묶였다. 몸이 들렸다. 발끝이 계단에서 떨어진다.<br>동료가 칼로 실을 끊었다. 계단에 떨어졌다. 팔에 실 자국이 깊다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-14, mind:-10 } },
      { l:'② 동료에게 팔을 내밀어 끊게 한다.', k:'bond', dc:14,
        ok:`팔을 동료 쪽으로 내밀었다. 손목을 가리켰다.<br><br>동료가 칼을 댔다. 실이 당겼다. 이쪽은 힘을 빼고 팔을 실이 가는 대로 뒀다. 칼이 따라왔다. 끊었다.<br>위에서 실 하나가 힘없이 떨어졌다.<br><br>혼자 끊으려 했으면 몸 전체가 끌려갔을 것이다.`,
        ng:`동료가 칼을 대는 순간 실이 세게 당겼다.<br><br>이쪽 팔이 칼날 쪽으로 갔다. 팔뚝이 베였다. 실도 같이 끊겼다.<br>피가 계단을 따라 떨어진다. 위에서 그걸 보고 있다는 느낌이 들었다.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-12, mind:-6 } },
      { l:'③ 무력을 실어 반대로 버틴다.', k:'steady', dc:15, cost:{ might:20 },
        ok:`난간을 붙잡고 다리로 버텼다. 팔에 힘을 다 실어 아래로 당겼다.<br><br>위에서도 당긴다. 실이 팽팽하게 운다. 버텼다. 오래.<br>위에서 먼저 놓았다. 실이 늘어졌다. 손목에서 떼어 냈다.<br><br>실 끝에 사기 손가락 하나가 묶여 딸려 왔다. 위의 것이 손가락 하나를 잃었다.`,
        ng:`버티는데 실이 하나 더 붙었다. 다른 손목에.<br><br>두 팔이 벌어졌다. 몸이 십자로 들렸다. 동료들이 매달려 끌어내렸다.<br>어깨가 둘 다 빠질 뻔했다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C3', t:'둥근 천장 — 갈빗대 위',
    x:`여기서는 천장을 밟고 걷는다. 머리 위에 신도석이 거꾸로 매달려 있다.<br><br>
    둥근 천장은 돌 갈빗대가 엮어 받친다. 갈빗대 사이는 회칠이다. 성인들이 그려져 있다. 회칠은 얇고 금이 갔다.<br>
    금 사이로 아래가 보인다. 아래는 어둠이다. 바닥이 없다.<br><br>
    갈빗대는 발 하나 너비다. 휘어서 올라갔다가 내려온다.`,
    o:[
      { l:'① 갈빗대 위를 달려 건넌다.', k:'evade', dc:14,
        ok:`갈빗대에 올라 달렸다. 휜 데서는 몸을 기울여 휘는 대로 갔다.<br><br>갈빗대가 만나는 매듭돌에서 방향을 바꿨다. 매듭돌 하나가 흔들렸다. 디딘 발을 바로 뗐다.<br>회칠 위 성인 그림 하나가 눈을 떴다. 이쪽이 지나간 다음이다.<br><br>건너편 기둥에 닿았다. 뒤에서 흔들리던 매듭돌이 아래로 떨어졌다. 소리가 안 돌아왔다.`,
        ng:`휜 데서 발이 바깥으로 밀렸다.<br><br>회칠을 디뎠다. 성인 얼굴 위였다. 금이 발밑으로 퍼진다. 갈빗대를 껴안고 버텼다.<br>발 하나가 회칠을 뚫고 어둠에 들어갔다. 차갑다. 뭔가 발가락을 핥았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-12, spirit:-10 } },
      { l:'② 금이 덜 간 회칠을 골라 걷는다.', k:'sense', dc:13,
        ok:`금을 봤다. 오래된 금은 가장자리가 검고 새 금은 하얗다.<br><br>검은 금만 있는 회칠을 골라 디뎠다. 오래 버틴 데는 더 버틴다.<br>느렸다. 갈빗대 위를 달리는 것보다 세 배 걸렸다.<br><br>건넜다. 디딘 자리마다 성인 그림이 조금씩 눈을 찡그렸다.`,
        ng:`하얀 금 하나를 못 봤다. 성인 수염 속에 숨어 있었다.<br><br>회칠이 꺼졌다. 무릎까지 빠졌다. 갈빗대를 잡았다. 손톱이 들렸다.<br>끌어올려졌다. 무릎 아래가 감각이 없다. 어둠이 묻었다.`,
        win:{ exp:14, dream:1 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C3', t:'종탑 — 종거미',
    x:`종탑이 아래로 늘어졌다. 그 끝에 종이 있다. 종이 걷는다.<br><br>
    종 테두리에서 다리가 나왔다. 길고 마디가 많다. 다리로 종탑 벽을 짚고 매달려 있다.<br>
    종이 울 때마다 벽이 떨린다. 떨림이 발밑까지 온다. 발이 떨리면 디딘 데를 놓친다.<br><br>
    종 아래를 지나야 아래층 계단이다. 종거미는 아래로 지나는 것을 덮는다.`,
    o:[
      { l:'① 울림 사이에 종 아래를 지난다.', k:'evade', dc:15, wake:1,
        ok:`종이 울었다. 떨림이 왔다. 무릎을 풀고 떨림을 몸으로 흘렸다. 발은 그대로 붙어 있다.<br><br>다음 울림까지 셌다. 일곱. 일곱 사이에 종 아래로 뛰어들었다. 종 안에서 혀가 이쪽을 향해 흔들렸다. 혀가 아니다. 팔이다.<br>팔 아래로 구르고, 반대편 테두리 밖으로 굴러 나왔다. 일곱째에 종이 울었다. 이쪽은 이미 밖이다.<br><br>흔들리는 바닥에서 몸이 버티는 게 아니라 같이 흔들렸다. 같이 흔들리니 놓칠 게 없었다.`,
        ng:`여섯째에 종이 울었다. 박자가 바뀌었다.<br><br>떨림에 발이 떴다. 종 안으로 떨어졌다. 안쪽 팔이 이쪽 어깨를 잡았다. 종이 내려앉는다.<br>동료들이 테두리를 들어 올렸다. 그 틈으로 빠졌다. 어깨에 쇠 비린내가 배었다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-8 } },
      { l:'② 무력을 실어 종 테두리를 짚고 넘는다.', k:'evade', dc:14, cost:{ might:18 },
        ok:`벽을 차고 올라 종 테두리를 짚었다. 짚은 손에 힘을 다 실어 몸을 종 위로 넘겼다.<br><br>종 꼭대기를 한 번 디뎠다. 차갑다. 종이 이쪽 무게에 울었다. 위에서 울리니 아래로만 떨림이 갔다.<br>반대편으로 내렸다. 종거미 다리들이 엉뚱한 데를 짚었다.<br><br>손바닥에 녹이 묻었다. 녹 아래에 글씨가 있었다. 누구 이름인지 읽기 전에 내려왔다.`,
        ng:`테두리를 짚는 순간 종이 울었다.<br><br>손바닥으로 울림을 다 받았다. 팔이 저려 놓쳤다. 종 옆으로 미끄러졌다. 다리 하나가 이쪽 허리를 감았다 놓았다.<br>계단까지 굴렀다. 허리에 마디 자국이 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C3', t:'머리 위의 신도석',
    x:`머리 위에 신도석이 거꾸로 매달렸다. 거기 누가 앉아 있다.<br><br>
    밀랍이다. 사람 모양으로 녹아 굳은 밀랍. 수사복을 입었다. 거꾸로 앉아서 거꾸로 기도한다. 손가락이 초처럼 녹아 늘어졌다.<br>
    신도석 끝에 초 상자가 있다. 밀랍 덩이와 꿀이 든 상자. 성당 벌집에서 나온 것이다.<br><br>
    기둥을 거꾸로 타고 올라가면 닿는다. 밀랍 수사들 사이로.`,
    o:[
      { l:'① 기둥을 거꾸로 타고 신도석까지 오른다.', k:'evade', dc:15,
        doom:{ title:'밀랍 수사', what:'밀랍 수사에게 신도석으로 끌려 올라갑니다', dc:15, sec:60,
          text:`기둥을 타고 올랐다. 신도석 가장자리를 잡았다. 매달려 몸을 넘겼다.<br><br>밀랍 수사 하나가 기도를 멈췄다. 늘어진 손가락이 이쪽 손목에 감겼다. 따뜻하다. 녹는 중이다.<br>이쪽을 신도석 안쪽으로 끌어당긴다. 옆자리가 비어 있다. 밀랍이 이쪽 소매로 흘러든다.<br><br>아래에서 동료들 목소리가 거꾸로 들린다. 손목부터 굳어 간다.`,
          dieText:`곡예사는 거꾸로 매달리는 데 익숙하다.<br><br>신도석에 거꾸로 앉은 것이 하나 늘었다. 굳은 손이 기도하는 모양이다.<br>다음 사람이 기둥을 오르면 손가락이 녹아 늘어질 것이다.` },
        ok:`기둥을 타고 올라 신도석 등받이 밑을 매달려 지났다. 밀랍 수사들 발 아래로.<br><br>초 상자까지 손으로 옮겨 갔다. 상자를 열었다. 밀랍 덩이 사이에 꿀이 굳어 있다. 한 줌 떠냈다.<br>내려가는 길에 수사 하나가 발을 움직였다. 녹은 발가락이 이쪽 머리 위로 떨어졌다. 뜨겁다. 몸을 놓고 떨어져 천장에 굴러 내렸다.<br><br>머리카락에 밀랍이 굳었다. 그것만 가져왔다고 하기에는 꿀이 달다.`,
        win:{ exp:22, dream:3, item:'꿀 한 줌' } },
      { l:'② 기둥 아래에서 줄을 걸어 상자를 끌어내린다.', k:'fix', dc:14,
        ok:`줄 끝에 돌을 매어 신도석 끝으로 던졌다. 세 번째에 상자 손잡이에 걸렸다.<br><br>천천히 당겼다. 상자가 신도석 끝에서 기울었다. 밀랍 수사들이 고개를 돌렸다. 그 전에 상자가 떨어졌다.<br>받았다. 안에 굳은 꿀이 있다.<br><br>위에서 수사들이 빈자리를 오래 봤다.`,
        ng:`줄이 상자가 아니라 수사 손가락에 걸렸다.<br><br>당기자 손가락이 늘어나며 따라 내려왔다. 줄을 타고 밀랍이 흘러내린다. 이쪽 손까지.<br>줄을 놓았다. 손등이 데었다. 굳은 밀랍을 뜯어내니 살갗이 같이 뜯겼다.`,
        win:{ exp:16, item:'꿀 한 줌' }, lose:{ hp:-12, spirit:-6 } }
    ] },

  { at:'C4', t:'온실 — 유리 지붕 골조',
    x:`온실 바닥이 하얗다. 균이 깔렸다. 걸으면 가루가 오른다. 가루는 숨으로 들어온다.<br><br>
    위를 봤다. 유리 지붕을 받친 쇠 골조가 격자로 이어진다. 유리는 김이 서려 뿌옇다. 골조는 녹이 슬었다.<br>
    가루는 무겁다. 아래에 깔린다. 위로는 덜 온다.<br><br>
    골조 하나가 저 끝 빗물 받이까지 이어진다.`,
    o:[
      { l:'① 골조 위로 올라 격자를 건넌다.', k:'evade', dc:15, wake:1,
        ok:`기둥을 타고 골조에 올랐다. 쇠가 손바닥 너비다. 녹 위에 습기가 앉아 미끄럽다.<br><br>발바닥 전체로 딛고 무게를 발 앞쪽에 뒀다. 격자가 만나는 데서는 멈추지 않고 방향을 틀었다. 아래에서 하얀 것들이 이쪽 그림자를 따라 고개를 든다. 위까지는 못 온다.<br>빗물 받이에 닿았다. 숨을 쉬었다. 깨끗하다.<br><br>발이 좁은 데를 좁다고 여기지 않았다. 쇠 한 줄이 길 한 줄이 됐다. 이 온실은 이쪽에게 길이 두 배다.`,
        ng:`격자 이음매가 녹슬어 빠져 있었다.<br><br>쇠가 반쯤 내려앉았다. 이쪽도 반쯤. 다리 하나가 아래로 처졌다. 하얀 것이 그 다리에 닿았다.<br>끌어올렸다. 바짓단에 하얀 실이 감겼다. 털어도 안 떨어진다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-12, spirit:-10 } },
      { l:'② 무력을 실어 골조 사이를 뛰어 빗물 통에 간다.', k:'evade', dc:14, cost:{ might:18 },
        ok:`골조와 골조 사이를 뛰었다. 다리에 힘을 다 실었다. 세 번 뛰고 빗물 받이 옆에 매달렸다.<br><br>받이 끝 통에 빗물이 고였다. 유리 지붕 위로 받은 물이다. 균이 닿지 않았다. 맑다.<br>수통을 채웠다. 뚜껑을 꼭 닫았다.<br><br>내려가는 길에 아래를 봤다. 다들 입을 천으로 막고 이쪽 물을 기다린다.`,
        ng:`둘째 뛰기에서 발이 유리를 디뎠다.<br><br>유리가 금이 갔다. 금 사이로 하얀 실이 올라왔다. 위쪽에도 있었다. 손을 짚어 다음 골조로 넘어갔다.<br>손바닥에 실이 붙었다. 긁어냈다. 긁은 자리가 가렵다.`,
        win:{ exp:18, item:'맑은 물' }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C4', t:'온실 — 정원사를 입은 것',
    x:`정원사가 일하고 있다. 가위로 가지를 친다.<br><br>
    가까이 가니 정원사가 아니다. 정원사 옷 안에 하얀 것이 차 있다. 모자 밑으로 갓이 비져나왔다. 얼굴 자리에 주름이 겹겹이다.<br>
    그것이 고개를 돌렸다. 가위를 든 채 이쪽으로 온다. 걸음이 사람 걸음이다. 사람이었던 때를 기억한다.<br><br>
    동료들이 무기를 든다. 가위가 길다.`,
    o:[
      { l:'① 가위가 닿기 직전에 뒤로 넘는다.', k:'evade', dc:15,
        ok:`가위가 벌어졌다. 이쪽 목 높이다. 닫히기 직전에 뒤로 넘었다.<br><br>가위가 빈 데를 잘랐다. 이쪽은 한 바퀴 돌아 그것의 뒤에 내렸다. 그것이 사람처럼 뒤를 돌아본다. 사람보다 느리다.<br>동료들이 그 틈에 다리를 쳤다. 정원사 옷이 무너지며 하얀 것이 쏟아졌다.<br><br>쏟아진 것이 다시 모이기 전에 불을 붙였다.`,
        ng:`넘는 순간 가위가 아래로 내려왔다. 사람은 그렇게 안 휘두른다.<br><br>정강이가 베였다. 넘어서 떨어졌다. 그것이 쓰러진 이쪽 위로 섰다. 모자 밑 갓에서 가루가 떨어진다.<br>동료들이 밀어냈다. 숨을 참았는데 조금 들어왔다. 입안이 쓰다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 넘으면서 모자를 차 떨어뜨린다.', k:'gaze', dc:14,
        ok:`그것을 넘으며 발끝으로 모자를 걷어찼다.<br><br>모자가 날아갔다. 갓이 드러났다. 갓 밑동에 굵은 줄기가 하나 있다. 옷 안 전부가 그 줄기에 매달렸다.<br>내려서며 외쳤다. 밑동이다. 동료의 칼이 거기로 들어갔다.<br><br>정원사 옷이 바람 빠지듯 주저앉았다. 가위가 한 번 더 닫혔다. 아무것도 안 잘렸다.`,
        ng:`모자를 찼는데 모자 안이 꽉 차 있었다.<br><br>발이 갓에 박혔다. 가루가 터졌다. 얼굴에 정통으로.<br>물러나 한참 기침했다. 눈이 따갑다. 밑동은 못 봤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-10, mind:-10 } },
      { l:'③ 무력을 실어 선반 위에서 내려찍는다.', k:'break', dc:15, cost:{ might:20 },
        ok:`화분 선반을 타고 올랐다. 그것이 이쪽을 올려다봤다. 모자 챙이 젖혀졌다.<br><br>뛰어내리며 무게와 힘을 다 실어 갓을 찍었다. 갓이 반으로 갈라졌다.<br>정원사 옷이 무릎을 꿇었다. 가위를 놓았다. 놓는 손짓이 사람 같았다.<br><br>가위는 동료가 챙겼다. 잘 든다.`,
        ng:`뛰어내리는데 그것이 가위를 위로 들었다.<br><br>몸을 틀어 날을 피했다. 갓을 못 찍고 어깨로 떨어졌다. 하얀 것 위로.<br>굴러 나왔다. 어깨에 하얀 실이 엉겼다. 떼어 내니 피가 묻어 나온다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-18, spirit:-6 } }
    ] },

  { at:'C4', t:'온실 — 포자 주머니 사이',
    x:`통로 양옆에 주머니가 줄지어 났다. 사람 머리만 하다. 표면이 팽팽하다.<br><br>
    앞서 간 쥐가 하나를 스쳤다. 주머니가 터졌다. 가루가 쥐를 덮었다. 쥐가 멈췄다. 그대로 하얘졌다.<br>
    주머니 사이는 한 발 너비다. 주머니들이 조금씩 부푼다. 그 한 발도 줄어든다.<br><br>
    통로 끝 화분대에 약초가 아직 초록이다. 유리 덮개 안이다.`,
    o:[
      { l:'① 손으로 짚고 거꾸로 서서 건넌다.', k:'evade', dc:14,
        ok:`몸이 넓은 데는 어깨다. 손은 좁다. 거꾸로 섰다.<br><br>손바닥 둘을 한 줄로 놓으며 걸었다. 다리는 위로 모았다. 주머니가 어깨 높이에 있다. 어깨는 위에 있지 않다. 다리 사이로 주머니 꼭지가 스칠 듯 지나간다.<br>끝에서 다리를 내리고 섰다. 유리 덮개를 열었다. 약초 잎이 단단하다.<br><br>손바닥에 균이 묻었다. 장갑을 벗어 버렸다. 장갑이 바닥에서 하얘졌다.`,
        ng:`손을 옮기다 팔이 떨렸다.<br><br>다리가 기울었다. 발끝이 주머니를 건드렸다. 터졌다. 가루가 다리부터 쏟아졌다.<br>몸을 굴려 빠졌다. 숨은 참았다. 다리가 하얗다. 털어 내는 데 한참 걸렸다.`,
        win:{ exp:18, item:'약초 뭉치' }, lose:{ hp:-12, mind:-8 } },
      { l:'② 숨을 참고 몸을 낮춰 굴러 지난다.', k:'steady', dc:14,
        ok:`숨을 크게 쉬고 멈췄다. 몸을 공처럼 말아 통로 바닥을 굴렀다.<br><br>주머니는 높이 달렸다. 바닥은 비었다. 굴러서 지났다. 끝에서 일어서서 숨을 내쉬었다.<br>뒤를 보니 주머니 하나가 이쪽이 지나간 바람에 흔들리고 있다. 안 터졌다.<br><br>참은 숨이 가슴에서 아프다. 아픈 정도면 된다.`,
        ng:`구르다 중간에 숨이 터졌다.<br><br>들이마셨다. 가루가 아직 공기에 떠 있었다. 목이 막혔다.<br>기어서 나왔다. 기침에 하얀 것이 섞여 나왔다. 동료가 등을 두드렸다.`,
        win:{ exp:15, dream:1 }, lose:{ mind:-12, spirit:-6 } }
    ] },

  { at:'C', t:'사냥 — 날뛰는 등 위',
    x:`큰 것이 날뛴다. 머리를 흔들고 몸을 비튼다.<br><br>
    동료들이 다가가지 못한다. 흔드는 머리에 맞으면 뼈가 남지 않는다.<br>
    곡예사는 흔들리는 것 위에 서는 일을 했다. 흔들리는 말, 흔들리는 줄, 흔들리는 사다리.<br><br>
    이것도 흔들리는 것이다. 이빨이 있을 뿐이다.`,
    o:[
      { l:'① 등에 올라타 버틴다.', k:'evade', dc:16, wake:1,
        ok:`몸을 비트는 박자에 맞춰 옆구리를 디디고 등에 올랐다.<br><br>그것이 미친 듯이 흔든다. 붙잡지 않았다. 흔드는 쪽 반대로 무게를 옮겼다. 왼쪽으로 비틀면 오른발, 머리를 쳐들면 앞으로.<br>그것이 이쪽을 떨어뜨리려고 머리를 등 쪽으로 돌렸다. 목이 드러났다. 동료들이 그 목으로 들어갔다.<br><br>흔들리는 데서 버티던 몸이, 흔드는 것의 고개를 이쪽이 원하는 데로 돌렸다. 위에 서 있는 쪽이 모는 쪽이다.`,
        ng:`세 번은 버텼다. 네 번째에 그것이 뒹굴었다.<br><br>등이 바닥이 됐다. 그 아래에 이쪽이 깔렸다. 숨이 한꺼번에 빠졌다.<br>그것이 일어서는 사이 기어 나왔다. 갈비 한쪽이 숨 쉴 때마다 걸린다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-18, mind:-6 } },
      { l:'② 무력으로 뿔을 잡고 머리를 비튼다.', k:'steady', dc:15, cost:{ might:20 },
        ok:`흔드는 머리가 이쪽 쪽으로 올 때 뿔을 잡았다. 두 손. 힘을 다 실었다.<br><br>머리에 실려 들렸다. 놓지 않았다. 내려올 때 발을 바닥에 박고 비틀었다.<br>그것의 목이 돌아갔다. 무릎이 꺾였다. 동료들이 덮쳤다.<br><br>손바닥이 뿔 모양으로 벗겨졌다.`,
        ng:`뿔을 잡자마자 머리가 위로 쳐들렸다.<br><br>손이 떨어졌다. 높이 떨어졌다. 몸을 돌려 발로 받으려 했는데 늦었다. 옆구리로 떨어졌다.<br>동료가 끌어냈다. 머리가 한참 울렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-8 } }
    ] },

  { at:'C', t:'무너진 층계 — 떨어질 높이',
    x:`층계가 중간에서 끊겼다. 아래층 바닥까지 사람 키 셋이다.<br><br>
    뒤에서 그것들이 온다. 발소리가 많다. 줄을 내릴 시간은 없다.<br>
    곡예사는 떨어지는 법을 먼저 배운다. 사람 키 셋이면 배운 높이다.<br><br>
    아래 바닥에 잡아 둔 것의 껍데기가 흩어져 있다. 모서리가 날카롭다.`,
    o:[
      { l:'① 뛰어내려 굴러 받는다.', k:'evade', dc:14,
        ok:`끝에서 뛰었다. 무릎을 접어 두고 떨어졌다.<br><br>발이 닿는 순간 무릎을 풀고 옆으로 굴렀다. 어깨, 등, 엉덩이. 껍데기 사이 빈 자리만 굴렀다.<br>일어섰다. 다친 데가 없다. 위에서 동료들이 하나씩 뛰어내린다. 이쪽이 받았다.<br><br>마지막 사람이 내리고 위를 봤다. 끊긴 층계 끝에 그것들이 모여 아래를 내려다본다. 안 뛴다.`,
        ng:`구르는 자리에 껍데기 조각이 있었다.<br><br>등이 그 위를 지나갔다. 옷과 살이 같이 찢겼다. 일어서니 등이 뜨겁다.<br>위에서 그것들이 끊긴 끝에 모였다. 이쪽 피 냄새를 맡는다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 끊긴 난간에 줄을 걸어 하나씩 내린다.', k:'fix', dc:13,
        ok:`난간 기둥에 줄을 두 번 감았다. 곡예단 매듭이다. 당길수록 조인다.<br><br>동료들을 하나씩 내렸다. 줄을 손에 감고 무게를 받았다. 발소리가 가까워진다. 마지막에 이쪽은 줄을 타고 미끄러져 내렸다.<br>줄은 매듭째 두고 왔다. 위에서 그것들이 줄을 당긴다. 매듭이 더 조인다.<br><br>그것들은 줄을 탈 줄 모른다.`,
        ng:`셋째 사람을 내릴 때 난간 기둥이 흔들렸다.<br><br>줄이 미끄러졌다. 그 사람이 떨어졌다. 이쪽 손바닥으로 줄이 타고 지나갔다.<br>그 사람은 껍데기 위에 떨어졌다. 살았다. 이쪽 손바닥이 다 벗겨졌다.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-12, spirit:-8 } }
    ] },

  { at:'C', t:'사냥 뒤 — 떨어지는 사람',
    x:`잡은 것이 쓰러지면서 벽을 쳤다. 벽 위 턱에 있던 동료가 떨어진다.<br><br>
    턱이 높다. 아래 바닥은 돌이다. 그 사람은 곡예사가 아니다. 떨어지는 법을 모른다.<br>
    곡예사는 떨어지는 것을 받는 법도 배운다. 받는 쪽이 같이 떨어져 주는 것이다.<br><br>
    두 박자 남았다.`,
    o:[
      { l:'① 받으면서 같이 구른다.', k:'bond', dc:15,
        ok:`밑으로 뛰어들어 팔을 벌렸다. 그 사람 허리를 받는 순간 받지 않았다. 같이 무너졌다.<br><br>무게를 이쪽 몸으로 돌려 바닥에 굴렸다. 한 바퀴, 두 바퀴. 떨어진 힘이 구르는 데로 다 빠져나갔다.<br>멈췄다. 그 사람이 이쪽 위에서 눈을 깜빡인다. 어디도 안 부러졌다.<br><br>이쪽 팔꿈치가 조금 까졌다. 그게 다다.`,
        ng:`받는데 그 사람이 버둥거렸다. 무게가 엉뚱하게 실렸다.<br><br>같이 넘어졌다. 구르지 못했다. 이쪽 무릎이 돌에 찍혔다. 그 사람 팔꿈치가 이쪽 얼굴을 쳤다.<br>둘 다 살았다. 둘 다 한동안 못 일어났다.`,
        win:{ exp:18, dream:2, hp:5 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 무력을 실어 벽을 차고 올라 가로챈다.', k:'evade', dc:15, cost:{ might:18 },
        ok:`벽으로 달려가 차고 올랐다. 다리에 힘을 다 실었다. 떨어지는 사람과 중간에서 만났다.<br><br>그 사람 허리를 감고 몸을 돌려 벽을 다시 찼다. 떨어지는 방향이 아래에서 옆으로 바뀌었다. 옆으로 떨어지면 덜 아프다.<br>쌓인 껍데기 더미 위로 둘이 굴렀다.<br><br>그 사람이 이쪽을 오래 봤다. 뭐라고 말하려다 그만뒀다.`,
        ng:`차고 오르는 박자가 반 늦었다.<br><br>떨어지는 사람이 이쪽 위로 떨어졌다. 둘이 같이 바닥에 떨어졌다. 이쪽이 아래다.<br>그 사람은 멀쩡하다. 이쪽 어깨에서 소리가 났다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-18, mind:-4 } }
    ] },

  { at:'C', t:'끝 무렵 — 사슬 위',
    x:`오래 사냥했다. 몸이 굳었다. 땀이 식었다.<br><br>
    마지막 구덩이에 사슬 하나가 걸려 있다. 아래에서 잡다 만 것이 기다린다. 숨소리가 길다. 다쳐서 화가 났다.<br>
    곡예사는 몸이 풀렸을 때 줄을 탄다. 굳은 몸으로 타는 줄은 없다. 그렇게 배웠다.<br><br>
    사슬이 한 번 흔들렸다. 아래의 것이 흔든 것이다.`,
    o:[
      { l:'① 굳은 몸 그대로 사슬 위에 선다.', k:'evade', dc:15, wake:1,
        ok:`사슬에 올라섰다. 다리가 뻣뻣하다. 무릎이 덜 굽는다.<br><br>그런데 발바닥이 사슬 고리를 하나씩 알았다. 굽지 않는 무릎 대신 발목이 받았다. 발목이 안 되면 엉덩이가, 엉덩이가 안 되면 팔이. 어디가 굳든 남은 데가 대신 받는다.<br>아래의 것이 사슬을 흔들었다. 흔드는 대로 서 있었다. 건넜다.<br><br>균형은 풀린 몸에 있는 게 아니었다. 이제 버릇이다. 지친 날에도 버릇은 안 지친다.`,
        ng:`셋째 고리에서 무릎이 안 굽었다.<br><br>흔들림을 못 받았다. 사슬에서 미끄러져 양팔로 매달렸다. 아래에서 그것이 뛰어올랐다. 발뒤꿈치를 이빨이 스쳤다.<br>손으로 사슬을 타고 건넜다. 팔이 다 풀렸다. 뒤꿈치에서 피가 흐른다.`,
        win:{ exp:25, dream:4 }, lose:{ hp:-16, spirit:-8 } },
      { l:'② 사슬에 매달려 손으로 건넌다.', k:'steady', dc:14,
        ok:`사슬을 두 손으로 잡고 매달렸다. 다리를 사슬에 감았다. 등이 아래를 향한다.<br><br>손 하나, 다리 하나. 천천히 건넜다. 아래의 것이 뛰어오른다. 닿지 않는 높이다. 이쪽은 등으로 그 숨을 느꼈다.<br>건너편에 닿았다.<br><br>곡예라고 하기는 어렵다. 살아서 건넜다.`,
        ng:`반쯤 가서 사슬 고리 하나가 벌어졌다.<br><br>사슬이 한 뼘 내려앉았다. 등이 아래로 처졌다. 그것이 뛰어 등을 긁었다.<br>이를 악물고 건넜다. 등에 줄이 셋 그어졌다.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-14, mind:-6 } }
    ] }
]);

// ── 경신술사 (lightfoot) · 내공 ──────────────
kJob('lightfoot', 'C', [
  { at:'C', t:'사냥터 — 바닥을 듣는 것',
    x:`그것은 눈이 없다. 머리 전체가 넓적한 판이다. 판을 바닥에 대고 있다.<br><br>
    바닥이 울리면 판이 그쪽으로 돈다. 그리고 판 가장자리가 열린다. 입이다. 판 둘레 전부가 입이다.<br>
    동료들이 무기를 들고 굳었다. 한 걸음이면 들킨다.<br><br>
    경신술사는 걸음의 무게를 덜어 쓴다. 덜어 낸 걸음은 바닥이 모른다.`,
    o:[
      { l:'① 바닥이 모르게 그것 뒤로 돈다.', k:'evade', dc:15, wake:1,
        ok:`발을 내려놓는 게 아니라 발을 바닥 위에 잠깐 맡겼다. 맡긴 무게를 바로 거뒀다.<br><br>그것의 둘레를 반 바퀴 돌았다. 판이 한 번도 안 움직였다. 뒤에서 일부러 한 번 바닥을 굴렀다. 판이 돌았다. 동료들 쪽으로 등을 보이며.<br>등은 판처럼 넓지 않다. 동료들의 날이 다 들어갔다.<br><br>돌아오는 길에 이쪽 발소리가 이쪽에게도 안 들렸다. 들리지 않는 걸음이 이제 걸음의 기본이 됐다.`,
        ng:`열째 걸음에 무게가 조금 남았다.<br><br>판이 이쪽으로 돌았다. 가장자리가 열렸다. 뛰었다. 판 끝이 종아리를 물었다 놓았다.<br>동료들이 그 틈에 쳤다. 종아리에 둥근 이 자국이 반달로 남았다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 내공을 끌어올려 둘레를 빠르게 돌며 끈다.', k:'evade', dc:14, cost:{ qi:18 },
        ok:`내공을 다리에 몰아 일부러 바닥을 울리며 달렸다. 판이 쫓는다. 판이 돌 때는 이쪽이 이미 없다.<br><br>세 바퀴를 돌렸다. 그것이 판을 계속 돌리다 몸이 꼬였다. 옆구리가 들렸다.<br>동료들이 들린 옆구리로 들어갔다.<br><br>멈추니 다리가 후들거린다. 그것은 아직 판을 돌리고 있었다. 천천히. 그러다 멈췄다.`,
        ng:`둘째 바퀴에서 내공이 엇나갔다. 발이 무거워졌다.<br><br>판이 따라잡았다. 가장자리가 발을 덮었다. 신발째 빨려 들어갔다. 발을 뺐다. 신발은 못 뺐다.<br>맨발로 남은 사냥을 했다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C', t:'굴 — 끈끈한 바닥',
    x:`바닥이 끈끈하다. 한 걸음 디디면 떼는 데 힘이 든다.<br><br>
    벽에 뭔가 붙어 있다. 바닥에서 뭔가 버둥대다 굳은 것들이다. 쥐, 새, 사람 손.<br>
    굴 안쪽에서 끈끈한 것을 깐 주인이 나온다. 천천히. 급할 게 없다.<br><br>
    경신술사는 닿은 것이 붙기 전에 뗀다. 붙는 데 걸리는 시간보다 짧게.`,
    o:[
      { l:'① 붙기 전에 발을 떼며 달린다.', k:'evade', dc:14,
        ok:`디디고, 붙기 전에 뗐다. 발바닥에 끈끈한 것이 닿는 소리만 났다. 쩍, 쩍.<br><br>굴을 끝까지 달렸다. 안쪽에서 나오던 것이 이쪽을 봤다. 이쪽이 붙지 않으니 다시 들어갔다. 붙지 않는 것은 먹이가 아니다.<br>밖에서 발바닥을 봤다. 끈끈한 것이 얇게 묻었다. 돌에 문질러 떼어 냈다.<br><br>동료들은 이쪽이 깐 판자를 밟고 왔다.`,
        ng:`일곱째 걸음에서 발이 늦었다.<br><br>붙었다. 다른 발로 떼려다 그 발도 붙었다. 안쪽에서 주인이 나온다. 급할 게 없다는 걸음으로.<br>동료들이 신발 끈을 잘라 줬다. 맨발로 빠져나왔다. 발바닥 살갗이 얇게 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-8 } },
      { l:'② 내공을 발바닥에 돌려 끈끈한 것을 녹인다.', k:'steady', dc:14, cost:{ qi:16 },
        ok:`가부좌는 못 튼다. 선 채로 숨을 단전에 모아 발바닥으로 내렸다.<br><br>발바닥이 뜨거워졌다. 끈끈한 것이 뜨거운 데서 묽어진다. 묽어진 데로 발이 미끄러져 빠졌다.<br>천천히 걸었다. 걸을 때마다 발밑이 묽어졌다. 뒤에 길이 났다. 동료들이 그 길로 왔다.<br><br>안쪽의 것이 묽어진 바닥을 보고 오래 머뭇거렸다.`,
        ng:`내공이 발바닥까지 내려가기 전에 무릎에서 막혔다.<br><br>발은 차가운 채 붙었다. 무릎만 뜨겁다. 억지로 뗐다. 발목이 접질렸다.<br>절뚝이며 나왔다. 끈끈한 것이 발목까지 감겼다.`,
        win:{ exp:16, dream:1, hp:5 }, lose:{ hp:-12, mind:-8 } },
      { l:'③ 벽에 붙은 것들 사이 마른 자리를 찾는다.', k:'sense', dc:13,
        ok:`벽 쪽을 봤다. 붙은 것들이 버둥대다 굳은 자리는 바닥이 말라 있다. 버둥대며 다 묻혀 갔다.<br><br>그 자리만 골라 디뎠다. 굳은 쥐 옆, 굳은 새 옆. 마지막은 굳은 손 옆.<br>손이 이쪽 발목을 잡지는 않았다. 다 굳었다.<br><br>남이 남긴 자리가 길이 됐다. 고맙다고 하기는 어렵다.`,
        ng:`마른 줄 알고 디딘 자리가 겉만 말랐다.<br><br>발이 빠졌다. 아래는 더 끈끈하다. 굳은 손 바로 옆이다. 손가락이 조금 움직인 것 같았다.<br>끌려 나왔다. 그 손이 정말 움직였는지는 아무도 확인하지 않았다.`,
        win:{ exp:14, dream:1 }, lose:{ mind:-8, spirit:-10 } }
    ] },

  { at:'C', t:'사냥 — 빠른 것',
    x:`그것은 빠르다. 다리가 여섯이다. 벽도 천장도 바닥처럼 달린다.<br><br>
    동료들 화살이 늘 그것이 있던 자리에 꽂힌다. 그것은 늘 다음 자리에 있다.<br>
    누군가 그것과 같이 달려야 한다. 그것이 어디로 꺾는지 먼저 외쳐 줄 사람이.<br><br>
    경신술사의 다리는 이럴 때 쓰라고 있다.`,
    o:[
      { l:'① 그것과 나란히 달리며 꺾는 데를 외친다.', k:'evade', dc:15, wake:1,
        ok:`그것 옆에 붙어 달렸다. 벽으로 오르면 이쪽도 벽을 디뎠다. 세 걸음이면 떨어지지 않는다.<br><br>그것이 꺾기 직전에 다리 하나가 먼저 힘을 뺀다. 거기서 외쳤다. 왼쪽, 위. 화살이 이쪽 말보다 늦게 날아간다. 그래도 그것이 갈 자리에 날아간다.<br>세 대째에 그것이 떨어졌다. 이쪽은 그 옆에 섰다. 숨이 안 찼다.<br><br>빠른 것을 쫓는 다리가 아니라 빠른 것과 같은 박자로 사는 다리가 됐다. 이쪽 걸음이 그것의 걸음을 미리 알았다.`,
        ng:`천장으로 오르는 데서 떨어졌다. 세 걸음이 모자랐다.<br><br>등으로 떨어졌다. 그것이 천장에서 이쪽 위로 내려왔다. 다리 여섯이 몸을 눌렀다.<br>동료들이 몰려와 떼어 냈다. 가슴에 다리 자국이 여섯.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-8 } },
      { l:'② 달리지 않고 그것이 돌아올 길목을 알린다.', k:'bond', dc:14,
        ok:`그것을 쫓지 않고 봤다. 같은 둘레를 돈다. 다섯 바퀴째에 알았다. 늘 같은 기둥을 짚고 꺾는다.<br><br>동료들에게 기둥을 가리켰다. 다들 기둥을 겨눴다. 그것이 기둥을 짚었다. 화살이 기둥에 같이 닿았다.<br>그것이 기둥에 꿰였다.<br><br>빨리 달리는 것도 버릇이 있다. 달리는 사람이 그걸 안다.`,
        ng:`기둥을 가리켰는데 그것이 이번엔 다른 기둥을 짚었다.<br><br>화살이 빈 기둥에 꽂혔다. 그것이 가리키는 이쪽 팔을 보고 이쪽에게 왔다.<br>팔을 물렸다. 동료들이 쫓았다. 팔이 한참 안 펴졌다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C', t:'외벽 — 숨 한 번 길이',
    x:`벼랑 벽을 따라 지나야 한다. 발 디딜 턱은 듬성듬성하다.<br><br>
    벽 중간에 구멍이 있다. 안에서 큰 것이 숨을 쉰다. 내쉴 때마다 뜨거운 바람이 벽을 쓸고 지나간다. 사람을 털어 낸다.<br>
    들이쉬고 내쉬는 사이가 길다. 그 사이에 구멍 앞을 지나면 된다.<br><br>
    턱과 턱 사이가 멀다. 걸어서는 숨 한 번 안에 못 지난다.`,
    o:[
      { l:'① 내공을 끌어올려 벽을 달려 지난다.', k:'evade', dc:15, cost:{ qi:20 },
        ok:`그것이 들이쉬기 시작할 때 내공을 다리에 몰았다. 들이쉬는 바람이 이쪽을 당긴다. 그 당김을 등에 업고 벽을 디뎠다.<br><br>턱이 없는 데도 디뎠다. 벽을 옆으로 달렸다. 구멍 앞을 지날 때 안에서 눈 하나가 떴다.<br>건너편 턱에 섰다. 등 뒤로 뜨거운 숨이 벽을 쓸었다. 이쪽이 있던 자리까지.<br><br>벽에 발자국이 그을려 남았다. 다섯.`,
        ng:`구멍 앞에서 내공이 끊겼다.<br><br>벽에서 미끄러졌다. 턱 하나를 잡고 매달렸다. 숨이 나왔다. 뜨겁다. 손등이 익는다.<br>놓지 않았다. 숨이 그치고 기어서 건넜다. 손등이 다 일어났다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 턱마다 엎드려 숨이 지나가길 기다린다.', k:'steady', dc:14,
        ok:`턱에 엎드려 벽에 붙었다. 숨이 지나간다. 등이 뜨겁다. 버텼다.<br><br>숨이 그치면 다음 턱으로 옮겼다. 다시 엎드렸다. 일곱 번.<br>오래 걸렸다. 등이 다 그을렸다. 건넜다.<br><br>빨리 가는 것이 경신이다. 살아서 가는 것은 그 앞이다.`,
        ng:`넷째 턱이 좁았다. 다 엎드려지지 않았다.<br><br>숨이 이쪽 다리를 털었다. 다리가 벽에서 떴다. 손가락 끝으로 버텼다.<br>숨이 지나가고 올라왔다. 손톱 끝이 다 갈렸다.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-14, spirit:-6 } }
    ] },

  { at:'C1', t:'탕박조 — 떠 있는 판자',
    x:`털 뽑는 탕이다. 길쭉한 쇠 통에 물이 끓는다. 김이 천장까지 찬다.<br><br>
    탕 위로 판자가 떠 있다. 일하던 사람들이 밟고 다니던 판자다. 판자 사이로 가끔 뭔가 떠올랐다 가라앉는다. 털 없는 등.<br>
    탕을 건너면 다음 라인이다. 돌아가면 한참이다. 돌아가는 길에는 갈고리가 돈다.<br><br>
    판자는 사람 무게를 받으면 잠긴다. 잠기는 데 걸리는 시간이 있다.`,
    o:[
      { l:'① 판자가 잠기기 전에 다음 판자로 간다.', k:'evade', dc:15,
        doom:{ title:'탕박조', what:'뜨거운 탕 속으로 끌려 들어갑니다', dc:15, sec:55,
          text:`첫 판자, 둘째 판자. 잠기기 전에 떠났다. 김 때문에 앞이 안 보인다. 발로 보고 갔다.<br><br>넷째 판자가 판자가 아니었다. 털 없는 등이었다. 디디자 뒤집혔다. 손이 나와 이쪽 발목을 잡았다.<br>허리까지 잠겼다. 뜨겁다. 끓는 데서 손이 안 놓는다. 아래로 당긴다.<br><br>동료들이 판자 끝에서 손을 뻗는다. 김 속이라 이쪽 손이 어디 있는지 모른다.`,
          dieText:`경신술사는 잠기기 전에 떠난다.<br><br>잠기지 않는 것을 디뎠다. 그것은 처음부터 안 떠 있었다. 아래서 올라온 것이었다.<br>탕 위에 판자가 하나 늘었다. 하얗게 익은 등이다.` },
        ok:`첫 판자에 발을 올리고, 잠기기 시작하는 걸 발바닥으로 느끼자마자 떠났다.<br><br>넷째 자리에 판자처럼 생긴 등이 떠 있었다. 판자는 김 속에서 젖은 소리를 낸다. 저건 소리가 없다. 건너뛰었다.<br>다섯째 판자를 디디고 끝에 내렸다. 뒤에서 등이 뒤집혔다. 손 하나가 빈 데를 움켜쥐고 가라앉았다.<br><br>건너편에서 다리 탕을 식혔다. 발바닥이 붉다. 그 정도다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 내공을 실어 탕 가장자리 턱을 단숨에 달린다.', k:'evade', dc:14, cost:{ qi:18 },
        ok:`탕 가장자리 쇠 턱은 손가락 두 마디 너비다. 뜨겁다. 오래 디디면 신발이 탄다.<br><br>내공을 끌어올려 단숨에 달렸다. 턱에 발이 닿는 시간을 줄였다. 신발 바닥에서 연기가 조금 났다. 그뿐이다.<br>끝까지 달렸다. 김 속에서 털 없는 등들이 이쪽 쪽으로 몰렸다가 흩어졌다.<br><br>신발 바닥에 쇠 턱 자국이 줄무늬로 탔다.`,
        ng:`반쯤 달렸을 때 김이 숨으로 들어왔다. 내공이 흐트러졌다.<br><br>발이 턱에 오래 머물렀다. 신발이 녹아 붙었다. 떼어 내며 달렸다. 발바닥이 데었다.<br>탕 안에서 손 하나가 턱 위로 올라와 이쪽이 지나간 자리를 더듬었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C1', t:'계류장 — 몰이 통로',
    x:`좁은 몰이 통로다. 짐승을 한 줄로 몰아 라인으로 보내던 길이다.<br><br>
    통로 저 끝에서 떼가 온다. 잘렸다가 다시 자란 것들이다. 다리가 넷인 것, 다섯인 것, 다리가 한쪽에만 난 것. 서로 밀며 이쪽으로 쏟아진다.<br>
    통로 중간에 철문이 있다. 열려 있다. 닫으면 떼가 막힌다. 떼보다 먼저 닿아야 한다.<br><br>
    경신술사가 제일 먼저 뛰었다. 다른 사람은 거리를 셌다.`,
    o:[
      { l:'① 떼보다 먼저 철문에 닿는다.', k:'evade', dc:15, wake:1,
        ok:`첫걸음부터 무게를 다 덜었다. 발이 바닥을 미는 게 아니라 바닥이 발을 지나갔다.<br><br>떼가 앞에서 온다. 이쪽도 그쪽으로 간다. 철문까지 이쪽이 열 걸음, 떼가 열다섯 걸음. 열 걸음이 다섯 걸음처럼 지나갔다.<br>철문을 닫았다. 빗장을 걸었다. 철문에 떼가 부딪쳤다. 철문이 울었다. 버텼다.<br><br>뒤에서 동료들이 이제 막 출발하고 있었다. 이쪽이 셋을 셀 때 남은 하나를 센다. 다리가 시간을 접어 쓰기 시작했다.`,
        ng:`철문 한 걸음 앞에서 떼 앞줄이 닿았다.<br><br>문을 반만 닫았다. 반 열린 데로 다리 다섯인 것이 밀려들어 이쪽 허리를 받았다. 철문과 그것 사이에 끼었다.<br>동료들이 와서 문을 같이 밀었다. 허리가 저리다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-18, mind:-6 } },
      { l:'② 통로 옆 칸막이 위로 올라가 떼를 흘려보낸다.', k:'hide', dc:14,
        ok:`칸막이 위로 올라가 엎드렸다. 동료들도 따라 올랐다.<br><br>아래로 떼가 흘렀다. 다리가 어디 붙었든 앞만 보고 간다. 라인 쪽으로. 몸이 기억하는 길이다.<br>다 지나가고 내려왔다. 통로 바닥에 떨어져 나온 다리가 몇 개 남아 꿈틀댄다.<br><br>밟지 않았다. 밟으면 붙을 것 같았다.`,
        ng:`칸막이가 낡았다. 떼가 부딪치자 흔들렸다.<br><br>떨어졌다. 떼 위로. 등을 밟히며 한참 실려 갔다. 칸막이 끝을 잡고 빠져나왔다.<br>등에 발굽 자국이 몇 개인지 셀 수 없다.`,
        win:{ exp:16, dream:1 }, lose:{ hp:-16, spirit:-6 } },
      { l:'③ 뒤처진 동료의 팔을 잡고 같이 뛴다.', k:'bond', dc:14,
        ok:`제일 느린 동료 팔을 잡았다. 이쪽 걸음에 그 사람 무게를 얹었다.<br><br>둘이 한 사람 무게로 뛰었다. 덜어 낸 무게를 나눠 썼다. 칸막이 끝 비상문까지 갔다. 둘 다 들어갔다. 떼가 문 앞을 지나갔다.<br>그 사람이 숨을 몰아쉰다. 이렇게 빨리 뛴 적이 없다고 했다.<br><br>이쪽도 남을 업고 이렇게 뛴 적은 없다.`,
        ng:`팔을 잡았는데 그 사람이 넘어졌다.<br><br>같이 넘어졌다. 떼가 지나간다. 이쪽이 그 사람 위에 엎드렸다. 등이 다 밟혔다.<br>지나가고 나서 그 사람은 멀쩡했다. 이쪽은 일어나지 못했다. 한참.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-18, mind:-4 } }
    ] },

  { at:'C1', t:'냉동 창고 — 녹는 바닥',
    x:`냉동 창고 바닥은 얼음이다. 얼음 위에 물이 얇게 고였다. 녹는 중이다.<br><br>
    천장에 걸린 고깃덩이도 녹는다. 녹은 데부터 움직인다. 한쪽 끝이 꿈틀거린다. 언 데는 아직 가만히 있다.<br>
    창고 구석에 배급 상자가 있다. 일하던 사람들 몫이었다. 뚜껑에 서리가 꼈다.<br><br>
    빨리 다녀와야 한다. 녹는 것들이 다 녹기 전에.`,
    o:[
      { l:'① 얼음 위를 미끄러지듯 다녀온다.', k:'evade', dc:14,
        ok:`발을 들지 않았다. 얼음 위를 밀었다. 무게를 덜면 미끄러짐도 가볍다.<br><br>매달린 덩이들 사이를 지났다. 녹은 끝이 이쪽 쪽으로 휜다. 휘는 속도보다 이쪽이 빨랐다.<br>상자를 열었다. 말린 고기가 언 채 들어 있다. 언 것은 움직이지 않는다. 품에 넣고 돌아왔다.<br><br>나오면서 돌아보니 덩이 하나가 갈고리에서 떨어져 바닥을 기고 있다. 이쪽 지나간 자리를 따라.`,
        ng:`돌아오는 길에 물이 고인 데서 발이 붙었다. 얼음이 다시 언 것이다.<br><br>멈췄다. 머리 위 덩이 하나가 녹은 끝으로 이쪽 목덜미를 더듬었다. 미지근하다.<br>신발을 비틀어 빼고 나왔다. 목덜미에 덩이 살결 자국이 남았다.`,
        win:{ exp:16, item:'말린 고기' }, lose:{ hp:-10, spirit:-10 } },
      { l:'② 내공을 돌려 몸을 데우고 천천히 다녀온다.', k:'steady', dc:14, cost:{ qi:16 },
        ok:`내공을 몸에 돌렸다. 손끝까지 데웠다. 언 손으로는 상자를 못 연다.<br><br>천천히 걸었다. 녹는 덩이들은 빠른 것에 휜다. 천천히 가는 것은 모른다.<br>상자 뚜껑을 손으로 녹여 열었다. 말린 고기 꾸러미가 있다. 꺼냈다.<br><br>돌아오는 동안 몸에서 김이 났다. 덩이 하나가 김 쪽으로 휘었다가 멈췄다.`,
        ng:`몸을 데우자 몸에서 김이 났다. 김이 덩이들에 닿았다.<br><br>닿은 데부터 녹았다. 이쪽 둘레만 녹는다. 덩이들이 한꺼번에 꿈틀거렸다.<br>뛰어나왔다. 팔에 녹은 살이 떨어졌다. 미지근하다.`,
        win:{ exp:15, item:'말린 고기' }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C2', t:'가마실 — 깨진 사기 바닥',
    x:`가마실 바닥에 사기 조각이 깔렸다. 굽다 깨진 인형들이다. 발목까지 쌓였다.<br><br>
    가마 옆에 굽기 전의 인형들이 줄지어 서 있다. 눈을 감고 있다. 조각이 밟히는 소리가 나면 눈을 뜬다. 하나가 뜨면 옆이 뜬다.<br>
    조각은 밟으면 운다. 사기는 원래 그렇다.<br><br>
    경신술사는 우는 자갈 위를 걸어 본 적이 있다. 사기는 자갈보다 잘 운다.`,
    o:[
      { l:'① 조각이 울지 않게 지난다.', k:'evade', dc:15, wake:1,
        ok:`조각 위에 발을 얹었다. 누르지 않았다. 조각이 이쪽 무게를 느끼기 전에 발이 떠났다.<br><br>가마 앞을 지났다. 인형들 눈꺼풀이 한 번 떨렸다. 안 떴다. 조각 하나 안 울었다.<br>가마실 끝 문에 닿았다. 돌아보니 동료들이 문 저편에서 이쪽만 본다. 어떻게 하느냐는 얼굴이다.<br><br>설명할 수가 없었다. 발이 무게를 싣는 법을 잊은 게 아니라, 언제 실을지 고르게 됐다. 이제 바닥이 이쪽을 듣는 건 이쪽이 정할 때뿐이다.`,
        ng:`열둘째 걸음에서 조각 하나가 다른 조각에 기댔다. 기댄 것이 울었다.<br><br>인형 하나가 눈을 떴다. 옆이 떴다. 줄이 다 떴다. 굽지 않은 손들이 이쪽으로 뻗는다. 흙이라 무르다. 무른 손이 세다.<br>뛰어 빠졌다. 팔에 덜 마른 흙이 손 모양으로 붙었다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-12, spirit:-10 } },
      { l:'② 내공을 실어 가마 지붕 위로 건너뛴다.', k:'evade', dc:14, cost:{ qi:18 },
        ok:`내공을 다리에 모아 가마 옆 벽을 디뎠다. 세 걸음 만에 가마 지붕 위다.<br><br>지붕이 뜨겁다. 오래 못 선다. 오래 서지 않았다. 지붕을 건너 반대편으로 내렸다. 조각 더미가 없는 문 앞이다.<br>인형들은 눈을 감은 채다. 가마의 열이 이쪽 소리를 덮었다.<br><br>신발 바닥이 조금 녹았다. 고무 냄새가 난다.`,
        ng:`지붕에 내리는 순간 내공이 흩어졌다. 무게가 한꺼번에 실렸다.<br><br>가마 지붕 벽돌이 한 장 빠졌다. 발이 빠졌다. 안은 불이다. 바로 뺐다.<br>발목이 데었다. 소리에 인형들이 다 눈을 떴다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C2', t:'이 박는 방 — 집게 손',
    x:`방 한가운데 의자가 있다. 의자 위로 쇠 집게가 여럿 매달렸다. 집게는 인형 입에 이를 박는 것이다.<br><br>
    집게가 움직인다. 아무도 안 앉았는데. 빈 의자 위에서 열렸다 닫혔다 한다. 박을 입을 찾는다.<br>
    벽에 작은 서랍이 수백 개다. 서랍마다 이가 든다. 가끔 서랍 하나가 저절로 열린다.<br><br>
    방을 가로지르면 집게 아래를 지나야 한다.`,
    o:[
      { l:'① 집게가 닫히는 박자 사이로 지난다.', k:'evade', dc:14,
        ok:`집게 하나가 열렸다 닫힐 때까지 셌다. 넷. 다음 집게는 다섯. 그다음은 셋.<br><br>셋과 넷 사이, 넷과 다섯 사이를 골라 지났다. 걸음 박자를 집게마다 바꿨다. 집게가 이쪽 귀 옆에서 닫혔다. 빈 것을 물었다.<br>방을 건넜다. 뒤에서 집게들이 한꺼번에 이쪽 쪽으로 돌았다. 늦었다.<br><br>박자가 다른 것 여럿을 지날 때는 이쪽 박자를 버리면 된다.`,
        ng:`셋째 집게가 박자를 건너뛰었다.<br><br>닫히는 집게에 귀가 물렸다. 당긴다. 의자 쪽으로. 몸을 비틀어 뺐다.<br>귓바퀴가 찢어졌다. 집게가 이쪽 피를 물고 의자 위에서 한참 열렸다 닫혔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-8 } },
      { l:'② 저절로 열린 서랍을 뒤진다.', k:'luck', dc:14,
        ok:`열린 서랍 쪽은 집게가 안 온다. 서랍이 열릴 때 집게는 의자를 본다.<br><br>맨 아래 열린 서랍은 이가 아니었다. 기름종이에 싼 꾸러미. 일하던 사람의 도시락이다. 말린 고기가 들었다.<br>서랍을 닫으려는데 위 서랍이 열렸다. 이가 가득하다. 하나가 이쪽을 향해 굴렀다.<br><br>그건 안 주웠다.`,
        ng:`열린 서랍에 손을 넣었다. 안에서 이가 쏟아졌다.<br><br>쏟아진 소리에 집게들이 이쪽으로 돌았다. 서랍 앞에 엎드렸다. 집게가 등 위에서 닫혔다. 옷을 물었다.<br>옷을 찢고 빠져나왔다. 등이 쓸렸다.`,
        win:{ exp:15, item:'말린 고기' }, lose:{ hp:-10, mind:-8 } }
    ] },

  { at:'C2', t:'다락 — 들보 사이의 실',
    x:`다락은 들보만 있다. 들보 사이 바닥은 얇은 널이다. 썩었다.<br><br>
    들보와 들보 사이에 실이 쳐졌다. 거미줄처럼. 실 하나가 떨리면 다락 저쪽 어둠에서 뭔가 고개를 든다. 모든 실이 거기로 모인다.<br>
    들보는 발 반 너비다. 실은 들보 위로도 지나간다. 무릎 높이, 발목 높이.<br><br>
    경신술사는 줄 사이로 몸을 지나게 할 수 있다. 줄이 모르게. 이 줄은 아주 잘 안다.`,
    o:[
      { l:'① 들보 위로 실을 피해 달린다.', k:'evade', dc:16,
        doom:{ title:'실', what:'실에 감겨 용마루로 끌려 올라갑니다', dc:15, sec:55,
          text:`들보 위를 달렸다. 발목 실을 넘고 무릎 실 아래로 빠졌다. 실이 한 가닥도 안 떨렸다.<br><br>셋째 들보에서 실이 먼저 움직였다. 이쪽이 건드린 게 아니다. 저쪽이 실을 당겨 이쪽 발 앞에 놓았다.<br>발목에 감겼다. 끌어올린다. 몸이 거꾸로 들린다. 용마루 어둠 쪽으로. 실이 더 감긴다. 무릎, 허리.<br><br>아래에서 동료들이 실을 자를 칼을 찾는다. 실이 높다.`,
          dieText:`경신술사의 걸음은 줄이 모른다.<br><br>줄을 쥔 쪽은 알았다. 줄을 놓는 것도 쥔 쪽이다.<br>용마루 아래 실 끝에 인형이 하나 늘었다. 발끝이 아직 들보를 찾는 모양이다.` },
        ok:`들보 위를 달렸다. 실은 이쪽이 지나가는 걸 몰랐다. 그런데 셋째 들보에서 실이 혼자 움직였다.<br><br>저쪽이 실을 당겨 이쪽 발 앞에 놓은 것이다. 놓인 실을 디디지 않았다. 실 위를 발끝으로 스치고 넘었다. 실이 아래로 늘어졌다. 저쪽이 당긴 힘이 빈 데로 빠졌다.<br>다락 끝 창틀에 닿았다. 어둠 속에서 뭔가 오래 실을 당겼다 놓았다.<br><br>남이 놓은 줄은 남의 박자다. 그걸 안 밟으면 된다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 실이 덜 모이는 쪽 널을 더듬어 간다.', k:'sense', dc:14,
        ok:`실이 어디로 모이는지 봤다. 다락 가운데로 모인다. 벽 쪽은 실이 성기다.<br><br>벽에 붙어 널 위를 걸었다. 썩은 널은 발끝으로 먼저 눌러 봤다. 단단한 것만 디뎠다.<br>오래 걸렸다. 실은 한 번도 안 떨렸다.<br><br>창틀에 닿아서 가운데를 봤다. 실이 모이는 데 뭔가 앉아 있다. 이쪽을 안 봤다. 아직.`,
        ng:`벽 쪽 널이 썩었다. 발이 빠졌다.<br><br>아래층 천장까지 다리가 내려갔다. 아래에서 뭔가 발을 잡았다. 사기 손이다. 차갑다.<br>들보를 잡고 빼냈다. 정강이에 손톱 자국이 길게 남았다. 실 하나가 떨렸다.`,
        win:{ exp:16, dream:1 }, lose:{ hp:-14, spirit:-6 } }
    ] },

  { at:'C3', t:'둥근 천장 — 회칠의 성인들',
    x:`갈빗대가 끊겼다. 무너져 나갔다. 남은 길은 회칠뿐이다.<br><br>
    회칠에 성인들이 그려져 있다. 얼굴이 크다. 얇다. 아래가 비친다. 아래는 아무것도 없다.<br>
    돌을 하나 굴려 봤다. 성인의 뺨 위에서 멈췄다. 뺨에 금이 갔다. 돌이 빠졌다. 소리가 안 났다.<br><br>
    돌 하나 무게도 못 받는다. 경신술사는 돌보다 가벼울 수 있는가.`,
    o:[
      { l:'① 무게를 다 덜고 성인들 얼굴 위를 건넌다.', k:'evade', dc:15, wake:1,
        ok:`숨을 다 내쉬었다. 몸에서 무게를 하나씩 덜어 냈다. 어깨, 허리, 무릎. 마지막에 발.<br><br>성인의 이마를 디뎠다. 회칠이 이쪽을 몰랐다. 눈썹, 콧등, 입술. 입술을 디딜 때 성인이 조금 입을 벌렸다. 다음 얼굴로 갔다.<br>건너편 갈빗대에 내렸다. 돌아보니 회칠에 금이 하나도 없다. 성인들 표정이 조금 바뀌었다. 놀란 쪽으로.<br><br>몸무게를 더는 게 아니었다. 디딘 곳에 몸무게를 안 두는 것이었다. 그 차이를 발이 알았다.`,
        ng:`셋째 얼굴에서 숨이 차올랐다. 무게가 돌아왔다.<br><br>성인의 눈에 발이 빠졌다. 회칠이 깨지며 이쪽이 반쯤 떨어졌다. 팔로 갈빗대 끝을 걸었다.<br>아래에서 찬 기운이 다리를 감는다. 끌어올려졌다. 다리에 회칠 가루와 다른 것이 묻었다.`,
        win:{ exp:25, dream:3 }, lose:{ hp:-14, spirit:-12 } },
      { l:'② 내공을 실어 갈빗대 끊긴 데를 단숨에 뛴다.', k:'evade', dc:14, cost:{ qi:18 },
        ok:`회칠을 안 밟기로 했다. 끊긴 갈빗대 끝에서 끝까지. 멀다.<br><br>내공을 끌어올렸다. 뛰었다. 몸이 오래 떴다. 내공이 몸을 들고 있는 동안 아래를 안 봤다.<br>건너편 갈빗대 끝에 발끝이 닿았다. 무게를 실었다. 버텼다.<br><br>회칠 성인들이 이쪽이 지나간 위를 올려다본다. 거꾸로.`,
        ng:`뛰는 순간 내공이 반만 올라왔다.<br><br>반만 갔다. 회칠 한가운데 떨어졌다. 성인 가슴에. 금이 사방으로 갔다.<br>엎드려 무게를 퍼뜨렸다. 기어서 건넜다. 성인 얼굴이 이쪽 무릎 밑에서 하나씩 깨졌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C3', t:'성가대석 — 입이 많은 노래',
    x:`성가대석이 거꾸로 매달렸다. 성가대가 노래한다.<br><br>
    한 사람에 입이 여럿이다. 목에도, 뺨에도, 손바닥에도. 입마다 다른 음을 낸다. 노래가 끝나면 다 같이 숨을 들이쉰다.<br>
    들이쉬는 숨이 세다. 성가대석 아래를 지나던 것이 빨려 올라갔다. 그리고 입 하나가 늘었다.<br><br>
    한 소절이 끝나기 전에 아래를 지나야 한다.`,
    o:[
      { l:'① 한 소절 안에 성가대석 아래를 달린다.', k:'evade', dc:15,
        ok:`소절이 시작될 때 뛰었다. 노래가 이쪽 등을 민다. 입이 많아서 소리가 두껍다.<br><br>성가대석 아래를 달렸다. 위에서 손바닥 입이 이쪽을 내려다보며 노래한다. 소절 끝이 다가온다. 음이 내려간다.<br>마지막 음에 성가대석 그늘을 벗어났다. 등 뒤에서 숨을 들이쉬는 소리. 이쪽 머리카락이 위로 날렸다. 그뿐이다.<br><br>성가대가 다음 소절을 시작했다. 한 음이 비었다. 아까 빨려 올라간 것의 자리였다.`,
        ng:`소절이 생각보다 짧았다. 이번 소절은 짧은 소절이었다.<br><br>숨을 들이쉬는 소리. 몸이 떴다. 발끝이 바닥에서 떨어졌다. 동료가 허리띠를 잡아당겼다.<br>떨어졌다. 귀에 노래가 남았다. 밤새 이쪽 입에서 그 음이 새어 나왔다.`,
        win:{ exp:20, dream:2 }, lose:{ mind:-12, spirit:-8 } },
      { l:'② 내공으로 숨을 묶고 버티며 걷는다.', k:'steady', dc:15, cost:{ qi:20 },
        ok:`내공으로 숨을 단전에 묶었다. 몸 안의 숨을 꽉 쥐었다.<br><br>천천히 걸었다. 성가대가 숨을 들이쉬었다. 몸이 위로 당겨진다. 숨이 안 딸려 나가니 몸도 안 딸려 간다. 버텼다.<br>세 소절 걸려 건넜다. 건너편에서 숨을 풀었다. 입에서 노래 한 토막이 같이 나왔다. 이쪽 목소리가 아니다.<br><br>삼켰다. 다시 안 나왔다.`,
        ng:`둘째 소절 끝에서 묶었던 숨이 풀렸다.<br><br>숨이 위로 빨려 나갔다. 숨을 따라 몸이 떴다. 성가대석 난간을 잡았다. 손바닥에 입이 닿았다. 물렸다.<br>떨어졌다. 손바닥에 둥근 자국이 남았다. 입 모양이다.`,
        win:{ exp:18, dream:2, spirit:5 }, lose:{ hp:-12, spirit:-12 } },
      { l:'③ 기둥 그늘에 붙어 소절 끝마다 숨는다.', k:'hide', dc:14,
        ok:`기둥 뒤에 붙었다. 소절이 끝날 때마다 기둥이 숨을 막아 줬다.<br><br>소절이 이어지는 동안 다음 기둥으로 갔다. 다섯 기둥. 다섯 소절.<br>건넜다. 귀가 먹먹하다.<br><br>성가대는 이쪽을 못 봤다. 입은 많아도 눈이 없다.`,
        ng:`넷째 기둥이 비어 있었다. 속이 썩어 구멍이 났다.<br><br>숨이 기둥을 뚫고 이쪽을 당겼다. 기둥 구멍에 몸이 끼었다. 그 덕에 안 빨려 갔다.<br>빠져나오는 데 한참 걸렸다. 갈비가 결린다.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C3', t:'홈통 — 입 달린 빗물받이',
    x:`벽을 따라 돌 홈통이 이어진다. 비가 위에서 아래로 흐르던 길이다. 지금은 거꾸로다.<br><br>
    홈통 끝마다 돌로 깎은 짐승 머리가 있다. 입을 벌렸다. 입 안에서 혀가 움직인다. 돌이 아니다.<br>
    홈통을 타고 가면 아래 첨탑 쪽으로 빨리 간다. 짐승 머리 옆을 지나야 한다. 머리가 일곱이다.<br><br>
    홈통 바닥에 빗물이 고였다. 고인 물이 맑다.`,
    o:[
      { l:'① 홈통을 타고 머리들 옆을 달려 내려간다.', k:'evade', dc:15,
        ok:`홈통 안을 달렸다. 좁다. 발 하나 너비다. 돌 머리 옆을 지날 때 입이 닫혔다. 이쪽 뒤에서.<br><br>일곱 번 닫혔다. 일곱 번 다 늦었다. 마지막 머리 앞에서 홈통이 꺾였다. 꺾이는 데서 몸을 비틀어 넘었다.<br>첨탑 쪽 턱에 내렸다. 돌아보니 일곱 머리가 다 이쪽을 본다. 혀를 빼물고.<br><br>이쪽은 첨탑에 먼저 왔다. 동료들은 계단으로 온다. 한참 뒤에.`,
        ng:`넷째 머리가 다른 머리보다 빨랐다.<br><br>입이 닫히며 이쪽 소매를 물었다. 홈통 밖으로 몸이 쏠렸다. 소매를 찢었다. 홈통 가장자리에 매달렸다.<br>기어서 다시 들어갔다. 팔뚝에 돌 이빨 자국이 둥글다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 첫 머리 앞 고인 빗물만 떠 온다.', k:'luck', dc:13,
        ok:`첫 머리는 입을 반쯤 닫은 채 졸고 있었다. 혀가 늘어졌다.<br><br>그 앞 고인 물에 수통을 댔다. 천천히. 물이 찬다. 맑다. 돌 냄새만 난다.<br>뚜껑을 닫는 순간 혀가 움찔했다. 물러났다.<br><br>성당이 뒤집혀도 비는 위에서 온다. 그건 안 뒤집혔다.`,
        ng:`수통을 대는데 혀가 수통을 감았다.<br><br>당긴다. 놓았다. 수통이 입 안으로 들어갔다. 돌 입이 닫혔다. 씹는 소리가 났다.<br>빈손으로 물러났다. 손가락에 혀가 스친 자리가 미끈하다.`,
        win:{ exp:14, item:'맑은 물' }, lose:{ mind:-8, spirit:-6 } }
    ] },

  { at:'C4', t:'온실 — 갓을 디딤돌 삼아',
    x:`온실 아래 단은 진창이다. 하얀 실이 엉킨 진창. 발을 넣으면 실이 감는다.<br><br>
    진창 위로 큰 갓들이 솟았다. 사람 키보다 크다. 갓 위는 평평하다. 갓에서 갓으로 가면 진창을 안 밟는다.<br>
    다만 갓은 눌리면 가루를 뿜는다. 무겁게 디디면 많이, 가볍게 디디면 조금.<br><br>
    저쪽 유리 종 안에 아직 하얘지지 않은 어린 버섯이 있다. 정원사들이 따로 키우던 것이다.`,
    o:[
      { l:'① 갓 위를 가볍게 디디며 건넌다.', k:'evade', dc:15,
        ok:`갓 가장자리를 디뎠다. 가운데는 무르다. 가장자리는 단단하다.<br><br>디딘 갓이 숨을 내쉬듯 가루를 조금 뿜었다. 가루가 오르기 전에 다음 갓이다. 가루는 이쪽 뒤에서만 올랐다.<br>유리 종 앞 받침대에 내렸다. 종을 들었다. 안의 버섯은 갈색이다. 하얀 실이 없다. 몇 개 땄다.<br><br>돌아보니 갓들 위로 하얀 김이 줄지어 올랐다. 이쪽이 지나간 길이 그렇게 보였다.`,
        ng:`일곱째 갓이 덜 자란 것이었다. 가장자리가 얇다.<br><br>찢어졌다. 발이 갓 속으로 빠졌다. 가루가 한꺼번에 터졌다. 얼굴까지.<br>숨을 참고 다음 갓으로 기어 넘었다. 눈이 따갑다. 한참 하얀 것이 보였다.`,
        win:{ exp:18, item:'야생 버섯' }, lose:{ hp:-10, mind:-10 } },
      { l:'② 진창 가장자리 화분대를 짚어 돌아간다.', k:'sense', dc:13,
        ok:`단 가장자리에 화분대가 줄지어 놓였다. 돌로 된 것이다. 실이 덜 탔다.<br><br>화분대에서 화분대로 옮겨 갔다. 멀다. 갓 위로 가는 것의 세 배다.<br>끝 화분대에 산나물이 남아 있었다. 정원사가 먹으려고 따로 둔 것 같다. 잎이 초록이다.<br><br>유리 종은 못 갔다. 대신 이건 진짜 초록이다.`,
        ng:`화분대 하나가 진창 쪽으로 기울어 있었다.<br><br>디디자 기울었다. 한 발이 진창에 들어갔다. 실이 발목을 감았다. 칼로 끊었다.<br>발목에 감긴 자국이 하얗다. 오래 가렵다.`,
        win:{ exp:14, item:'산나물' }, lose:{ hp:-10, spirit:-8 } }
    ] },

  { at:'C4', t:'온실 — 짐승을 입은 것',
    x:`네 발로 달리는 것이 있다. 개였다. 지금은 개 가죽 안에 하얀 것이 찼다.<br><br>
    다리가 개 다리보다 길다. 가죽이 모자라 실이 바깥으로 비져나왔다. 빠르다. 개였을 때보다 빠르다.<br>
    동료들이 쫓다가 지쳤다. 그것은 안 지친다. 지칠 몸이 없다.<br><br>
    경신술사는 지치지 않는 것보다 빨라야 한다. 오래는 아니어도.`,
    o:[
      { l:'① 그것을 앞질러 막다른 단으로 몬다.', k:'evade', dc:16, wake:1,
        ok:`그것이 달리는 길을 봤다. 늘 단 가장자리를 돈다. 앞지르려면 안쪽으로 가로질러야 한다. 안쪽은 진창이다.<br><br>진창 위에 놓인 판자와 화분과 쓰러진 정원사를 디뎠다. 디딘 것이 무엇인지 안 봤다. 디딜 수 있으면 됐다. 그것보다 먼저 막다른 단 입구에 섰다.<br>그것이 멈췄다. 처음으로 앞에 뭔가 있었다. 돌아서려는데 동료들이 뒤를 막았다.<br><br>길이 아닌 데로 가로지르는 동안, 발밑이 길인지 아닌지 묻지 않게 됐다. 디딜 수 있는 것은 다 길이다.`,
        ng:`가로지르다 판자 하나가 진창에 잠겼다.<br><br>발이 빠졌다. 그것이 그 틈에 이쪽을 지나갔다. 지나가며 옆구리를 물었다. 개 이빨이다. 안에서 실이 나와 상처를 더듬는다.<br>동료가 불로 지졌다. 옆구리가 탄 냄새가 난다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-18, spirit:-6 } },
      { l:'② 내공을 발끝에 실어 지나가는 머리를 찬다.', k:'break', dc:15, cost:{ qi:20 },
        ok:`그것이 오는 길목에 섰다. 숨을 모아 내공을 오른발 끝으로 내렸다.<br><br>그것이 덮쳤다. 옆으로 반 걸음 비키며 발끝으로 머리를 찼다. 개 머리가 꺾였다. 가죽 안에서 실이 뜯기는 소리가 났다.<br>그것이 몇 걸음 더 달리다 쓰러졌다. 다리는 계속 달린다. 몸이 안 따라간다.<br><br>발끝이 저리다. 신발 앞이 터졌다.`,
        ng:`찼는데 머리가 아니라 가죽만 찼다.<br><br>가죽이 밀렸다. 안의 것은 그대로다. 그것이 이쪽 다리를 물었다. 놓지 않는다.<br>동료들이 칼로 떼어 냈다. 종아리에 하얀 실이 몇 가닥 남았다. 뽑았다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C4', t:'중앙 돔 — 숨 쉬는 바닥',
    x:`중앙 돔 바닥은 흙이 아니다. 하얀 것이 두껍게 깔렸다. 바닥 전체가 부풀었다 꺼진다.<br><br>
    꺼질 때마다 가루가 뿜어진다. 돔 안이 하얘진다. 부풀 때는 가루가 바닥으로 빨려 든다.<br>
    가운데에 큰 갓이 솟았다. 저것이 숨을 쉰다. 동료들이 저것을 베러 간다. 길을 봐 줄 사람이 먼저 가야 한다.<br><br>
    바닥이 부푸는 동안이 길이다.`,
    o:[
      { l:'① 내공으로 숨을 늘리고 부푸는 동안 달린다.', k:'steady', dc:15, cost:{ qi:20 },
        ok:`바닥이 꺼질 때 숨을 들이쉬고 내공으로 묶었다. 가루가 이쪽 얼굴 앞을 지나간다. 숨은 안 쉰다.<br><br>바닥이 부풀기 시작했다. 달렸다. 부푼 바닥은 단단하다. 꺼지기 전에 갓 밑동에 닿았다.<br>밑동에 칼집을 하나 내고 돌아섰다. 동료들에게 밑동을 가리켰다. 다음 부풂에 동료들이 왔다.<br><br>숨을 풀었을 때 돔 안이 하얬다. 이쪽 숨은 하얗지 않았다.`,
        ng:`둘째 꺼짐에서 묶었던 숨이 새어 나갔다.<br><br>새로 들이쉬었다. 가루다. 기침이 터졌다. 바닥이 꺼지는 데 무릎을 꿇었다. 무릎에 실이 감겼다.<br>동료가 뒤에서 끌어냈다. 기침에 하얀 실이 섞여 나왔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-12, mind:-12 } },
      { l:'② 꺼지는 박자를 무시하고 단숨에 가로지른다.', k:'evade', dc:15,
        doom:{ title:'숨 쉬는 바닥', what:'하얀 바닥 속으로 가라앉습니다', dc:15, sec:60,
          text:`단숨에 달렸다. 바닥이 부풀든 꺼지든 디딜 수 있으면 디뎠다.<br><br>반쯤 갔을 때 바닥이 꺼졌다. 이쪽 발밑이 제일 깊게 꺼졌다. 무릎까지 들어갔다. 바닥이 부풀며 닫혔다. 닫힌 데에 다리가 물렸다.<br>바닥이 다시 꺼진다. 이번에는 허리까지. 하얀 것이 숨 쉬듯 이쪽을 조금씩 삼킨다.<br><br>동료들이 칼로 바닥을 판다. 판 자리도 숨을 쉰다.`,
          dieText:`경신술사는 디딘 것이 꺼지기 전에 떠난다.<br><br>여기서는 바닥이 먼저 디뎠다. 이쪽을.<br>바닥이 한 번 더 부풀었다. 아까보다 조금 컸다.` },
        ok:`단숨에 달렸다. 바닥이 꺼지는 느낌이 발바닥에 올라올 때마다 다음 발을 더 빨리 냈다.<br><br>꺼지는 바닥은 꺼질 시간이 필요하다. 그 시간보다 짧게 머물렀다. 가루가 이쪽 뒤에서 올랐다.<br>갓 밑동에 손을 짚었다. 숨을 쉬었다. 밑동 둘레만 바닥이 단단하다.<br><br>이쪽이 지나간 길에 작은 구멍이 줄지어 났다. 바닥이 이쪽을 삼키려다 못 삼킨 자리다.`,
        win:{ exp:24, dream:3 } }
    ] },

  { at:'C', t:'추격 — 뒤에서 오는 것',
    x:`잡다 놓친 것이 따라온다. 다쳐서 화가 났다.<br><br>
    동료 하나가 다리를 다쳤다. 무리가 느리다. 그것은 느린 쪽을 안다. 피 냄새로.<br>
    누군가 그것을 다른 데로 끌고 가야 한다. 그리고 돌아와야 한다.<br><br>
    경신술사는 끌고 가는 것보다 돌아오는 것이 어렵다는 걸 안다.`,
    o:[
      { l:'① 다친 동료의 피를 묻히고 반대로 달린다.', k:'evade', dc:15, wake:1,
        ok:`동료 붕대를 풀어 이쪽 소매에 감았다. 피 냄새가 이쪽에서 난다. 반대쪽 굴로 달렸다.<br><br>그것이 따라왔다. 굴이 갈리는 데마다 일부러 한 번씩 멈췄다. 냄새가 고이게. 그리고 다시 달렸다. 셋째 갈림에서 소매를 풀어 깊은 굴에 던졌다. 이쪽은 옆 굴로 꺾었다.<br>그것이 깊은 굴로 내려갔다. 이쪽은 돌아왔다. 무리는 멀리 가 있었다.<br><br>갈 때의 걸음과 돌아올 때의 걸음이 같은 걸음이었다. 다리가 지치지 않고 길을 접었다. 멀리 가는 것이 이제 멀지 않다.`,
        ng:`셋째 갈림에서 그것이 이쪽을 앞질렀다. 굴을 이쪽보다 잘 안다.<br><br>앞에서 나왔다. 멈췄다. 그것이 덮쳤다. 어깨를 물렸다. 떨치고 다른 굴로 뛰었다.<br>무리에게 돌아왔을 때 이쪽 피 냄새가 더 짙었다. 그것도 곧 올 것이다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-18, spirit:-6 } },
      { l:'② 내공을 실어 그것 앞을 스쳐 지나가며 돌린다.', k:'evade', dc:15, cost:{ qi:18 },
        ok:`내공을 끌어올려 그것 쪽으로 달렸다. 코앞을 스쳐 지나갔다. 바람이 그것 눈을 쳤다.<br><br>그것이 고개를 돌렸다. 이쪽을 쫓는다. 무리 반대로. 다시 스쳐 지나가며 한 번 더 돌렸다. 그것이 제자리에서 맴돌다 굴 벽에 부딪쳤다.<br>돌아와 보니 그것은 아직 맴돌고 있었다. 이쪽 냄새가 사방에 남았다.<br><br>다리가 떨린다. 내공을 다 썼다.`,
        ng:`스쳐 지나가는데 그것이 고개를 안 돌렸다.<br><br>앞발만 뻗었다. 이쪽 발목에 걸렸다. 굴렀다. 그것이 이쪽을 넘어 무리 쪽으로 갔다.<br>뒤쫓아 갔다. 동료들이 막았다. 이쪽 발목이 부었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'③ 무리를 바위틈에 숨기고 입구를 지킨다.', k:'hide', dc:14,
        ok:`바위틈을 찾아 무리를 밀어 넣었다. 다친 다리를 진흙으로 덮었다. 냄새가 덜 난다.<br><br>이쪽은 입구 위 바위에 엎드렸다. 그것이 지나갔다. 멈췄다. 냄새를 맡는다. 진흙 냄새다. 다시 갔다.<br>한참 엎드려 있었다. 다리에 쥐가 났다.<br><br>달리지 않는 날도 있다.`,
        ng:`진흙이 마르면서 갈라졌다. 냄새가 샜다.<br><br>그것이 돌아왔다. 입구에 머리를 들이밀었다. 이쪽이 위에서 뛰어내려 막았다. 머리에 발을 얹고 밀어냈다.<br>그것이 물러나며 이쪽 다리를 긁었다.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C', t:'벼랑길 — 무너지는 턱',
    x:`벼랑에 붙은 좁은 턱길이다. 뒤에서부터 무너진다.<br><br>
    무리가 지나간 무게에 금이 갔다. 금이 따라온다. 이쪽이 맨 뒤다.<br>
    앞에 동료 하나가 굳었다. 아래를 봤다. 아래에는 아까 잡은 것의 동족들이 모여 위를 올려다본다.<br><br>
    굳은 사람을 지나가려면 그 사람을 넘거나, 같이 가야 한다.`,
    o:[
      { l:'① 굳은 동료 바깥으로 돌아 앞질러 간다.', k:'evade', dc:14,
        ok:`턱 바깥 가장자리에 발끝만 걸치고 동료를 돌아 지났다. 지나며 그 사람 허리띠를 잡아 끌었다.<br><br>그 사람이 걸음을 떼었다. 끌려서라도. 무너지는 소리가 발뒤꿈치를 따라온다. 앞에 단단한 바위가 나왔다.<br>둘 다 바위에 올라섰다. 뒤에서 턱길이 통째로 떨어졌다. 아래에서 소리가 많이 났다.<br><br>동료가 이쪽 발을 봤다. 발끝만 걸쳐 걸은 발을.`,
        ng:`돌아 지나다 가장자리가 부서졌다.<br><br>발이 빠졌다. 동료 허리띠를 잡은 손으로 버텼다. 동료가 비명을 질렀다. 둘이 같이 끌려갈 뻔했다.<br>동료가 벽을 잡았다. 그 덕에 기어 올라왔다. 손목이 꺾였다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 굳은 동료에게 걸음을 세어 준다.', k:'bond', dc:14,
        ok:`뒤에서 그 사람 어깨에 손을 얹었다. 하나, 하고 말했다. 그 사람이 발을 뗐다. 둘.<br><br>이쪽 걸음 박자를 그 사람에게 빌려줬다. 세는 대로 걸었다. 아래를 안 봤다. 이쪽 목소리만 들었다.<br>스물에 바위에 닿았다. 뒤에서 턱이 떨어졌다.<br><br>그 사람은 몇 걸음이었는지 기억 못 한다. 이쪽은 기억한다. 스물.`,
        ng:`열을 셌을 때 그 사람이 다시 아래를 봤다.<br><br>멈췄다. 뒤에서 금이 따라잡았다. 이쪽 발밑이 내려앉았다. 그 사람을 앞으로 밀고 이쪽은 벽에 매달렸다.<br>그 사람이 끌어올려 줬다. 서로 말이 없었다.`,
        win:{ exp:16, dream:1, mind:5 }, lose:{ hp:-14, spirit:-6 } }
    ] },

  { at:'C', t:'사냥 — 발목을 노리는 것들',
    x:`바닥에 작은 것들이 깔렸다. 손바닥만 하다. 등딱지 아래 집게가 있다.<br><br>
    발목만 문다. 문 다음에 놓지 않는다. 하나가 물면 다른 것들이 그 다리를 타고 오른다.<br>
    동료들이 큰 것과 싸운다. 그 발밑으로 작은 것들이 몰린다. 누가 작은 것들을 끌어가야 한다.<br><br>
    경신술사는 발이 바닥에 닿는 시간을 줄이는 것을 공부한다.`,
    o:[
      { l:'① 작은 것들 사이를 달리며 끌어간다.', k:'evade', dc:15, wake:1,
        ok:`작은 것들 한가운데로 뛰어들었다. 발이 닿고, 집게가 닫히기 전에 떴다.<br><br>집게들이 이쪽을 쫓는다. 한 걸음마다 수십 개가 닫힌다. 다 빈 데다. 동료들 발밑이 비었다. 동료들이 큰 것에만 칼을 썼다.<br>굴 끝까지 끌고 가서 돌 위로 올라섰다. 작은 것들이 돌 둘레에 모였다. 큰 것이 쓰러지는 소리가 났다.<br><br>닿는 시간을 줄이다 보니 닿았다는 것도 잊었다. 발바닥이 바닥을 한 번 물어보고 대답은 기다리지 않는다.`,
        ng:`스무 걸음째에 집게 하나가 늦게 닫혔다. 늦어서 맞았다.<br><br>발목을 물렸다. 둘째, 셋째가 다리를 타고 올랐다. 뛰면서 떼어 냈다. 떼어 낸 자리마다 살이 같이 떨어졌다.<br>돌 위에 올라서 남은 것을 떼어 냈다. 다리가 피투성이다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-18, mind:-6 } },
      { l:'② 바위에 올라 작은 것들을 굽어보며 위치를 외친다.', k:'steady', dc:14,
        ok:`바위에 올라섰다. 아래가 다 보인다. 작은 것들이 어느 쪽으로 몰리는지.<br><br>동료들 이름을 부르며 발밑을 알렸다. 왼발, 뒤로, 그 자리. 동료들이 이쪽 말대로 디뎠다. 물리지 않았다.<br>큰 것이 쓰러졌다. 작은 것들은 흩어졌다.<br><br>이쪽은 바위에서 한 걸음도 안 움직였다. 목이 쉬었다.`,
        ng:`바위 위에도 작은 것들이 있었다. 등딱지가 바위 색이다.<br><br>발목을 물렸다. 외치던 말이 비명으로 바뀌었다. 동료들이 그 비명을 신호로 알았다. 엉뚱한 데로 디뎠다.<br>둘이 물렸다. 이쪽도.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C', t:'쉬는 자리 — 운기',
    x:`사냥 사이에 쉰다. 불은 못 피운다. 냄새가 난다.<br><br>
    다리가 무겁다. 하루에 몇 번 내공을 끌어올렸는지 모르겠다. 경락이 뜨겁고 끝은 차다.<br>
    가까운 굴에서 뭔가 돌아다니는 소리가 난다. 멀지 않다.<br><br>
    운기를 하면 몸이 돌아온다. 운기 중에는 몸이 굳는다. 아무것도 피하지 못한다.`,
    o:[
      { l:'① 내공을 몸에 돌려 다리를 풀어 둔다.', k:'steady', dc:14, cost:{ qi:15 },
        ok:`가부좌를 틀었다. 숨을 단전에 모아 천천히 다리로 내렸다. 뜨거운 데를 식히고 찬 데를 데웠다.<br><br>굴 소리가 가까워졌다. 눈을 안 떴다. 동료가 옆에서 칼을 들고 앉았다. 소리가 다른 데로 갔다.<br>눈을 떴다. 다리가 가볍다. 아침처럼.<br><br>동료에게 고맙다고 했다. 동료는 칼을 내리지 않은 채 고개만 끄덕였다.`,
        ng:`내공이 무릎에서 엉켰다.<br><br>억지로 밀었다. 다리 한쪽이 저리며 굳었다. 운기를 멈췄다. 굳은 다리를 손으로 주물렀다.<br>굴 소리가 멀어질 때까지 다리가 안 풀렸다.`,
        win:{ exp:15, dream:1, hp:10 }, lose:{ hp:-10, mind:-8 } },
      { l:'② 쉬는 대신 쉬는 자리 둘레를 소리 없이 돈다.', k:'evade', dc:15,
        ok:`다들 쉬게 두고 일어났다. 쉬는 자리 둘레를 돌았다. 발소리 없이.<br><br>둘레를 세 번 도는 동안 굴 소리가 두 번 가까워졌다. 두 번 다 이쪽이 먼저 그 굴 앞에 있었다. 돌을 던져 다른 굴로 돌렸다.<br>네 번째에 동료들이 깼다. 이쪽 다리는 더 무거워졌다.<br><br>그래도 다들 쉬었다. 경신술사가 대신 걸었다.`,
        ng:`둘째 바퀴에 굴 하나에서 뭔가 나왔다. 먼저 나왔다.<br><br>이쪽을 봤다. 이쪽이 소리를 지르면 다들 깬다. 안 지르고 달렸다. 쉬는 자리 반대로. 그것이 쫓아왔다.<br>멀리서 따돌리고 돌아왔다. 등에 긁힌 자국 셋. 다들 아직 잔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-8 } }
    ] }
]);

// ── 환영술사 (illusion) · 마력 ──────────────
kJob('illusion', 'C', [
  { at:'C', t:'사냥터 — 다친 척하는 미끼',
    x:`동료들이 구덩이를 팠다. 위를 가지로 덮었다. 그것을 그 위로 오게 해야 한다.<br><br>
    그것은 다친 것을 쫓는다. 절뚝이는 걸음, 끌리는 다리, 피 냄새. 셋이 다 있어야 온다.<br>
    환영술사는 걸음을 만든다. 끌리는 다리도 만든다. 냄새는 만들어 본 적이 없다.<br><br>
    구덩이 건너편 굴에서 그것이 고개를 내밀었다. 코를 벌름거린다.`,
    o:[
      { l:'① 마력으로 다친 짐승을 띄우고 냄새까지 입힌다.', k:'evade', dc:14, cost:{ mana:18 }, wake:1,
        ok:`짐승 모양을 띄웠다. 뒷다리를 끌게 했다. 그리고 동료 붕대에 묻은 피를 손에 묻혀 환영 위를 쓸었다. 마력이 피에 엉겨 붙었다.<br><br>그것이 코를 쳐들었다. 환영 쪽으로 냄새가 간다. 환영이 끌리는 다리로 구덩이 위를 지났다. 그것이 덮쳤다.<br>가지가 꺼졌다. 그것이 떨어졌다. 동료들이 창을 내리꽂았다.<br><br>손바닥에 남은 피가 마력에 아직 찐득하다. 보이는 것만 만들던 손이 냄새를 붙잡는 법을 알았다. 다음에는 피 없이도 될 것 같다.`,
        ng:`피를 묻혔는데 마력이 냄새를 안 붙들었다. 냄새가 이쪽 손에 남았다.<br><br>그것이 환영이 아니라 이쪽 손을 쫓았다. 구덩이를 돌아서 왔다. 뛰었다. 등에 발톱이 닿았다.<br>동료들이 창으로 막았다. 그것은 구덩이에 안 빠졌다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, spirit:-6 } },
      { l:'② 환영 없이 이쪽이 직접 절뚝이며 지난다.', k:'evade', dc:15,
        ok:`이쪽 다리를 끌며 구덩이 가장자리를 걸었다. 피는 이쪽 팔을 조금 그어서 냈다.<br><br>그것이 굴에서 나왔다. 천천히. 다친 것은 서두르지 않아도 잡힌다. 이쪽은 구덩이 뒤쪽 가장자리에 섰다.<br>그것이 마지막에 뛰었다. 이쪽은 옆으로 굴렀다. 그것은 구덩이 한가운데 내렸다. 가지가 꺼졌다.<br><br>팔의 상처는 작다. 그것이 쫓은 것은 그 작은 상처였다.`,
        ng:`옆으로 굴렀는데 구덩이 가장자리였다. 흙이 무너졌다.<br><br>그것과 같이 떨어질 뻔했다. 가장자리를 잡고 매달렸다. 그것이 아래에서 뛰어올라 발을 물려 했다.<br>동료들이 끌어올렸다. 발뒤꿈치가 찢어졌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C', t:'굴 — 눈이 많은 것',
    x:`굴 안의 것은 눈이 많다. 몸 여기저기에 하나씩 박혔다. 스무 개쯤.<br><br>
    눈마다 다른 쪽을 본다. 하나를 속여도 나머지가 본다.<br>
    환영술사의 환영은 한 방향에서 보라고 만든다. 스무 방향은 처음이다.<br><br>
    그것이 굴 입구를 막고 있다. 졸고 있다. 눈 몇 개만 떴다.`,
    o:[
      { l:'① 뜬 눈 가운데 진짜로 보는 눈을 찾는다.', k:'gaze', dc:15,
        ok:`뜬 눈을 하나씩 봤다. 눈동자가 움직이는 것은 셋이다. 나머지는 떠 있기만 한다.<br><br>셋 중에서도 하나만 눈꺼풀이 떨린다. 그게 깨어 있는 눈이다. 나머지는 자면서 뜬 눈이다.<br>그 눈 하나 앞에만 굴 벽 모양 환영을 세웠다. 작게. 무리가 그 뒤로 지났다.<br><br>스무 개를 다 속일 필요는 없었다. 보는 건 하나였다.`,
        ng:`셋을 찾았다. 넷째가 있었다. 등 밑에.<br><br>그 눈이 이쪽을 봤다. 그것이 깼다. 스무 개가 다 떴다. 굴이 눈으로 가득하다.<br>물러났다. 그것이 쫓다가 멈췄다. 눈 하나가 이쪽 얼굴을 오래 기억했다.`,
        win:{ exp:18, dream:2 }, lose:{ spirit:-12, mind:-6 } },
      { l:'② 마력을 쏟아 굴 전체에 빈 굴을 덮어씌운다.', k:'evade', dc:15, cost:{ mana:20 },
        ok:`한 방향이 아니라 굴 전체를 덮었다. 빈 굴의 모양을 굴 안에 칠했다. 어디서 봐도 빈 굴로 보이게.<br><br>마력이 쭉쭉 빠진다. 무리가 그 안을 지나갔다. 스무 개 눈이 빈 굴을 봤다. 한 눈이 무리 한 사람과 마주쳤다. 빈 굴만 봤다.<br>다 지나갔다. 환영을 거두자 무릎이 꺾였다.<br><br>그것은 끝까지 졸았다.`,
        ng:`굴 전체를 덮는데 한쪽 구석이 덜 덮였다.<br><br>그것의 눈 하나가 그 구석을 봤다. 이쪽 발이 거기 있었다. 그것이 일어섰다. 환영이 그것 몸에 찢겼다.<br>뛰어 나왔다. 머리가 깨질 듯 아프다. 마력을 찢긴 값이다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-10, spirit:-12 } },
      { l:'③ 눈이 안 닿는 배 밑으로 기어 지난다.', k:'hide', dc:14,
        ok:`눈은 몸 위와 옆에 박혔다. 배 밑에는 없다. 배 밑은 흙에 닿아 있으니까.<br><br>엎드려 기었다. 그것의 배와 굴 바닥 사이로. 뜨겁고 축축하다. 숨소리가 등 위에서 오르내린다.<br>반대편으로 빠져나왔다. 무리도 하나씩 그렇게 왔다.<br><br>옷에 그것의 배 냄새가 뱄다. 다음 굴의 것들이 이쪽을 동족으로 볼지도 모른다.`,
        ng:`기는데 그것이 몸을 뒤척였다.<br><br>배가 내려앉았다. 이쪽 위로. 숨이 막혔다. 그것은 안 깼다. 무거운 잠이다.<br>동료들이 다리를 당겨 빼냈다. 갈비가 아프다.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C', t:'사냥 — 덮치는 순간',
    x:`그것이 이쪽만 노린다. 환영을 띄우면 환영을 안 본다. 이쪽 숨소리를 듣는다.<br><br>
    다른 것을 만들어 봐야 소용없다. 이쪽이 이쪽이라는 걸 그것이 안다.<br>
    그렇다면 이쪽을 만든다. 이쪽 위에.<br><br>
    환영술사는 맞는 것이 늘 진짜가 아닌 쪽이게 한다. 진짜와 가짜가 한 뼘 떨어져 있으면.`,
    o:[
      { l:'① 이쪽 모습을 한 뼘 옆에 겹쳐 입는다.', k:'evade', dc:15, wake:1,
        ok:`이쪽 모습을 이쪽 몸에서 한 뼘 옆으로 밀어 입었다. 몸은 여기, 모습은 저기. 숨소리는 둘이 같은 데서 난다.<br><br>그것이 덮쳤다. 모습 쪽을. 발톱이 모습을 통과했다. 한 뼘 옆에서 이쪽은 한 발도 안 움직였다.<br>그것이 고개를 갸웃했다. 다시 덮쳤다. 또 한 뼘이 비었다. 동료들이 그 사이에 옆구리를 갈랐다.<br><br>멀리 세우던 환영이 이쪽 몸에 붙었다. 이쪽 모습이 이쪽 것이 아니어도 된다는 걸 몸이 알았다.`,
        ng:`한 뼘을 밀었는데 숨소리가 모습 쪽에서 안 났다.<br><br>그것이 숨소리를 덮쳤다. 이쪽 몸을. 어깨가 깊게 그어졌다. 모습은 저 혼자 비켜 서 있었다.<br>동료들이 떼어 냈다. 어깨에서 피가 멈추지 않는다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-18, spirit:-6 } },
      { l:'② 환영을 거두고 그 자리에 버틴다.', k:'steady', dc:14,
        ok:`환영을 다 거뒀다. 숨을 고르게 했다. 그것이 듣는 것은 흔들리는 숨이다.<br><br>그것이 다가왔다. 숨이 고르다. 잡을 것인지 망설인다. 그 망설임이 동료들에게는 길었다.<br>뒤에서 창이 들어갔다.<br><br>이쪽은 숨을 끝까지 고르게 쉬었다. 그게 제일 어려운 환영이었다.`,
        ng:`숨이 고르다가 한 번 떨렸다.<br><br>그것이 덮쳤다. 팔로 막았다. 팔뚝을 물렸다. 동료들이 쳤다. 놓았다.<br>팔이 한동안 안 쥐어진다.`,
        win:{ exp:16, dream:1 }, lose:{ hp:-14, mind:-8 } }
    ] },

  { at:'C', t:'밤 — 냄새로 찾는 것',
    x:`밤이다. 쉬는 자리 둘레에 뭔가 돈다. 냄새로 찾는다.<br><br>
    눈은 약하다. 환영을 보기는 볼 것이다. 잘 보지는 못한다. 대신 냄새가 맞으면 온다.<br>
    무리 냄새는 숨길 수 없다. 땀, 피, 먹고 남은 것.<br><br>
    그것보다 큰 것의 모양을 보여 주면 물러날까. 그것이 무서워하는 것이 있기는 할까.`,
    o:[
      { l:'① 마력으로 그것보다 큰 것을 어둠 속에 세운다.', k:'evade', dc:15, cost:{ mana:18 },
        ok:`그것을 잡을 만한 것을 상상했다. 그것보다 두 배 크고, 등이 굽고, 입이 옆으로 찢어진 것. 어둠 속에 세웠다.<br><br>그것이 멈췄다. 눈이 약해서 윤곽만 본다. 윤곽은 크다. 냄새는 무리 냄새다. 큰 것이 무리를 먹고 있다고 여겼는지 모른다.<br>그것이 물러났다. 남의 먹이에 끼지 않는다.<br><br>새벽까지 큰 것을 세워 뒀다. 마력이 바닥났다.`,
        ng:`큰 것을 세웠는데 그것이 오히려 다가왔다.<br><br>큰 것을 무서워하지 않았다. 큰 것을 먹는 쪽이었다. 환영을 덮쳤다. 통과했다. 바로 뒤에 무리가 있었다.<br>다들 깼다. 이쪽이 제일 늦게 깼다. 다리를 물렸다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 무리를 바위 모양으로 덮어 둔다.', k:'bond', dc:14,
        ok:`잠든 무리 위에 바위 모양을 덮었다. 하나씩. 바위 다섯.<br><br>그것이 둘레를 돌았다. 냄새는 나는데 보이는 건 바위다. 바위 하나를 코로 밀어 봤다. 동료 등이었다. 동료가 숨을 참았다.<br>그것이 바위를 핥고 갔다. 바위에서 냄새가 나는 데라고 여긴 것이다.<br><br>아침에 동료가 등이 축축하다고 했다. 이유는 말하지 않았다.`,
        ng:`바위 다섯을 덮다가 마지막 하나가 흐려졌다.<br><br>그것이 흐린 바위를 밀었다. 동료가 소리를 질렀다. 그것이 덮쳤다. 이쪽이 사이로 뛰어들었다.<br>이쪽 옆구리를 물었다 놓고 갔다. 동료는 멀쩡하다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
    ] },

  { at:'C1', t:'갈고리 줄 — 걸린 것인 척',
    x:`갈고리 줄 끝에서 앞치마를 입은 것이 걸어온다. 줄을 따라 하나씩 살핀다. 걸린 것이 제대로 걸렸는지.<br><br>
    걸리지 않은 것을 보면 건다. 갈고리는 넉넉하다. 빈 갈고리가 셋 돈다.<br>
    숨을 데가 없다. 줄 아래는 훤하다.<br><br>
    환영술사는 남을 속이기 전에 이쪽을 속여야 할 때가 있다. 이쪽이 이쪽이 아니게.`,
    o:[
      { l:'① 이쪽 위에 고깃덩이 모양을 덮고 줄에 섞인다.', k:'evade', dc:15, wake:1,
        ok:`빈 갈고리 하나를 잡고 매달렸다. 이쪽 위에 고깃덩이를 덮었다. 잘린 자리, 아문 자리, 손가락만큼 자란 새 살까지.<br><br>앞치마가 왔다. 이쪽 앞에서 멈췄다. 칼끝으로 이쪽을 툭 건드렸다. 칼끝이 고기에 닿는 소리를 냈다. 소리는 이쪽이 넣었다.<br>앞치마가 다음 갈고리로 갔다.<br><br>환영을 몸 밖에 세우는 것보다 몸에 입는 게 쉬웠다. 가장 잘 아는 모양이 이쪽 몸이니까. 이제는 이쪽을 무엇으로든 입힐 수 있을 것 같다.`,
        ng:`고깃덩이를 덮는데 숨을 쉬었다. 고깃덩이가 부풀었다.<br><br>앞치마가 멈췄다. 칼끝으로 찔렀다. 칼이 환영을 지나 이쪽 옆구리에 들어갔다. 얕게.<br>갈고리를 놓고 떨어져 굴렀다. 앞치마가 빈 갈고리를 오래 봤다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, spirit:-8 } },
      { l:'② 줄 그늘 아래 엎드려 기어 지난다.', k:'evade', dc:14,
        ok:`매달린 고깃덩이 그늘이 바닥에 겹쳐 진다. 그늘이 짙은 데만 골라 엎드려 기었다.<br><br>앞치마 발이 이쪽 머리 옆을 지나갔다. 발이 넷이다. 앞치마 아래로 보이는 건 그것뿐이다.<br>줄 끝까지 기었다. 일어섰다.<br><br>바닥에 기름과 피가 이쪽 모양대로 쓸려 있다. 앞치마가 돌아오면 볼 것이다. 서둘렀다.`,
        ng:`기는데 고깃덩이에서 뭔가 떨어졌다. 이쪽 등에. 미지근하다.<br><br>움찔했다. 앞치마가 멈췄다. 고개를 숙였다. 이쪽과 눈이 마주쳤다. 눈이 둘보다 많다.<br>뛰었다. 갈고리가 등을 긁고 지나갔다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-8 } }
    ] },

  { at:'C1', t:'정육실 — 띠톱',
    x:`띠톱이 돈다. 아무도 안 미는데 고기가 톱으로 간다.<br><br>
    톱 앞 바닥이 기울었다. 기운 쪽으로 다 미끄러진다. 고기도 연장도 사람도. 톱은 미끄러져 온 것을 반으로 가른다. 갈린 것은 따로따로 다시 자란다.<br>
    톱 너머가 다음 방이다. 톱 옆 좁은 틈으로 지나야 한다.<br><br>
    톱은 무엇을 보고 당기는가. 환영술사는 그걸 먼저 알고 싶다.`,
    o:[
      { l:'① 톱 앞에 이쪽 모양을 세워 끌어당김을 돌린다.', k:'evade', dc:15,
        doom:{ title:'띠톱', what:'톱 쪽으로 빨려 들어갑니다', dc:15, sec:55,
          text:`톱 앞에 이쪽을 하나 세웠다. 바닥이 그쪽으로 기울면 이쪽은 틈으로 간다.<br><br>바닥은 환영 쪽으로 안 기울었다. 이쪽으로 기울었다. 톱은 눈으로 당기지 않는다. 무게로 당긴다. 환영은 무게가 없다.<br>미끄러진다. 손톱으로 바닥을 긁는다. 기름이 손톱 아래로 들어온다. 톱날 소리가 발끝에서 난다.<br><br>동료들이 줄을 던진다. 줄이 기름에 미끄러진다.`,
          dieText:`환영술사는 보이는 것을 다룬다.<br><br>톱은 보지 않았다. 무거운 것을 원했다. 이쪽은 무거웠다.<br>다음 날 톱 옆에서 이쪽과 닮은 것 둘이 각각 자라기 시작했다.` },
        ok:`이쪽을 세웠다. 바닥이 그쪽으로 기울지 않았다. 이쪽으로 기울었다. 발이 미끄러졌다.<br><br>알았다. 무게다. 환영을 거두고 이쪽 몸 위에 무거운 것의 모양을 씌우는 대신, 옆에 굴러 있던 쇠 갈고리 더미를 환영으로 감쌌다. 이쪽 모양으로. 그리고 발로 밀었다.<br>바닥이 갈고리 더미 쪽으로 기울었다. 톱이 이쪽 모양을 한 쇠를 물었다. 불꽃이 튀며 톱날이 끊겼다.<br><br>무게 없는 환영에 무게를 빌려 줬다. 톱은 그것을 이쪽으로 알았다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 톱 옆 고정쇠를 풀어 띠를 늦춘다.', k:'fix', dc:14,
        ok:`톱 옆 덮개를 열었다. 띠를 잡아 주는 고정쇠가 있다. 사람이 쓰던 기계다. 사람이 쓰던 것은 사람이 멈출 수 있다.<br><br>고정쇠를 풀었다. 띠가 늘어졌다. 톱날이 헛돈다. 바닥 기울기가 멈췄다.<br>틈으로 지났다. 무리도 따라왔다.<br><br>덮개 안쪽에 손자국이 있다. 누가 먼저 이걸 하려다 못 했다.`,
        ng:`고정쇠를 풀다가 띠가 튀었다.<br><br>톱날이 이쪽 팔을 스쳤다. 깊다. 바닥이 이쪽 피 쪽으로 기울었다. 무리가 이쪽 허리를 잡고 버텼다.<br>팔을 동여맸다. 띠는 결국 늘어졌다. 이쪽 피가 톱날에 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-18, mind:-6 } }
    ] },

  { at:'C1', t:'출하장 — 반장의 머릿수',
    x:`출하구 앞에 반장이 서서 센다. 나가는 덩이 수를.<br><br>
    수가 맞으면 문이 열린다. 수가 틀리면 반장이 모자란 만큼 채운다. 가까이 있는 것으로.<br>
    오늘 나갈 덩이는 서른이다. 대기줄에 걸린 것은 스물다섯이다. 반장이 이쪽 무리를 본다. 다섯이다.<br><br>
    환영술사는 숫자를 만들 수 있다. 셀 수 있는 모양이면 무엇이든.`,
    o:[
      { l:'① 반장이 세는 손을 본다.', k:'gaze', dc:14,
        ok:`반장의 손가락을 봤다. 덩이 하나에 손가락 하나를 접는다. 손가락이 서른 개다.<br><br>세는 것은 손가락이다. 눈이 아니다. 손가락은 덩이가 지나가며 일으키는 바람을 센다.<br>동료들에게 대기줄 덩이를 두 개씩 묶어 밀게 했다. 바람이 하나만 인다. 스물다섯이 열셋이 됐다. 반장이 모자란 수를 대기줄에서 다시 채운다.<br><br>그 사이 무리가 출하구 옆 틈으로 빠졌다. 반장은 아직 세고 있다.`,
        ng:`손을 보는데 반장이 이쪽을 셌다. 손가락 하나를 접었다.<br><br>이쪽이 한 덩이가 됐다. 대기줄 갈고리가 이쪽 쪽으로 돌았다. 피했다. 반장이 접은 손가락을 펴지 않는다.<br>출하구를 지날 때까지 이쪽 등에 그 손가락이 겨눠져 있었다.`,
        win:{ exp:18, dream:2 }, lose:{ spirit:-12, mind:-6 } },
      { l:'② 마력으로 덩이 다섯을 더 띄워 수를 채운다.', k:'hide', dc:15, cost:{ mana:20 },
        ok:`대기줄 끝에 덩이 다섯을 띄웠다. 갈고리에 걸린 모양으로. 걸린 것은 무게가 있어 줄이 처진다. 줄 처지는 것까지 그려 넣었다.<br><br>반장이 셌다. 서른. 문이 열렸다. 덩이들이 나간다. 환영 다섯도 나간다. 무리가 그 다섯 뒤에 붙어 나갔다.<br>문 밖에서 환영을 거뒀다. 반장이 문 안에서 고개를 갸웃했다.<br><br>나간 것을 다시 셀 줄은 모르는 모양이다.`,
        ng:`다섯을 띄우는데 마력이 넷에서 끊겼다.<br><br>스물아홉. 반장이 하나를 채우러 걸어왔다. 무리 쪽으로. 이쪽이 앞으로 나섰다.<br>반장 손이 이쪽 어깨를 잡았다. 동료들이 칼로 그 손을 쳤다. 손이 놓였다. 어깨에 손가락 자국이 남았다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-14, spirit:-8 } },
      { l:'③ 반장 앞을 비켜 대기줄 뒤로 돌아간다.', k:'evade', dc:14,
        ok:`반장은 앞만 센다. 대기줄 뒤는 안 본다.<br><br>무리를 이끌고 대기줄 덩이들 뒤로 돌았다. 덩이들 사이로. 덩이 하나가 이쪽 쪽으로 몸을 틀었다. 덩이 수는 바뀌지 않았다. 반장은 안 봤다.<br>출하구 옆 배수구 쪽으로 나왔다. 좁다. 기어서 나왔다.<br><br>나오면서 들었다. 반장이 스물다섯을 세고 멈췄다.`,
        ng:`덩이들 사이를 지나는데 덩이 하나가 갈고리에서 떨어졌다.<br><br>반장이 소리 쪽을 봤다. 덩이 하나가 줄었다. 반장이 채울 것을 찾았다. 이쪽이 제일 가까웠다.<br>배수구로 굴러 들어갔다. 반장 칼이 배수구 쇠살을 쳤다. 손가락 끝이 베였다.`,
        win:{ exp:16, dream:1 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C2', t:'진열장 — 유리 눈들',
    x:`진열장 칸마다 인형이 앉아 이쪽을 본다. 눈이 유리다.<br><br>
    유리 눈은 못 본다. 환영술사는 그걸 안다. 그런데도 눈이 따라 돈다.<br>
    인형들 등에서 실이 위로 이어진다. 실이 떨리면 인형이 돈다. 인형은 실로 본다. 실 끝의 것이 대신 본다.<br><br>
    실 끝의 것이 보는 것은 무엇인가. 이쪽 모습인가, 실의 떨림인가.`,
    o:[
      { l:'① 마력으로 진열장 앞을 지나가는 인형 하나를 만든다.', k:'evade', dc:15, cost:{ mana:18 },
        ok:`인형을 하나 만들었다. 진열장에 앉은 것과 같은 크기, 같은 사기 얼굴. 실까지 그렸다. 위로 이어지는 실.<br><br>그 인형이 진열장 앞을 걸었다. 칸의 인형들이 그쪽으로 고개를 돌렸다. 위에서 실이 조금 흔들렸다. 위의 것이 자기 실을 세는 것이다. 하나가 더 있다.<br>위의 것이 그 인형을 찾느라 실을 다 당겼다. 진열장 인형들이 다 그쪽을 봤다. 이쪽 무리는 반대편으로 지났다.<br><br>환영 인형을 거뒀다. 위에서 실 하나가 끊어진 것처럼 늘어졌다.`,
        ng:`인형을 만들었는데 실을 덜 그렸다. 실이 위까지 안 닿았다.<br><br>위의 것이 실 없는 인형을 봤다. 자기 것이 아니다. 진열장 인형들이 일제히 이쪽을 돌아봤다. 만든 쪽을.<br>인형들이 칸에서 내려왔다. 뛰었다. 종아리에 이가 박혔다. 빼냈다. 사람 어금니다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-14, spirit:-8 } },
      { l:'② 어느 인형의 이가 새것인지 본다.', k:'gaze', dc:14,
        ok:`인형들 입을 봤다. 이가 누렇고 닳은 것, 하얗고 날 선 것.<br><br>새로 박힌 이가 있는 인형만 실이 팽팽하다. 오래된 것들은 실이 늘어졌다. 위의 것은 새것만 쓴다.<br>팽팽한 실을 셋 끊었다. 나머지는 늘어진 채 그대로다. 무리가 지나갔다. 인형 셋이 칸에서 고개를 떨궜다.<br><br>새 이가 누구 것인지는 생각하지 않기로 했다.`,
        ng:`보는데 인형 하나가 입을 다물었다. 이를 숨겼다.<br><br>그 인형이 실 없이 움직였다. 칸에서 뛰어내려 이쪽 손목을 물었다. 사기 턱이 단단하다.<br>바닥에 내리쳐 깼다. 손목에 이 자국이 박혔다. 새 이다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C2', t:'도장실 — 얼굴 칠하는 것',
    x:`도장실에 얼굴을 칠하는 것이 있다. 붓이 손가락마다 달렸다.<br><br>
    사기 얼굴에 볼을 칠하고 입술을 칠한다. 칠한 얼굴은 선반에 올린다. 선반이 꽉 찼다. 칠할 얼굴이 모자라다.<br>
    칠하는 것이 고개를 든다. 이쪽 무리를 본다. 얼굴이 다섯 있다.<br><br>
    작업대에 물감 통이 있다. 물감에 꿀을 섞었다. 달고 끈적한 냄새가 방에 찼다.`,
    o:[
      { l:'① 이쪽 얼굴 위에 다 칠한 사기 얼굴을 덮는다.', k:'evade', dc:15, wake:1,
        ok:`선반의 칠한 얼굴 하나를 봤다. 그 얼굴을 그대로 이쪽 얼굴에 덮었다. 볼의 붉은 점, 입술 끝의 갈라짐까지.<br><br>칠하는 것이 이쪽에게 왔다. 붓을 들었다가 멈췄다. 칠할 데가 없다. 이미 다 칠했다. 이쪽을 선반에 올리려 했다. 이쪽은 선반 쪽으로 걸어가 그 앞에 섰다. 스스로 올라가는 척.<br>그것이 다음 얼굴을 찾아 돌아섰다. 동료들이 그 등에 칼을 넣었다.<br><br>남의 얼굴을 쓰는 동안 이쪽 얼굴을 잊지 않았다. 덮은 것과 덮인 것을 둘 다 쥐고 있었다. 손이 그만큼 커졌다.`,
        ng:`얼굴을 덮었는데 눈을 덜 그렸다. 눈이 이쪽 눈이었다.<br><br>칠하는 것이 이쪽 눈에 붓을 댔다. 칠하려고. 차갑다. 눈을 감았다. 눈꺼풀에 물감이 칠해졌다.<br>뒤로 물러나 닦았다. 꿀 섞인 물감이 안 닦인다. 한참 눈이 끈적했다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-10, spirit:-12 } },
      { l:'② 그것이 다른 데 칠하는 사이 꿀 단지를 집는다.', k:'luck', dc:14,
        ok:`그것이 동료 얼굴을 보며 다가가는 사이 작업대로 갔다. 물감 통 옆에 꿀 단지가 따로 있다. 아직 안 섞은 꿀이다.<br><br>집었다. 뚜껑이 단단하다. 물감 냄새가 안 뱄다.<br>돌아보니 동료가 붓을 피해 물러나고 있었다. 그것이 붓을 내렸다. 이쪽을 봤다. 단지를 든 손을.<br><br>단지를 품에 넣고 동료들 쪽으로 물러났다. 그것은 칠할 얼굴이 아니면 쫓지 않았다.`,
        ng:`단지를 집는데 옆의 물감 통이 엎어졌다.<br><br>물감이 이쪽 손과 소매에 쏟아졌다. 그것이 돌아봤다. 칠해진 손을. 아직 덜 칠한 손이다. 붓이 이쪽 손으로 왔다.<br>손을 빼며 물러났다. 손등에 붓 자국이 남았다. 사기처럼 하얗게 굳었다.`,
        win:{ exp:15, item:'꿀 한 줌' }, lose:{ hp:-8, mind:-10 } }
    ] },

  { at:'C2', t:'다락 — 인형사가 보는 것',
    x:`다락 한가운데 그것이 앉아 있다. 모든 실이 그것 손가락으로 모인다.<br><br>
    그것은 눈이 없다. 인형들 눈으로 본다. 다락에 인형이 수백이다. 수백 개의 유리 눈이 그것의 눈이다.<br>
    동료들이 그것을 베려면 인형들 사이를 지나야 한다. 지나는 순간 수백 개가 본다.<br><br>
    환영술사는 수백 개의 눈에게 한 가지를 동시에 보여 줘야 한다.`,
    o:[
      { l:'① 마력을 쏟아 인형들 눈마다 실이 끊기는 모습을 보인다.', k:'evade', dc:16, cost:{ mana:22 }, wake:1,
        ok:`눈 하나하나에 환영을 띄울 수는 없다. 대신 다락 전체에 하나를 띄웠다. 실이 한꺼번에 끊어지는 모습. 수백 가닥이 늘어지며 떨어지는 것.<br><br>수백 개의 눈이 그걸 봤다. 그것이 봤다. 그것의 손가락이 실을 다시 잡으려고 허우적댔다. 실은 그대로다. 그것이 실을 놓고 다시 쥐는 사이 동료들이 지났다.<br>칼이 그것의 손목에 들어갔다. 이번에는 진짜로 실이 늘어졌다.<br><br>하나를 보여 주면 보는 눈이 몇이든 상관없었다. 이쪽 환영은 이제 눈의 수를 세지 않는다.`,
        ng:`실이 끊기는 모습을 띄웠다. 그것이 봤다. 그런데 손가락은 실을 느꼈다. 실은 안 끊겼다.<br><br>그것이 환영이라는 걸 알았다. 그리고 환영이 어디서 오는지 찾았다. 수백 개의 눈이 이쪽을 향했다.<br>인형들이 일제히 이쪽으로 왔다. 동료들이 이쪽을 감쌌다. 팔과 다리에 이가 수십 군데 박혔다.`,
        win:{ exp:25, dream:4 }, lose:{ hp:-18, spirit:-10 } },
      { l:'② 동료들에게 인형 눈 높이 아래로 기라고 한다.', k:'bond', dc:14,
        ok:`인형들은 앉아 있다. 눈은 다 같은 높이다. 그 아래는 안 본다.<br><br>동료들에게 손짓했다. 엎드려 기라고. 인형 무릎 아래로. 다들 기었다. 이쪽이 맨 앞에서 높이를 잡아 줬다.<br>그것 발밑까지 갔다. 그것의 발 아래로는 아무 눈도 없었다. 거기서 일어나 칼을 들었다.<br><br>그것은 마지막까지 이쪽을 못 봤다. 일어설 때 봤다.`,
        ng:`기는데 동료 하나가 머리를 들었다. 숨이 막혀서.<br><br>눈 하나가 그 머리를 봤다. 다 봤다. 인형들이 기는 무리 위로 떨어졌다.<br>이쪽이 그 동료를 덮었다. 등에 인형들이 매달렸다. 떼어 내는 데 한참 걸렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'③ 이쪽 손목의 실을 끊지 않고 그대로 둔다.', k:'steady', dc:14,
        ok:`손목에 실이 하나 붙어 있다. 언제부터인지 모른다. 끊지 않았다.<br><br>그것은 실이 붙은 것을 자기 것으로 여긴다. 이쪽이 다가가도 안 본다. 자기 인형이 다가오는 줄 안다.<br>그것 바로 앞까지 갔다. 실을 끊었다. 그것이 처음으로 이쪽을 봤다. 늦었다.<br><br>동료들 칼보다 이쪽 칼이 먼저였다.`,
        ng:`실을 두고 다가가는데 실이 당겼다.<br><br>그것이 이쪽을 인형처럼 움직였다. 팔이 들렸다. 칼이 동료 쪽을 향했다. 버텼다. 팔이 떨렸다.<br>동료가 실을 끊었다. 이쪽 칼끝이 동료 소매를 스쳤다. 둘 다 아무 말도 안 했다.`,
        win:{ exp:18, dream:2 }, lose:{ mind:-12, spirit:-8 } }
    ] },

  { at:'C3', t:'종탑 — 떨림을 듣는 종',
    x:`종탑 끝에 종거미가 매달렸다. 종 테두리에서 다리가 나온다.<br><br>
    눈이 없다. 종이 귀다. 벽이 떨리면 종이 운다. 울린 쪽으로 다리를 뻗는다.<br>
    환영은 떨리지 않는다. 보는 것에게만 통한다. 이것은 보지 않는다.<br><br>
    환영술사가 할 일이 없는 데에서, 환영술사는 늘 일을 찾았다.`,
    o:[
      { l:'① 마력으로 소리를 엮어 반대편 벽에 울림을 놓는다.', k:'evade', dc:15, cost:{ mana:18 }, wake:1,
        ok:`모양 대신 소리를 짰다. 발소리가 아니라 울림. 벽을 무엇이 디딜 때 나는 낮은 떨림.<br><br>반대편 벽에 놓았다. 서툴다. 그런데 종이 울었다. 종이 그 울림에 대답했다. 다리들이 반대편으로 뻗었다. 벽을 짚고 매달려 거기서 기다린다.<br>무리가 이쪽 벽을 따라 내려갔다. 종은 다른 데를 듣고 있었다.<br><br>보이는 것만 만들던 마력이 들리는 것을 만들었다. 보지 않는 것도 이제 속일 수 있다. 이쪽 일이 반쯤 넓어졌다.`,
        ng:`울림을 놓았는데 이쪽 숨소리보다 작았다.<br><br>종이 작은 쪽을 버리고 큰 쪽을 골랐다. 이쪽이다. 다리 하나가 이쪽 허리를 감았다. 종 쪽으로 당긴다.<br>동료들이 다리를 쳐서 끊었다. 허리에 감긴 마디가 그대로 남았다. 떼어 냈다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, spirit:-8 } },
      { l:'② 종이 울 때만 움직이고 그치면 멈춘다.', k:'hide', dc:14,
        ok:`종이 울면 종 자신의 울림에 귀가 먹는다. 그동안만 움직였다.<br><br>울림, 세 걸음. 그침, 멈춤. 울림, 세 걸음. 종거미 바로 밑을 지날 때도 그랬다. 종 안에서 혀가 흔들렸다. 이쪽을 안 찾았다.<br>계단에 닿았다.<br><br>종이 울 때마다 이쪽 가슴도 울렸다. 그건 종이 몰랐다.`,
        ng:`종이 울다 말았다. 울림이 반 박자 짧았다.<br><br>그침 속에서 이쪽 발이 한 걸음 더 나갔다. 종이 들었다. 다리가 이쪽 앞 벽을 찍었다. 피하며 넘어졌다.<br>무릎이 깨졌다. 종이 그 소리를 들었다. 다시 굴러 피했다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C3', t:'신도석 — 빈자리 하나',
    x:`거꾸로 매달린 신도석에 밀랍 수사들이 앉았다. 녹아 굳은 사람 모양이다.<br><br>
    한 줄에 빈자리가 하나 있다. 그 자리 앞 성서대 위에 초 상자가 있다. 밀랍과 꿀이 든다.<br>
    수사들은 거꾸로 앉아 기도한다. 빈자리를 자꾸 본다. 채울 것을 기다린다.<br><br>
    환영술사는 저 자리에 수사 하나를 앉힐 수 있다. 환영 수사를.`,
    o:[
      { l:'① 이쪽 위에 밀랍 수사를 덮고 빈자리에 앉는다.', k:'evade', dc:15,
        doom:{ title:'빈자리', what:'밀랍 수사들에게 신도석으로 끌려 올라갑니다', dc:15, sec:60,
          text:`이쪽 위에 밀랍 수사를 덮었다. 녹아 늘어진 손가락까지. 신도석으로 올라가 빈자리에 앉았다. 거꾸로.<br><br>옆자리 수사가 이쪽 손을 잡았다. 같이 기도하자는 것이다. 손이 따뜻하다. 녹는다. 이쪽 손가락으로 밀랍이 흘러든다.<br>환영 위로 진짜 밀랍이 덮인다. 수사들이 하나씩 이쪽 쪽으로 몸을 기울인다. 빈자리가 찼다. 이제 놓을 이유가 없다.<br><br>아래에서 동료들이 이쪽을 부른다. 이쪽 입이 밀랍으로 덮여 대답이 안 나온다.`,
          dieText:`환영술사는 빈자리에 환영을 앉혔다.<br><br>수사들은 환영과 사람을 가리지 않았다. 가릴 필요가 없었다. 밀랍은 둘 다 덮는다.<br>신도석 줄이 다 찼다. 수사들이 비로소 고개를 숙였다.` },
        ok:`빈자리에 앉지 않았다. 빈자리 앞에 이쪽을 덮은 밀랍 수사를 세웠다. 앉으려는 모양으로. 반쯤 앉은 채로.<br><br>수사들이 그쪽을 봤다. 자리가 찰 것을 기다린다. 기다리는 동안은 아무도 손을 안 뻗는다. 그 사이 성서대 밑으로 기어 초 상자를 열었다. 굳은 꿀을 떠냈다.<br>내려와서 환영을 거뒀다. 반쯤 앉던 수사가 사라졌다. 신도석 수사들이 일제히 이쪽을 내려다봤다.<br><br>빈자리는 또 비었다. 채우는 쪽이 이쪽이 아니면 된다.`,
        win:{ exp:24, dream:3, item:'꿀 한 줌' } },
      { l:'② 어느 수사가 아직 덜 굳었는지 본다.', k:'gaze', dc:14,
        ok:`수사들 손가락 끝을 봤다. 다 굳은 것은 끝이 뾰족하다. 덜 굳은 것은 끝에서 방울이 맺힌다.<br><br>방울 맺힌 수사가 둘이다. 그 둘 사이만 피해 신도석 끝으로 올랐다. 굳은 수사는 손을 못 뻗는다.<br>초 상자에서 굳은 꿀을 한 줌 떠냈다. 밀랍 냄새가 배었다.<br><br>덜 굳은 둘 중 하나는 신도석 아래 바닥에 이름이 새겨진 자리였다. 거꾸로. 최근 이름이다.`,
        ng:`굳은 줄 알았던 수사 손가락 끝에서 방울이 떨어졌다. 이쪽 목덜미에.<br><br>뜨겁다. 움찔했다. 그 수사가 이쪽을 봤다. 손을 뻗었다. 녹는 손이 이쪽 머리를 쓰다듬었다.<br>뿌리치고 떨어졌다. 머리카락이 밀랍에 굳어 뭉쳤다. 잘라야 했다.`,
        win:{ exp:16, item:'꿀 한 줌' }, lose:{ hp:-10, spirit:-12 } }
    ] },

  { at:'C3', t:'성가대 — 한 음이 비는 노래',
    x:`입 많은 성가대가 노래한다. 한 사람에 입이 여럿, 입마다 다른 음.<br><br>
    노래에 한 음이 빈다. 낮은 음 하나. 빈 데에 이르면 성가대가 숨을 들이쉬고 찾는다. 그 음을 낼 입을.<br>
    성가대석 아래를 지나는 것이 있으면 빨아올려 입 하나로 삼는다.<br><br>
    환영술사는 모양을 만든다. 모양이 노래할 수 있다면.`,
    o:[
      { l:'① 마력으로 빈 음을 내는 입 하나를 성가대석에 띄운다.', k:'evade', dc:15, cost:{ mana:20 },
        ok:`성가대석 끝에 입 하나를 띄웠다. 입술만. 그 입이 낮은 음을 냈다. 마력으로 짠 소리다. 서툴다. 그래도 낮다.<br><br>노래가 빈 데에 이르렀다. 빈 데가 찼다. 성가대가 숨을 들이쉬지 않았다. 노래가 이어졌다. 처음으로 끝까지.<br>그 사이 무리가 성가대석 아래를 다 지났다.<br><br>노래가 끝나자 성가대가 모두 이쪽 입을 봤다. 환영을 거뒀다. 다음 노래는 다시 한 음이 빈다.`,
        ng:`입을 띄웠는데 음이 조금 높았다.<br><br>노래가 틀렸다. 성가대가 노래를 멈췄다. 모든 입이 다물었다. 그리고 한꺼번에 숨을 들이쉬었다.<br>무리가 바닥에 엎드려 버텼다. 이쪽은 늦었다. 몸이 떴다가 떨어졌다. 귀에서 피가 났다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-12, spirit:-12 } },
      { l:'② 노래가 빈 데에 이르기 전에 지난다.', k:'steady', dc:14,
        ok:`노래를 처음부터 들었다. 빈 데까지 서른두 마디다. 마디를 셌다.<br><br>첫 마디에 무리를 출발시켰다. 열여섯째 마디에 반을 지났다. 서른째에 마지막 사람이 지났다. 서른둘째에 성가대가 숨을 들이쉬었다. 빈 데에서.<br>아래에 아무도 없었다.<br><br>세는 동안 이쪽 입술이 노래를 따라 움직였다. 그건 다들 못 본 척했다.`,
        ng:`스무째 마디에서 세는 것을 놓쳤다. 노래가 셈을 지웠다.<br><br>무리 끝이 아직 아래에 있을 때 숨이 들어왔다. 이쪽이 맨 끝이었다. 몸이 떴다. 기둥을 잡았다.<br>버텼다. 손바닥이 다 쓸렸다. 귀에 노래가 박혔다.`,
        win:{ exp:16, dream:1, mind:5 }, lose:{ hp:-10, mind:-12 } }
    ] },

  { at:'C4', t:'온실 — 온기를 찾는 실',
    x:`하얀 실이 바닥을 덮었다. 실 끝이 공기 속으로 일어선다. 더듬는다.<br><br>
    실은 눈이 없다. 온기를 찾는다. 따뜻한 것이 지나가면 실이 그쪽으로 눕는다. 그리고 감는다.<br>
    환영은 차갑다. 빛은 있고 온기는 없다.<br><br>
    무리가 지나려면 실이 다른 데로 누워야 한다.`,
    o:[
      { l:'① 환영에 온기를 섞어 넣는다.', k:'evade', dc:15, wake:1,
        ok:`손바닥을 비볐다. 이쪽 체온을 마력에 실었다. 처음 해 보는 일이다. 빛을 짤 때와 손이 다르게 움직였다.<br><br>무리 반대편에 사람 모양을 세웠다. 실이 그쪽으로 기울었다. 눕기 시작했다. 사람 모양을 실이 감았다. 감은 것이 사라지지 않는다. 온기가 남아 있으니까.<br>무리가 지났다. 실은 한 가닥도 안 돌아봤다.<br><br>환영을 거두자 손바닥이 차가웠다. 온기를 빌려 준 만큼. 보이기만 하던 것이 이제 따뜻하다.`,
        ng:`온기를 섞으려다 마력이 이쪽 체온을 너무 많이 가져갔다.<br><br>몸이 식었다. 환영은 미지근하다. 실이 미지근한 것과 따뜻한 것을 둘 다 찾았다. 이쪽 무리가 더 따뜻했다.<br>실이 발목들을 감았다. 칼로 끊었다. 이쪽은 한참 떨었다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-12, spirit:-10 } },
      { l:'② 실이 덜 덮인 화분 사이를 찾아 약초를 딴다.', k:'sense', dc:13,
        ok:`실이 왜 화분 몇 개는 피했는지 봤다. 그 화분은 흙이 젖지 않았다. 마른 데는 실이 싫어한다.<br><br>마른 화분 사이로 지났다. 화분 하나에 약초가 났다. 잎이 단단하고 초록이다. 실이 피한 덕이다.<br>뜯었다. 뿌리째.<br><br>실은 이쪽 발을 따라 일어섰다가 마른 흙에서 멈췄다.`,
        ng:`마른 화분인 줄 알았는데 겉흙만 말랐다.<br><br>손을 넣는 순간 실이 손목을 감았다. 따뜻한 손이다. 감는 힘이 세다.<br>칼로 끊었다. 손목에 하얀 실 자국이 팔찌처럼 남았다.`,
        win:{ exp:14, item:'약초 뭉치' }, lose:{ hp:-10, mind:-6 } }
    ] },

  { at:'C4', t:'정원 일꾼들 — 일하는 척',
    x:`정원사를 입은 것들이 일한다. 다섯이다. 물을 주고 가지를 치고 흙을 고른다.<br><br>
    일하는 것은 건드리지 않는다. 일 안 하는 것만 본다. 일 안 하는 것이 보이면 다섯이 같이 일을 멈춘다. 가위를 든다.<br>
    무리가 이 단을 지나야 한다. 다들 일하는 사람처럼 보여야 한다.<br><br>
    환영술사는 사람 다섯을 정원사 다섯으로 바꿀 수 있다. 오래는 못 간다.`,
    o:[
      { l:'① 마력으로 무리 모두에게 정원사 옷을 입힌다.', k:'hide', dc:15, cost:{ mana:20 },
        ok:`무리 다섯에게 정원사 옷을 입혔다. 모자, 앞치마, 흙 묻은 장갑. 손에 물뿌리개를 들렸다. 환영 물뿌리개다.<br><br>무리가 물 주는 시늉을 하며 단을 건넜다. 정원사를 입은 것들이 고개를 들었다가 다시 숙였다. 같은 옷이다. 일을 하고 있다.<br>단 끝에서 옷을 거뒀다. 정원사 하나가 이쪽 쪽을 봤다. 일꾼이 다섯 줄었다.<br><br>그것은 한참 이쪽 쪽을 보다가, 일을 다시 시작했다. 일이 먼저다.`,
        ng:`셋째 옷을 입히는데 마력이 흔들렸다. 옷이 깜빡였다.<br><br>정원사들이 일을 멈췄다. 다섯이 같이 가위를 들었다. 깜빡인 쪽으로 걸어왔다.<br>무리가 흩어졌다. 이쪽 앞치마 끈이 가위에 잘렸다. 앞치마 아래 이쪽 옆구리도.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, spirit:-6 } },
      { l:'② 이쪽 혼자 일하는 척하며 가위 사이를 지난다.', k:'evade', dc:15,
        ok:`환영 없이 했다. 바닥에서 흙손을 하나 주웠다. 흙을 고르며 걸었다.<br><br>정원사들 사이를 지났다. 가위 하나가 이쪽 귀 옆에서 가지를 쳤다. 일을 하는 중이다. 이쪽도 흙을 골랐다.<br>단 끝에 닿았다. 무리에게 흙손을 하나씩 들게 했다. 같이 건넜다.<br><br>일하는 척은 환영이 아니어도 된다. 다들 그건 할 줄 안다.`,
        ng:`흙을 고르는데 흙 속에 하얀 것이 있었다. 이쪽 손이 멈췄다.<br><br>일을 멈춘 것이다. 정원사들이 일제히 고개를 들었다. 가위가 열렸다.<br>뛰었다. 가위 끝이 등을 긁었다. 흙손은 버리고 왔다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-8 } },
      { l:'③ 정원사들이 일하는 순서를 보고 빈틈을 찾는다.', k:'gaze', dc:14,
        ok:`다섯이 하는 일을 봤다. 물 주고, 치고, 고르고. 같은 순서로 돈다. 돌 때마다 단 동쪽이 잠깐 빈다.<br><br>빈 때에 무리를 하나씩 보냈다. 다섯 번 돌 동안 다섯이 건넜다.<br>이쪽이 마지막이었다. 빈틈이 이쪽 차례에도 있었다.<br><br>일하는 것은 일하는 순서를 안 바꾼다. 사람이었을 때 배운 그대로다.`,
        ng:`순서를 봤는데 넷째 바퀴에 순서가 바뀌었다.<br><br>정원사 하나가 늙어서 느려졌다. 빈틈이 줄었다. 이쪽이 그 빈틈에 있었다.<br>가위가 이쪽 팔을 집었다. 가지처럼. 비틀어 뺐다. 팔뚝이 깊게 그어졌다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, spirit:-4 } }
    ] },

  { at:'C4', t:'중앙 돔 — 여왕 갓 앞',
    x:`중앙 돔 가운데에 큰 갓이 솟았다. 돔을 반쯤 채운다. 갓 밑에서 실이 사방으로 뻗는다.<br><br>
    갓은 볼 줄 안다. 갓 둘레에 눈 같은 혹이 수십 개 열렸다. 다가오는 것을 보면 실을 던진다. 실에 감긴 것은 갓 밑으로 끌려간다. 거기서 하얀 것이 된다.<br>
    동료들이 밑동을 베러 간다. 혹들의 눈을 돌려야 한다.<br><br>
    갓이 보는 것은 무엇인가. 먹이인가, 위협인가.`,
    o:[
      { l:'① 갓 앞에 서서 혹들의 눈을 이쪽으로 끈다.', k:'evade', dc:16,
        doom:{ title:'여왕 갓', what:'하얀 실에 감겨 갓 밑으로 끌려갑니다', dc:15, sec:60,
          text:`갓 앞에 섰다. 이쪽 모습을 셋으로 나눠 흔들었다. 혹들이 셋을 번갈아 본다.<br><br>실이 날아왔다. 셋 다를 향해서. 둘은 통과했다. 하나는 이쪽이었다. 다리를 감았다.<br>끌려간다. 바닥에 등이 쓸린다. 갓 밑이 가까워진다. 밑은 따뜻하고 하얗다. 사람 모양의 하얀 것들이 거기 누웠다. 몇은 아직 숨을 쉰다.<br><br>동료들이 실을 자르러 뛴다. 실이 계속 온다.`,
          dieText:`환영술사는 맞는 것이 늘 진짜가 아닌 쪽이게 한다.<br><br>갓은 하나만 맞으면 됐다. 셋을 다 던졌다.<br>갓 밑에 사람 모양 하얀 것이 하나 늘었다. 그것도 숨을 조금 쉰다.` },
        ok:`갓 앞에 섰다. 이쪽 모습을 셋으로 나눠 흔들었다. 혹들이 셋을 번갈아 본다.<br><br>실이 날아왔다. 셋 다를 향해서. 이쪽은 셋 중 아무 데도 없었다. 셋을 세우고 이쪽은 넷째 자리로 물러나 있었다. 실이 셋을 다 통과해 바닥에 박혔다.<br>갓이 다시 던질 실을 모으는 사이 동료들이 밑동에 닿았다. 칼이 들어갔다. 혹들이 한꺼번에 감겼다.<br><br>보이는 자리에 이쪽을 두지 않았다. 그것이 다다.`,
        win:{ exp:25, dream:4 } },
      { l:'② 마력을 쏟아 갓에게 갓을 보여 준다.', k:'gaze', dc:15, cost:{ mana:22 }, wake:1,
        ok:`갓이 무엇을 두려워할지 생각했다. 갓은 자라는 것이다. 자라는 것이 두려워하는 것은 더 큰 자람이다.<br><br>돔 위에 갓을 하나 더 띄웠다. 이것보다 큰 갓. 실이 더 길고 혹이 더 많은 것. 그 갓의 실이 이 갓을 향해 내려오는 모습.<br>혹들이 위를 봤다. 실을 전부 위로 던졌다. 환영을 향해. 밑동이 비었다. 동료들이 거기를 베었다.<br><br>갓에게 갓을 보여 줬다. 상대가 무엇이든 그것이 무서워하는 것을 그릴 수 있다. 이제 환영의 첫 붓은 상대의 속에서 나온다.`,
        ng:`큰 갓을 띄웠다. 혹들이 봤다. 무서워하지 않았다. 반겼다.<br><br>실이 위로 갔다. 환영과 이어지려고. 이어지지 않자 갓이 혼란에 빠졌다. 실을 사방으로 던졌다. 이쪽에게도.<br>어깨를 감겼다. 동료가 끊었다. 어깨에 하얀 실 뿌리가 박혔다. 뽑아내는 데 살이 같이 나왔다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, spirit:-12 } }
    ] },

  { at:'C', t:'사냥 — 숨어 버린 것',
    x:`다친 것이 굴 깊이 숨었다. 나오지 않는다. 무리가 있는 동안은.<br><br>
    들어가면 굴은 그것 편이다. 좁고 어둡다. 기다리면 그것은 낫는다. 나으면 밤에 나온다.<br>
    그것이 나오게 하려면 무리가 떠나야 한다. 떠난 것처럼 보이면 된다.<br><br>
    환영술사는 있는 것을 없게 보이는 일도 한다.`,
    o:[
      { l:'① 마력으로 굴 앞에서 무리가 떠나는 모습을 보인다.', k:'evade', dc:15, cost:{ mana:18 },
        ok:`무리를 굴 옆 바위 뒤에 숨겼다. 그리고 굴 앞에 무리 다섯을 띄웠다. 짐을 지고 돌아서서 멀어지는 모습. 발소리를 점점 작게.<br><br>환영이 모퉁이를 돌아 사라졌다. 한참 조용했다. 굴 안에서 그것이 고개를 내밀었다. 코를 벌름거린다. 한 걸음 나왔다.<br>바위 뒤에서 동료들이 뛰쳐나갔다. 그것은 굴로 돌아갈 틈이 없었다.<br><br>떠나는 모습은 오는 모습보다 잘 믿는다. 보고 싶었던 것이니까.`,
        ng:`떠나는 무리를 띄웠는데 발소리를 줄이는 걸 잊었다. 발소리가 굴 앞에서 계속 났다.<br><br>그것이 안 나왔다. 대신 굴 안에서 돌이 날아왔다. 이쪽 쪽으로. 이쪽 숨소리를 들은 것이다.<br>이마에 맞았다. 피가 눈으로 흘렀다. 그것은 굴 안에서 낫는 중이다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-14, mind:-8 } },
      { l:'② 굴 입구에 묻은 흔적으로 굴 속 모양을 읽는다.', k:'gaze', dc:14,
        ok:`굴 입구 흙에 그것이 들어간 자국이 있다. 배를 끌고 들어갔다. 자국이 오른쪽으로 휜다.<br><br>오른쪽으로 휘는 굴이다. 휘는 바깥쪽 벽은 얇다. 동료들에게 바깥쪽 벽 위를 파게 했다.<br>벽이 무너지며 그것의 등이 드러났다. 굴 안에서 낫던 것이 낫기 전에 끝났다.<br><br>굴은 그것 편이었다. 굴 모양은 이쪽 편이었다.`,
        ng:`자국을 읽는데 그것이 굴 안에서 이쪽을 보고 있었다. 입구 바로 안에서.<br><br>눈이 마주쳤다. 그것이 튀어나와 이쪽 다리를 물고 끌었다. 굴 안으로 반쯤 들어갔다.<br>동료들이 허리를 잡고 끌어냈다. 정강이에 이가 박혔다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, spirit:-6 } }
    ] },

  { at:'C', t:'쉬는 자리 — 열 없는 불',
    x:`밤이다. 불을 피우면 냄새와 연기가 간다. 안 피우면 어둠 속의 것들이 온다. 불빛을 꺼리는 것들이다.<br><br>
    환영술사는 빛을 만든다. 연기 없는 불, 냄새 없는 불. 열도 없다. 밤새 띄우면 마력이 바닥난다.<br>
    둘레에서 뭔가 맴돈다. 다섯쯤. 빛 바깥에서.<br><br>
    빛만 있으면 되는지, 그것들이 열까지 아는지는 모른다.`,
    o:[
      { l:'① 마력으로 밤새 열 없는 불을 띄운다.', k:'steady', dc:14, cost:{ mana:16 },
        ok:`쉬는 자리 가운데에 불을 띄웠다. 장작까지 그렸다. 타는 소리도 조금.<br><br>둘레에서 맴돌던 것들이 빛 가장자리에서 멈췄다. 넘어오지 않는다. 빛만 알았다. 열은 몰랐다.<br>다들 잤다. 이쪽은 불을 지키느라 졸지 못했다. 새벽에 불을 거뒀다. 둘레의 것들은 없었다.<br><br>장작 그림 위에 손을 대 봤다. 차갑다. 그래도 다들 따뜻하게 잤다고 했다.`,
        ng:`새벽 전에 마력이 흔들렸다. 불이 깜빡였다.<br><br>깜빡이는 사이 빛 가장자리의 하나가 넘어왔다. 잠든 동료 발을 물었다. 다들 깼다.<br>불을 다시 세웠다. 늦었다. 동료 발목이 피투성이다. 이쪽 머리가 깨질 듯하다.`,
        win:{ exp:15, dream:1, spirit:8 }, lose:{ mind:-12, spirit:-6 } },
      { l:'② 불 없이 둘레를 돌며 빛 조각을 여기저기 흩는다.', k:'evade', dc:15,
        ok:`큰 불 대신 작은 빛을 흩었다. 바위 위에 하나, 굴 앞에 하나. 그것들이 오는 길목마다. 마력은 조금씩.<br><br>빛 조각 사이를 돌며 꺼지는 것을 다시 켰다. 그것들이 길목마다 멈췄다. 돌아갔다. 다른 길목으로 왔다. 거기도 빛이다.<br>새벽까지 돌았다. 다리가 무겁다. 마력은 남았다.<br><br>큰 불 하나보다 작은 불 여럿이 더 멀리 지켰다.`,
        ng:`빛 조각을 켜러 굴 앞에 갔다. 그것이 거기 있었다. 빛보다 먼저 왔다.<br><br>이쪽을 덮쳤다. 굴렀다. 빛 조각이 이쪽 손에서 떨어져 그것 얼굴 앞에서 터졌다. 그것이 물러났다.<br>팔뚝에 긴 줄이 그어졌다. 이쪽이 만든 빛에 이쪽이 산 셈이다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } }
    ] },

  { at:'C', t:'사냥 뒤 — 죽은 척하는 것',
    x:`잡은 것이 쓰러졌다. 동료들이 다가간다. 가죽을 벗기려고.<br><br>
    환영술사 눈에 뭔가 걸린다. 쓰러진 것의 배가 오르내리지 않는다. 그런데 눈 둘레 살갗에 이음매가 있다.<br>
    환영의 이음매다. 이 짐승이 이쪽 일을 한다. 죽은 얼굴을 그려 입었다. 서툴게.<br><br>
    동료 하나가 칼을 들고 그 머리 옆에 쪼그려 앉았다.`,
    o:[
      { l:'① 이음매를 찾아 그 자리를 알린다.', k:'gaze', dc:15,
        ok:`이음매를 따라 눈을 옮겼다. 눈 둘레, 콧등, 입가. 입가에서 이음매가 끊겼다. 거기만 덜 그렸다.<br><br>입가 살갗이 아주 조금 떨린다. 숨이다. 동료에게 외쳤다. 입이다. 물러나.<br>동료가 물러나는 순간 그것이 입을 벌렸다. 빈 데를 물었다. 다들 칼을 들고 있었다.<br><br>죽은 얼굴을 그리던 그림이 진짜 죽은 얼굴이 됐다. 이음매가 사라졌다.`,
        ng:`이음매를 찾는데 이쪽 눈이 따라가지 못했다. 이음매가 움직였다.<br><br>그것이 이쪽이 보는 걸 알았다. 그림을 고쳤다. 이음매가 사라졌다. 동료가 칼을 댔다. 그것이 일어나 동료를 덮쳤다.<br>이쪽이 동료를 밀쳤다. 이쪽 어깨가 대신 물렸다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 동료를 잡아당기고 이쪽이 대신 앉는다.', k:'evade', dc:14,
        ok:`동료 어깨를 잡아 뒤로 당겼다. 이쪽이 그 자리에 앉았다. 칼은 안 들었다.<br><br>그것의 머리 옆에 앉아 숨을 맞췄다. 그것이 숨을 참으면 이쪽도 참았다. 오래. 그것이 먼저 숨을 쉬었다. 입이 열리는 순간 이쪽은 뒤로 넘어졌다.<br>이빨이 이쪽 코앞에서 닫혔다. 동료들 칼이 그 목에 들어갔다.<br><br>숨 참기는 이쪽이 이겼다. 그것은 그리는 데만 숨을 썼다.`,
        ng:`뒤로 넘어지는 게 반 박자 늦었다.<br><br>이빨이 턱을 스쳤다. 피가 많이 났다. 동료들이 덮쳐 끝냈다.<br>턱을 동여맸다. 한동안 말을 하기 힘들었다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, mind:-4 } }
    ] },

  { at:'C', t:'끝 무렵 — 바닥난 마력',
    x:`오래 사냥했다. 마력이 바닥났다. 손끝에서 빛 한 줄도 안 나온다.<br><br>
    마지막 굴에서 그것이 나온다. 이쪽을 노린다. 환영을 다루던 자의 냄새를 안다. 환영을 다루던 자는 지금 아무것도 못 한다는 것까지 안다.<br>
    동료들이 멀다. 몇 걸음이 남았다.<br><br>
    환영술사는 환영 없이 무엇인가.`,
    o:[
      { l:'① 환영이 할 일을 몸으로 한다.', k:'evade', dc:15, wake:1,
        ok:`환영을 세울 때처럼 생각했다. 그것이 어디를 볼지. 보는 데에 무엇을 둘지.<br><br>오른쪽으로 비키는 척 어깨를 흔들었다. 그것의 눈이 어깨를 따라갔다. 발은 왼쪽으로 갔다. 그것이 어깨가 간 쪽을 덮쳤다. 빈 데였다.<br>다시 했다. 이번엔 시선을 흘렸다. 이쪽 눈이 본 쪽을 그것도 봤다. 이쪽 몸은 반대로 갔다. 동료들에게 닿았다.<br><br>마력 없이도 환영은 됐다. 보는 것이 어디를 보게 할지 아는 손이 이미 몸 전체에 퍼져 있었다.`,
        ng:`어깨를 흔들었다. 그것이 안 따라왔다. 발을 봤다.<br><br>마력 없는 속임은 몸의 속임이다. 몸은 그것이 더 잘 안다. 덮쳤다. 이쪽 허리를 받았다.<br>동료들이 닿았다. 떼어 냈다. 허리가 끊어질 것 같다.`,
        win:{ exp:25, dream:4 }, lose:{ hp:-18, mind:-6 } },
      { l:'② 등을 벽에 대고 동료들이 올 때까지 버틴다.', k:'steady', dc:14,
        ok:`벽에 등을 붙였다. 뒤는 막혔다. 그것은 앞에서만 온다.<br><br>그것이 덮쳤다. 칼집으로 막았다. 다시. 팔로 막았다. 셋째에 동료들이 닿았다.<br>그것이 돌아서는 순간 다 끝났다.<br><br>막은 팔이 퉁퉁 부었다. 마력이 없으니 이쪽도 그냥 사람이다. 사람으로 버텼다.`,
        ng:`벽이 무른 흙이었다. 등이 밀려 들어갔다.<br><br>그것이 덮쳤다. 막을 틈이 없었다. 가슴을 눌렸다. 숨이 안 쉬어진다.<br>동료들이 왔다. 떼어 냈다. 가슴에 발톱 자국이 넷.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-16, spirit:-6 } }
    ] }
]);

// ── 척후병 (scout) · 무력 ────────────────────
kJob('scout', 'C', [
  { at:'C', t:'사냥터 — 먼저 본 둥지',
    x:`무리가 사냥감을 찾는다. 척후병은 무리 열 걸음 앞이다. 오늘은 스무 걸음이다.<br><br>
    바위 밑에 뼈가 쌓였다. 뼈가 고르다. 다 같은 크기로 부러졌다. 이빨 크기가 같다는 뜻이다.<br>
    뼈 더미 너머에 굴이 셋이다. 굴마다 앞에 긁힌 자국이 있다. 자국 깊이가 다르다.<br><br>
    셋 중 하나에 그것이 산다. 나머지 둘은 그것이 파 둔 것이다.`,
    o:[
      { l:'① 자국 사이를 비켜 다니며 진짜 굴을 가린다.', k:'evade', dc:14, wake:1,
        ok:`굴 앞을 하나씩 지났다. 굴 입구에 몸이 드러나지 않게 비스듬히.<br><br>첫 굴은 자국이 깊은데 흙이 말랐다. 옛날 것이다. 둘째 굴은 자국이 얕은데 흙이 축축하다. 셋째는 자국 위에 다른 자국이 겹쳤다. 나가는 것과 들어오는 것.<br>셋째다. 그리고 첫 굴은 셋째와 땅속으로 이어진다. 흙 무너진 모양이 그쪽으로 기울었다.<br><br>돌아가 무리에게 말했다. 굴 하나가 아니라 굴 둘. 하나는 들어가는 곳, 하나는 도망 나오는 곳. 땅 위 자국으로 땅 아래가 그려졌다. 처음이다.`,
        ng:`둘째 굴 앞을 지날 때 안에서 숨소리가 났다. 이쪽 계산이 틀렸다.<br><br>그것이 고개를 내밀었다. 이쪽을 봤다. 뛰었다. 그것이 쫓아 나왔다. 무리 쪽으로.<br>무리가 준비 없이 맞았다. 이쪽 등에 발톱이 닿았다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 뼈 더미를 뒤져 그것의 크기를 잰다.', k:'sense', dc:14,
        ok:`부러진 뼈 끝을 맞춰 봤다. 이빨 자국 사이가 손가락 셋 너비다. 턱이 사람 어깨만 하다.<br><br>뼈 더미 아래에서 마른 고기 조각이 나왔다. 그것이 남긴 것이다. 남길 만큼 배부르다. 배부른 것은 낮에 잔다.<br>무리에게 알렸다. 크기, 턱, 그리고 지금 잔다는 것.<br><br>본 것보다 알아낸 것이 많았다. 뼈는 말이 많다.`,
        ng:`뒤지는데 뼈 더미가 무너졌다. 소리가 났다.<br><br>굴 셋에서 동시에 소리가 났다. 셋 다 대답이다. 하나가 아니었다.<br>무리에게 뛰어 돌아갔다. 뒤에서 셋이 나왔다. 정강이가 뼈 조각에 찢겼다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-8 } }
    ] },

  { at:'C', t:'굴 — 갈라진 길의 냄새',
    x:`굴이 셋으로 갈렸다. 셋 다 비린내가 난다.<br><br>
    한쪽은 그것이 사는 데다. 한쪽은 그것이 먹이를 두는 데다. 한쪽은 아무것도 아니다. 아무것도 아닌 데가 제일 위험할 때도 있다.<br>
    무리는 지쳤다. 셋을 다 걸을 힘은 없다.<br><br>
    척후병은 셋을 다 보고 와야 하나를 고르게 할 수 있다.`,
    o:[
      { l:'① 무력을 다해 셋 다 달려 보고 온다.', k:'sense', dc:15, cost:{ might:18 },
        ok:`왼쪽 쉰 걸음. 먹이 굴이다. 반쯤 먹힌 것들이 벽에 붙어 있다. 아직 꿈틀대는 것도. 돌아섰다.<br><br>가운데 쉰 걸음. 그것의 굴이다. 잠든 숨소리. 돌아섰다. 오른쪽 쉰 걸음. 아무것도 없다. 바닥이 매끈하다. 너무 매끈하다. 무언가 자주 쓸고 다닌다.<br>돌아와서 말했다. 가운데로 가서 자는 것을 친다. 오른쪽은 절대 안 간다.<br><br>숨이 턱까지 찼다. 무리는 숨을 고른 채로 갔다.`,
        ng:`가운데까지 보고 오른쪽으로 갔다. 매끈한 바닥에서 미끄러졌다.<br><br>바닥이 아래로 기울었다. 미끄러져 내려갔다. 아래에서 뭔가 입을 벌렸다. 벽을 손으로 긁으며 멈췄다.<br>기어 올라왔다. 손톱이 다 깨졌다. 오른쪽에 뭐가 있는지는 반만 알았다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-16, mind:-8 } },
      { l:'② 입구 바닥 자국만 보고 고른다.', k:'gaze', dc:14,
        ok:`세 입구 바닥을 봤다. 왼쪽은 끌린 자국. 먹이를 끌고 들어갔다. 가운데는 발자국이 들어가고 나온다. 사는 데다.<br><br>오른쪽은 자국이 없다. 바닥이 쓸려 있다. 자국을 지우는 무엇이 있다. 그쪽은 버렸다.<br>가운데를 골랐다. 맞았다.<br><br>안 간 굴이 무엇이었는지는 끝내 몰랐다. 몰라도 된다.`,
        ng:`가운데 발자국을 봤다. 들어가고 나온다. 그런데 나온 발자국이 하나 많았다.<br><br>무엇이 아직 밖에 있다는 뜻이다. 그걸 알았을 때 뒤에서 그것이 왔다.<br>무리가 굴 입구에서 맞붙었다. 이쪽 팔이 물렸다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } },
      { l:'③ 무리와 같이 냄새를 맡아 보고 정한다.', k:'bond', dc:13,
        ok:`무리를 입구에 세우고 다 같이 냄새를 맡게 했다. 셋이 다 다르다고 했다.<br><br>썩은 것, 젖은 털, 그리고 아무 냄새도 아닌 것. 아무 냄새도 아닌 것이 오른쪽이다. 거기는 다 같이 싫다고 했다.<br>가운데로 갔다. 다 같이 정한 길이다.<br><br>척후병이 혼자 정하지 않은 날이다. 틀리지 않았다.`,
        ng:`냄새가 다들 달랐다. 서로 우겼다.<br><br>목소리가 커졌다. 가운데 굴에서 숨소리가 멎었다. 그것이 깼다.<br>정하기도 전에 그것이 나왔다. 이쪽이 맨 앞에서 맞았다. 어깨가 찢어졌다.`,
        win:{ exp:14, dream:1, mind:5 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C', t:'사냥 — 그것의 버릇',
    x:`그것을 이틀째 쫓는다. 잡히지 않는다. 무리가 지쳤다.<br><br>
    척후병은 이틀 동안 그것이 지나간 데를 다 봤다. 물 먹는 데, 자는 데, 똥 누는 데.<br>
    짐승은 버릇으로 산다. 괴상한 것도 짐승이면 버릇이 있다.<br><br>
    버릇을 알면 길목을 안다. 길목을 알면 기다릴 수 있다.`,
    o:[
      { l:'① 이틀의 흔적을 이어 길목을 집어낸다.', k:'sense', dc:15, wake:1,
        ok:`본 것을 하나씩 바닥에 그렸다. 물 먹은 데, 잔 데, 지나간 데. 점을 이었다.<br><br>점이 고리가 됐다. 그것은 하루에 한 번 고리를 돈다. 고리에서 제일 좁은 데가 무너진 기둥 사이다. 해 질 녘에 지난다.<br>무리를 기둥 사이에 숨겼다. 해 질 녘에 그것이 왔다. 기다리던 창들이 다 맞았다.<br><br>앞을 보던 눈이 이틀을 봤다. 지난 이틀이 앞날이 됐다. 어디까지 갈지는 아직 모른다.`,
        ng:`점을 잇는데 하나가 안 맞았다. 그것이 하루는 고리를 벗어났다.<br><br>그 하루를 버리고 길목을 골랐다. 해 질 녘에 그것이 안 왔다. 버린 하루의 길로 갔다. 그리고 무리 뒤에서 나왔다.<br>뒤를 맞았다. 이쪽이 맨 뒤였다. 다리를 물렸다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-8 } },
      { l:'② 무력을 실어 이쪽이 미끼가 되어 길목으로 끈다.', k:'evade', dc:15, cost:{ might:18 },
        ok:`그것 앞에 일부러 나섰다. 소리를 질렀다. 그것이 쫓았다. 다리에 힘을 다 실어 뛰었다.<br><br>무너진 기둥 사이로 달렸다. 이쪽은 지났다. 그것은 기둥 사이에서 창들을 만났다.<br>숨을 고르며 돌아봤다. 그것이 기둥 사이에 쓰러져 있다.<br><br>길목을 아는 척후병은 길목으로 데려올 줄도 안다.`,
        ng:`뛰는데 그것이 이쪽보다 빨랐다. 이틀 동안 그건 안 봤다.<br><br>기둥 사이 열 걸음 전에 잡혔다. 등을 덮쳤다. 같이 굴렀다. 무리가 기둥 사이에서 뛰어나왔다.<br>등이 다 찢겼다. 그것도 잡혔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-18, spirit:-4 } }
    ] },

  { at:'C', t:'혼자 앞 — 돌아오지 않는 메아리',
    x:`무리보다 백 걸음 앞이다. 굴이 넓어졌다.<br><br>
    돌을 하나 던졌다. 소리가 돌아온다. 몇 박자인지 세면 굴 크기를 안다. 넷이다. 크다.<br>
    다시 던졌다. 소리가 셋에 돌아왔다. 굴은 그대로인데 소리가 짧아졌다.<br><br>
    굴 안에 굴을 채우는 것이 다가오고 있다.`,
    o:[
      { l:'① 다가오는 것보다 먼저 무리에 닿는다.', k:'evade', dc:15,
        ok:`몸을 돌렸다. 지나온 길이 다 기억난다. 꺾인 데, 낮은 데, 젖은 데. 셈하지 않고 달렸다.<br><br>뒤에서 굴이 좁아지는 소리가 따라온다. 바람이 이쪽 등을 민다. 큰 것이 공기를 밀고 온다.<br>무리에게 닿았다. 외쳤다. 다들 옆 굴로 들어갔다. 큰 것이 지나갔다. 굴 전체가 그것이었다.<br><br>돌을 셋째 던졌으면 소리가 안 돌아왔을 것이다.`,
        ng:`달리다 낮은 데를 잊었다. 이마를 박았다.<br><br>쓰러졌다. 뒤에서 바람이 다가온다. 기어서 옆 틈으로 몸을 밀어 넣었다. 큰 것이 지나갔다. 틈 입구를 긁고.<br>이마에서 피가 흐른다. 무리에게는 늦게 알렸다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 그 자리 벽 틈에 숨어 지나가는 것을 본다.', k:'hide', dc:14,
        ok:`벽 틈에 몸을 넣었다. 숨을 반으로 줄였다.<br><br>그것이 지나갔다. 머리도 꼬리도 없다. 살로 된 둥근 벽이 굴을 따라 미끄러진다. 표면에 작은 입이 수없이 열렸다 닫힌다.<br>다 지나가는 데 백을 셌다. 크기를 알았다. 방향도.<br><br>무리에게 돌아가 다 말했다. 다들 길을 바꿨다.`,
        ng:`틈이 얕았다. 등이 밖에 남았다.<br><br>지나가는 것의 작은 입들이 등을 스쳤다. 스친 데마다 살이 조금씩 뜯겼다.<br>다 지나간 뒤에야 나왔다. 등이 쓰라리다. 본 것은 다 봤다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-8 } }
    ] },

  { at:'C1', t:'계류장 — 몰이꾼의 길',
    x:`계류장 칸막이가 미로처럼 이어진다. 짐승을 라인으로 모는 길이다.<br><br>
    그 안을 몰이꾼이 돈다. 긴 막대를 든 것이다. 막대 끝에 전기가 튄다. 걸린 것은 무엇이든 라인 쪽으로 몬다. 사람도.<br>
    칸막이는 가슴 높이다. 몰이꾼은 그보다 크다. 위에서 다 본다.<br><br>
    척후병은 미로를 먼저 본다. 몰이꾼이 도는 순서까지.`,
    o:[
      { l:'① 몰이꾼이 도는 길을 거꾸로 밟아 빈 칸을 찾는다.', k:'evade', dc:15, wake:1,
        ok:`몰이꾼 뒤를 따라 걸었다. 몰이꾼은 뒤를 안 본다. 앞으로만 몬다.<br><br>세 바퀴를 따라 돌았다. 몰이꾼은 늘 같은 칸에서 꺾는다. 꺾을 때 등지는 칸이 넷이다. 그 넷을 이으면 미로를 가로지르는 길이 된다.<br>무리를 데리고 그 길로 지났다. 몰이꾼은 네 번 다 등지고 있었다.<br><br>따라 걷는 동안 미로가 위에서 내려다보는 그림처럼 머리에 펼쳐졌다. 이쪽 눈이 이쪽 머리 위로 올라간 것 같았다.`,
        ng:`셋째 바퀴에 몰이꾼이 다른 칸에서 꺾었다. 바로 이쪽 앞이었다.<br><br>막대가 내려왔다. 전기가 어깨를 탔다. 몸이 굳었다. 몰이꾼이 막대로 이쪽을 라인 쪽으로 밀었다.<br>무리가 칸막이를 넘어와 끌어냈다. 어깨가 한동안 떨렸다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-8 } },
      { l:'② 무력을 실어 칸막이 문을 막아 몰이꾼을 가둔다.', k:'break', dc:14, cost:{ might:18 },
        ok:`몰이꾼이 막다른 칸에 들어간 순간 그 칸 문을 닫았다. 빗장이 녹슬어 안 걸린다. 무력을 실어 빗장을 비틀어 박았다.<br><br>몰이꾼이 막대로 문을 쳤다. 전기가 튀었다. 문이 버텼다.<br>무리가 미로를 빠져나갔다. 이쪽이 마지막이었다. 뒤에서 막대가 문을 칠 때마다 불꽃이 튀었다.<br><br>손바닥이 녹물에 벗겨졌다. 그 정도면 됐다.`,
        ng:`빗장을 비틀다 빗장이 부러졌다.<br><br>몰이꾼이 문을 밀고 나왔다. 막대가 이쪽 허리를 찔렀다. 전기가 다리까지 내려갔다.<br>쓰러진 이쪽을 무리가 끌고 칸막이를 넘었다. 다리가 한참 남의 것 같았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-18, mind:-4 } }
    ] },

  { at:'C1', t:'정육실 — 배수구 앞',
    x:`정육실 바닥 가운데에 배수구가 있다. 크다. 사람이 들어갈 만하다.<br><br>
    배수구 둘레 바닥이 젖었다. 다른 데보다 깨끗하다. 누가 자꾸 핥은 것처럼.<br>
    척후병은 깨끗한 바닥을 의심한다. 깨끗한 데는 무언가 자주 다니는 데다.<br><br>
    무리가 이 방을 건너야 한다. 배수구를 지나서.`,
    o:[
      { l:'① 배수구 가장자리를 먼저 지나 본다.', k:'evade', dc:15,
        doom:{ title:'배수구', what:'뼈 없는 것에 감겨 배수구로 끌려갑니다', dc:15, sec:55,
          text:`배수구 가장자리를 비켜 걸었다. 반쯤 지났을 때 쇠살 틈에서 뭔가 흘러나왔다.<br><br>살이다. 뼈가 없는 살. 바닥을 미끄러져 이쪽 발목을 감았다. 감고 나서 당긴다. 배수구 쪽으로.<br>쇠살 틈은 좁다. 살은 좁은 데로 들어간다. 이쪽 발도 들어가고 있다. 무릎까지.<br><br>뒤에서 무리가 뛰어온다. 살이 더 흘러나와 허리를 감는다.`,
          dieText:`척후병은 깨끗한 바닥을 의심했다. 그래서 먼저 갔다.<br><br>의심이 맞았다. 맞은 것을 알릴 입이 배수구 아래에 있다.<br>배수구 둘레가 다시 깨끗해졌다. 무리는 그 바닥을 건너지 않았다.` },
        ok:`배수구를 크게 비켜 걸었다. 가장자리에서 세 걸음 떨어져.<br><br>쇠살 틈에서 살이 흘러나왔다. 바닥을 더듬었다. 이쪽 발 한 뼘 앞까지 왔다. 세 걸음은 그것이 닿는 거리보다 길었다.<br>건너편에 닿아 무리에게 외쳤다. 세 걸음. 그보다 가까이 오지 마라.<br><br>무리가 벽을 따라 건넜다. 살은 배수구 둘레를 핥고 들어갔다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 바닥 깨끗한 자국의 너비를 재고 길을 잡는다.', k:'sense', dc:14,
        ok:`깨끗한 바닥이 어디서 끝나는지 봤다. 배수구에서 사방 두 걸음 반. 그 너머는 기름때가 그대로다.<br><br>그것이 닿는 데까지만 깨끗하다. 기름때를 밟고 가면 된다.<br>무리를 기름때 위로 이끌었다. 미끄럽다. 서로 손을 잡고 건넜다.<br><br>배수구 쇠살 아래에서 무엇이 이쪽 발소리를 따라 움직였다. 따라오지는 못했다.`,
        ng:`재는데 깨끗한 자국 끝이 움직였다. 넓어지고 있었다.<br><br>그것이 지금 나오는 중이었다. 물러났다. 늦었다. 발끝이 감겼다. 칼로 끊었다. 끊긴 살이 바닥에서 꿈틀댄다.<br>발가락에 감긴 자국이 하얗다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-8 } }
    ] },

  { at:'C1', t:'냉동 창고 — 닫히는 문',
    x:`냉동 창고 문이 두껍다. 열려 있다. 열린 채 조금씩 닫힌다. 문이 무겁다.<br><br>
    안을 봐야 한다. 무리가 들어가도 되는지. 들어갔다가 문이 닫히면 안에서는 안 열린다. 손잡이가 바깥에만 있다.<br>
    안쪽 구석에 배급 상자가 보인다. 그리고 상자 옆에 서리가 덮인 것이 앉아 있다. 사람 모양이다.<br><br>
    척후병은 혼자 들어갔다가 혼자 나온다.`,
    o:[
      { l:'① 무력을 다해 문이 닫히기 전에 다녀온다.', k:'evade', dc:15, cost:{ might:18 },
        ok:`다리에 힘을 다 실어 뛰어들었다. 매달린 고깃덩이 사이를 지나 상자까지.<br><br>상자를 열었다. 말린 고기 꾸러미. 들고 돌아섰다. 서리 덮인 것이 고개를 들었다. 서리가 떨어진다. 아래가 사람이 아니다.<br>문 틈이 한 뼘 남았을 때 몸을 옆으로 세워 빠져나왔다. 문이 닫혔다. 안에서 문을 긁는 소리가 났다.<br><br>무리에게 말했다. 여기는 안 들어간다.`,
        ng:`상자까지는 갔다. 돌아올 때 고깃덩이 하나가 갈고리에서 떨어져 길을 막았다.<br><br>돌아서 왔다. 문 틈이 좁다. 어깨가 걸렸다. 무리가 문을 붙잡고 당겼다. 빠져나왔다. 어깨가 문에 짓눌렸다.<br>꾸러미는 안에 두고 왔다. 서리 덮인 것이 그걸 집는 게 문틈으로 보였다.`,
        win:{ exp:20, item:'말린 고기' }, lose:{ hp:-16, mind:-6 } },
      { l:'② 문 경첩에 쐐기를 박아 닫히지 않게 한다.', k:'fix', dc:14,
        ok:`문 아래 경첩 틈에 쇠 갈고리를 박았다. 돌로 두드려 깊게.<br><br>문이 닫히다 멈췄다. 사람 하나 지날 틈이 남았다. 그 틈이면 돌아 나올 수 있다.<br>무리에게 안을 보여 줬다. 서리 덮인 것도. 다들 그걸 피해 구석 상자를 꺼내 왔다.<br><br>쐐기는 박아 둔 채로 나왔다. 다음에 올 사람을 위해.`,
        ng:`쐐기를 박다 문이 멈추지 않고 쐐기를 밀었다.<br><br>쐐기가 튀었다. 이쪽 정강이를 쳤다. 문이 닫혔다. 안을 못 봤다.<br>안에서 문을 긁는 소리가 났다. 문이 닫혀서 다행이라고 다들 말했다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-12, mind:-6 } }
    ] },

  { at:'C2', t:'공방 계단 — 층마다 다른 실',
    x:`공방은 위로 올라간다. 계단이 층마다 꺾인다.<br><br>
    층계참마다 천장에서 실이 내려온다. 층마다 실 색이 다르다. 아래층은 흰 실, 위층은 누런 실. 위로 갈수록 실이 굵다.<br>
    실이 굵은 데는 실을 쥔 것과 가깝다.<br><br>
    척후병은 무리보다 한 층 먼저 올라간다. 한 층이 얼마나 먼지는 층마다 다르다.`,
    o:[
      { l:'① 한 층씩 먼저 올라 실의 결을 읽고 내려온다.', k:'evade', dc:15, wake:1,
        ok:`한 층 올라 층계참 실을 봤다. 실이 팽팽한 데와 늘어진 데. 늘어진 데로 지나면 실이 안 운다.<br><br>내려와 알리고, 다시 올랐다. 세 층을 그렇게 했다. 셋째 층에서 알았다. 실이 팽팽한 쪽이 늘 같은 벽이다. 실을 쥔 것이 그쪽에 있다. 위층이 어디로 기울었는지 실이 말해 준다.<br>무리를 늘어진 쪽 벽으로만 올렸다. 한 번도 실이 안 울었다.<br><br>층 하나를 보던 눈이 건물 하나를 봤다. 계단을 다 오르기 전에 맨 위가 어디 있는지 알았다.`,
        ng:`셋째 층에서 늘어진 실 하나가 갑자기 팽팽해졌다.<br><br>위에서 당긴 것이다. 실이 이쪽 목 앞을 가로질렀다. 목을 젖혔다. 턱이 실에 베였다.<br>내려와 알렸는데 목소리가 안 나왔다. 손짓으로 했다. 턱에서 피가 떨어진다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-14, mind:-8 } },
      { l:'② 층계참 벽에 남은 이전 사람들의 표식을 찾는다.', k:'sense', dc:13,
        ok:`벽을 훑었다. 손톱으로 긁은 자국이 있다. 화살표. 누가 먼저 이 계단을 올랐다.<br><br>화살표가 늘어진 실 쪽을 가리킨다. 따라갔다. 다음 층계참에도 있다. 그 사람도 척후였던 모양이다. 긁은 높이가 늘 같다. 허리 높이.<br>넷째 층계참에는 화살표가 없었다. 거기서부터는 이쪽이 긁으며 올랐다.<br><br>허리 높이로.`,
        ng:`표식을 찾았다. 따라갔다. 넷째 층계참에서 표식이 실 한가운데를 가리켰다.<br><br>표식을 긁은 사람이 마지막에 틀렸다. 아니면 누가 표식을 고쳤다. 실이 울었다. 위에서 인형들이 내려왔다.<br>무리를 다시 아래로 뺐다. 팔에 이 자국 둘.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-6 } }
    ] },

  { at:'C2', t:'털 방 — 토끼장',
    x:`인형에 털을 심는 방이다. 벽을 따라 토끼장이 줄지어 있다.<br><br>
    토끼가 산다. 진짜 토끼다. 털을 뽑히고 다시 자라면 또 뽑힌다. 다들 반쯤 벗겨졌다.<br>
    토끼장 사이 바닥에 인형이 하나 엎드려 있다. 토끼를 지키는 것이다. 털 뽑는 집게를 손에 쥐었다.<br><br>
    무리의 먹을 것이 바닥났다.`,
    o:[
      { l:'① 지키는 인형이 고개를 돌린 사이 토끼장 하나를 연다.', k:'luck', dc:14,
        ok:`인형이 다른 토끼장 쪽으로 고개를 돌렸다. 집게를 들었다. 털을 뽑으러 간다.<br><br>그 사이 맨 끝 토끼장을 열었다. 토끼 하나가 이쪽 손에 안겼다. 털이 다 자란 것이다. 뽑힐 차례였다.<br>품에 안고 나왔다. 인형은 뽑을 털이 하나 없어진 걸 모른다. 아직.<br><br>요리사가 토끼를 오래 쓰다듬다가 일어섰다.`,
        ng:`토끼장 문이 녹슬어 울었다.<br><br>인형이 돌아봤다. 집게를 든 채 기어 왔다. 이쪽 팔을 집었다. 털 대신 살갗을 뽑았다.<br>팔을 빼고 물러났다. 팔뚝에 작은 구멍이 줄지어 났다.`,
        win:{ exp:15, item:'짐승 고기' }, lose:{ hp:-12, mind:-6 } },
      { l:'② 인형이 엎드린 자리를 피해 방을 가로지른다.', k:'evade', dc:14,
        ok:`인형은 엎드려서 바닥만 본다. 발을 보고 쫓는다.<br><br>토끼장 위를 짚고 발을 바닥에 안 대고 지났다. 손으로만. 토끼들이 이쪽 손가락을 핥았다.<br>방 끝에 닿았다. 무리에게 똑같이 하라고 했다.<br><br>인형은 바닥만 봤다. 바닥에 아무도 없었다.`,
        ng:`토끼장 하나가 이쪽 무게에 기울었다.<br><br>토끼들이 놀라 뛰었다. 인형이 고개를 들었다. 처음으로 위를 봤다. 이쪽을.<br>집게가 이쪽 발을 집었다. 신발을 버리고 왔다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-10, spirit:-8 } }
    ] },

  { at:'C2', t:'다락 입구 — 천장의 구멍',
    x:`다락으로 가는 사다리가 천장 구멍으로 이어진다.<br><br>
    구멍 위는 어둡다. 실이 구멍 가장자리에서 늘어져 있다. 실 끝이 조금씩 흔들린다. 바람이 없는데.<br>
    누군가 먼저 머리를 올려 봐야 한다. 위에 무엇이 기다리는지.<br><br>
    척후병의 머리가 제일 먼저 올라간다. 그게 척후다.`,
    o:[
      { l:'① 사다리를 올라 머리만 내밀어 본다.', k:'evade', dc:16,
        doom:{ title:'천장 구멍', what:'천장 구멍으로 끌려 올라갑니다', dc:15, sec:55,
          text:`사다리를 올라 머리를 구멍 위로 내밀었다. 눈이 어둠에 익기를 기다렸다.<br><br>익기 전에 실이 목에 감겼다. 가는 실이 여러 겹. 위로 당긴다. 사다리에서 발이 떨어졌다. 어깨까지 구멍에 들어갔다.<br>위에서 손이 이쪽 머리를 쓰다듬는다. 사기 손이다. 얼굴을 더듬는다. 이를 센다.<br><br>아래에서 무리가 이쪽 다리를 잡았다. 위에서 당기는 힘이 더 세다.`,
          dieText:`척후병의 머리가 제일 먼저 올라간다.<br><br>오늘은 머리만 올라갔다. 나머지는 나중에 올라갔다.<br>다락의 인형 하나가 새 이를 받았다. 척후병이 남보다 먼저 본 것을 그 인형이 이제 본다.` },
        ok:`머리를 내밀기 전에 칼을 먼저 올렸다. 칼날을 구멍 위로 비췄다. 날에 위가 비친다.<br><br>실이 칼에 감겼다. 위에서 당긴다. 칼을 놓았다. 칼이 올라갔다. 위에서 칼을 만지는 소리가 났다. 칼은 이가 없다. 실망한 듯 떨어뜨렸다.<br>그 사이 날에 비친 것을 봤다. 구멍 바로 위에 셋. 실을 쥐고 엎드려 있다.<br><br>무리에게 셋이라고 했다. 구멍을 통째로 부수고 올라가기로 했다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 무력을 실어 구멍 둘레 널을 뜯어 넓힌다.', k:'steady', dc:15, cost:{ might:20 },
        ok:`사다리를 버리고 구멍 둘레 천장 널을 아래에서 잡아 뜯었다. 힘을 다 실었다. 널이 하나씩 떨어진다.<br><br>구멍이 넓어졌다. 위의 것들이 엎드린 자리가 드러났다. 셋이다. 갑자기 빛 아래에 놓였다. 실을 쥔 손이 멈췄다.<br>무리가 넓어진 구멍으로 한꺼번에 올라갔다. 좁은 데로 하나씩 올라갔으면 하나씩 당겨졌을 것이다.<br><br>팔이 한참 떨렸다.`,
        ng:`널을 뜯는데 위에서 널을 같이 잡았다. 반대로 당긴다.<br><br>이쪽 팔이 널과 같이 구멍으로 들어갔다. 실이 손목에 감겼다. 무리가 이쪽을 잡아당겼다. 손목이 빠졌다. 실에 살갗이 감겨 남았다.<br>널은 반만 뜯었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'③ 무리와 함께 구멍 아래 실을 하나씩 끊어 둔다.', k:'bond', dc:14,
        ok:`늘어진 실을 무리와 하나씩 잡았다. 셋을 세고 같이 끊었다.<br><br>위에서 당기던 것들이 한꺼번에 뒤로 넘어지는 소리가 났다. 실을 쥔 채로. 그 소리로 몇인지 알았다. 셋.<br>올라가 보니 셋이 엎어져 있었다. 일어나기 전에 끝냈다.<br><br>혼자 끊었으면 하나씩 당겨졌을 것이다.`,
        ng:`셋을 셌는데 한 사람이 둘에 끊었다.<br><br>실 하나가 먼저 끊기자 나머지가 당겨졌다. 그 실을 쥔 손들이 위로 들렸다. 이쪽 손도.<br>놓았다. 손바닥이 실에 베였다. 위의 것들이 알았다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-12, mind:-8 } }
    ] },

  { at:'C3', t:'거꾸로 선 회랑 — 위아래가 바뀐 길',
    x:`성당이 거꾸로다. 위로 올라가던 계단이 아래로 내려간다. 내려가던 길은 머리 위에 붙었다.<br><br>
    무리가 헷갈린다. 왼쪽 오른쪽까지 헷갈린다. 거꾸로 선 성당에서는 문도 거꾸로 열린다.<br>
    척후병은 길을 머리에 그린다. 그림이 뒤집히면 다시 그려야 한다.<br><br>
    첨탑 끝으로 가야 한다. 첨탑은 지금 발밑 깊은 데에 있다.`,
    o:[
      { l:'① 뒤집힌 그대로 길을 다시 그린다.', k:'sense', dc:15, wake:1,
        ok:`눈을 감았다. 들어올 때 본 성당을 떠올렸다. 바로 선 성당. 그리고 그 그림을 머릿속에서 뒤집었다.<br><br>뒤집힌 그림 위에 지금 선 자리를 찍었다. 첨탑은 회랑 끝 계단 아래다. 문은 경첩이 위에 달렸으니 아래로 연다.<br>그 길로 무리를 이끌었다. 한 번도 안 막혔다.<br><br>그림을 뒤집을 수 있으면 돌릴 수도 있다. 어느 쪽에서 들어가도 길은 하나다. 이쪽 머릿속 그림이 처음으로 종이가 아니라 덩어리가 됐다.`,
        ng:`뒤집다가 좌우까지 뒤집었다.<br><br>이쪽이 고른 문은 반대편이었다. 문을 열자 아래가 비었다. 아래로 떨어질 뻔했다. 문틀을 잡았다.<br>되돌아오는 데 한참 걸렸다. 무리가 지쳤다. 손바닥이 문틀 쇠에 찢겼다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-12, mind:-10 } },
      { l:'② 무력을 실어 내려가는 기둥을 타고 지름길을 본다.', k:'evade', dc:15, cost:{ might:18 },
        ok:`기둥이 아래로 뻗었다. 원래는 천장을 받치던 기둥이다. 지금은 깊은 데로 내려가는 길이다.<br><br>힘으로 기둥을 붙잡고 미끄러져 내려갔다. 반쯤 내려가서 아래를 봤다. 첨탑 지붕 끝이 보인다. 기둥 끝이 첨탑 옆 회랑에 닿는다.<br>올라와서 무리에게 줄을 내렸다. 계단으로 돌면 반나절 길이 한 시간이 됐다.<br><br>팔이 떨린다. 거꾸로 된 성당에서는 지름길도 거꾸로다.`,
        ng:`미끄러지다 기둥에 붙은 것이 있었다. 기둥 색과 같다.<br><br>그것이 손을 물었다. 놓쳤다. 떨어졌다. 아래 회랑 난간에 걸렸다. 갈비가 난간에 찍혔다.<br>무리는 결국 계단으로 내려왔다. 이쪽을 데리러.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-18, mind:-4 } }
    ] },

  { at:'C3', t:'회랑 — 홈통에 사는 것',
    x:`회랑 벽을 따라 홈통이 지난다. 홈통 끝마다 돌 짐승 머리가 입을 벌렸다.<br><br>
    그 입에서 무언가 나와 회랑을 기어 다닌다. 길쭉하다. 젖었다. 머리가 홈통 끝 돌 머리와 같은 모양이다.<br>
    회랑을 지나는 것이 있으면 홈통으로 끌고 들어간다. 홈통은 좁다. 끌려간 것은 길쭉해진다.<br><br>
    회랑은 길다. 홈통 끝 머리가 열둘이다.`,
    o:[
      { l:'① 돌 머리 입이 닫힌 데만 골라 지난다.', k:'evade', dc:15,
        ok:`돌 머리를 하나씩 봤다. 입이 벌어진 것과 다문 것. 다문 머리 아래는 지금 비었다. 그것이 안에 있다.<br><br>벌어진 머리 아래는 그것이 나와 있다는 뜻이다. 회랑 어딘가에. 벌어진 데는 다 피했다. 다문 데 아래로만 지났다.<br>열두 머리를 다 지났다. 회랑 바닥에서 젖은 것이 한 번 지나갔다. 이쪽 뒤로.<br><br>무리에게 다문 입 아래로만 오라고 했다. 셋이 열렸다 닫히는 동안 다 왔다.`,
        ng:`다문 줄 알았던 머리가 반쯤 열려 있었다. 어둠 속이라 틈이 안 보였다.<br><br>그 아래를 지날 때 위에서 그것이 떨어졌다. 이쪽 어깨에. 젖은 것이 목을 감았다. 홈통 쪽으로 당긴다.<br>무리가 칼로 잘랐다. 목에 젖은 자국이 둥글다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, spirit:-6 } },
      { l:'② 회랑 기둥 그늘을 따라 숨어 간다.', k:'hide', dc:14,
        ok:`기둥과 기둥 사이 그늘이 짙다. 그늘에서 그늘로 갔다. 멈출 때는 기둥에 등을 붙였다.<br><br>젖은 것이 회랑을 기어 지나갔다. 기둥 그늘을 안 본다. 회랑 가운데만 본다.<br>끝까지 갔다. 무리도 그늘로 왔다.<br><br>돌 머리들 입에서 물이 떨어진다. 그 소리 덕에 이쪽 발소리가 묻혔다.`,
        ng:`셋째 기둥 그늘에 이미 무엇이 있었다. 젖은 것이 거기서 쉬고 있었다.<br><br>이쪽 등이 그것에 닿았다. 차갑다. 그것이 감았다. 기둥째.<br>무리가 와서 떼어 냈다. 허리에 젖은 줄이 감긴 자국.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C3', t:'종지기 — 줄 당기는 소리',
    x:`성당 깊은 데서 종이 운다. 정해진 박자로. 누가 당긴다.<br><br>
    종지기다. 종 줄을 당기는 것. 종이 울면 성당 안의 것들이 깨어난다. 종이 그치면 다시 잠든다.<br>
    종이 울 때마다 무리 앞뒤에서 무엇이 움직인다. 종이 그칠 때까지 버텨야 한다.<br><br>
    척후병은 종지기가 어디 있는지 알고 싶다. 박자를 아는 것보다 줄을 아는 게 낫다.`,
    o:[
      { l:'① 종소리가 오는 쪽을 쫓아 줄 끝을 찾는다.', k:'evade', dc:15, wake:1,
        ok:`종이 울 때 귀를 기울였다. 소리가 벽을 타고 온다. 벽마다 늦게 오는 데와 빨리 오는 데가 있다. 빨리 오는 벽 쪽으로 갔다.<br><br>종이 울 때마다 깨어나는 것들 사이를 비켜 갔다. 다섯 번 울릴 동안. 줄이 보였다. 줄 끝에 길고 마른 것이 매달려 당긴다.<br>무리에게 돌아가 줄 위치를 알렸다. 무리가 줄을 끊으러 갔다. 종이 그쳤다. 성당이 조용해졌다.<br><br>소리가 오는 길이 눈에 보이는 길처럼 그려졌다. 이제 소리만 들어도 어디서 오는지 발이 먼저 간다.`,
        ng:`소리를 쫓는데 메아리를 쫓았다. 진짜 소리는 반대편이다.<br><br>메아리 끝에는 깨어난 것들만 있었다. 셋이 이쪽을 돌아봤다. 뛰었다. 다리를 긁혔다.<br>무리에게 돌아갔을 때 종이 또 울었다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-8 } },
      { l:'② 종이 그친 틈에 종탑 아래 벌집을 턴다.', k:'luck', dc:14,
        ok:`종탑 아래 들보에 벌집이 붙었다. 성당 초를 만들던 벌집이다. 벌은 종소리에 다 떠났다.<br><br>종이 그쳤다. 그 틈에 들보에 올라 벌집 한 귀퉁이를 떼어 냈다. 굳은 꿀이 들었다.<br>내려오는데 종이 다시 울었다. 들보가 떨렸다. 꿀을 품에 안고 뛰어내렸다.<br><br>성당이 뒤집혀도 벌은 위에 집을 지었다. 지금 위가 어디든.`,
        ng:`벌집을 떼는데 종이 예정보다 빨리 울었다.<br><br>들보가 떨렸다. 떨어졌다. 벌집도 같이. 깨어난 것 하나가 떨어진 벌집으로 왔다. 이쪽에게도.<br>꿀은 그것에게 줬다. 이쪽은 등을 긁혔다.`,
        win:{ exp:15, item:'꿀 한 줌' }, lose:{ hp:-12, spirit:-6 } }
    ] },

  { at:'C4', t:'계단식 온실 — 단을 내려다보기',
    x:`온실은 가운데로 갈수록 낮아진다. 단이 다섯이다. 맨 아래가 중앙 돔이다.<br><br>
    유리가 김에 뿌옇다. 단 아래가 잘 안 보인다. 하얀 것이 단마다 다르게 깔렸다. 어떤 단은 얇고 어떤 단은 무릎까지 찼다.<br>
    지붕 골조 위로 오르면 다섯 단이 한눈에 보일 것이다. 지붕 골조 끝에 빗물 받이가 있다.<br><br>
    무리의 물이 떨어졌다.`,
    o:[
      { l:'① 무력을 실어 골조를 타고 올라 다섯 단을 본다.', k:'evade', dc:15, cost:{ might:18 },
        ok:`기둥을 힘으로 타고 올라 골조에 엎드렸다. 김 위로 머리가 나왔다. 유리 너머로 다섯 단이 보였다.<br><br>둘째 단은 얇다. 셋째 단 동쪽이 비었다. 넷째 단에는 움직이는 것이 셋. 다섯째 돔 둘레에 하얀 것이 고리로 쌓였다.<br>빗물 받이 통에서 물을 받았다. 유리 위에 내린 비다. 맑다.<br><br>내려와서 바닥에 다섯 단을 그려 줬다. 어디로 내려갈지 다들 손가락으로 따라 그었다.`,
        ng:`골조 이음매가 녹슬어 꺾였다.<br><br>골조째 기울었다. 유리 한 장을 깨고 매달렸다. 깨진 유리 사이로 김이 쏟아져 나왔다. 하얀 가루가 섞였다.<br>숨을 참고 내려왔다. 손바닥이 유리에 베였다. 단은 반만 봤다.`,
        win:{ exp:20, item:'맑은 물' }, lose:{ hp:-16, mind:-6 } },
      { l:'② 단 가장자리 배수로를 따라 내려가며 길을 잰다.', k:'sense', dc:14,
        ok:`단마다 가장자리에 배수로가 있다. 물이 흐르던 돌 홈이다. 하얀 것이 물을 싫어한다. 홈은 깨끗하다.<br><br>홈을 따라 한 단씩 내려가 봤다. 홈 바닥에 아직 물이 조금 흐른다. 홈은 돔 앞까지 이어진다.<br>올라와서 무리에게 말했다. 홈으로 간다. 발목이 젖겠지만 하얘지지는 않는다.<br><br>정원사들이 만든 길이다. 정원사들은 그 길을 잊었다.`,
        ng:`셋째 단 홈이 막혀 있었다. 하얀 것이 홈을 메웠다.<br><br>발을 넣었다. 실이 감겼다. 빼는 사이 다른 실이 무릎까지 올라왔다. 칼로 끊었다.<br>돌아와서 셋째 단부터는 모른다고 했다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-8 } }
    ] },

  { at:'C4', t:'온실 — 짐승들이 다니는 길',
    x:`하얀 것이 짐승을 입고 다닌다. 개, 고양이, 큰 새. 입은 짐승이 다니던 길로 다닌다.<br><br>
    짐승은 길을 낸다. 화분 사이, 선반 밑, 깨진 유리 틈. 하얀 것은 그 길을 그대로 쓴다. 길 위에 가루를 흘린다.<br>
    무리가 지나갈 길과 짐승 길이 겹친다. 어디서 겹치는지 알아야 한다.<br><br>
    척후병은 짐승 길을 안다. 입은 것이 무엇이든.`,
    o:[
      { l:'① 가루 흘린 길을 비켜 다니며 겹치는 데를 찾는다.', k:'evade', dc:15, wake:1,
        ok:`가루가 흘린 줄을 봤다. 짐승 길이다. 줄을 밟지 않고 옆을 따라 걸었다. 줄이 갈라지고 모이는 데를 하나씩 셌다.<br><br>모이는 데가 넷이다. 거기서 짐승을 입은 것들이 마주친다. 마주칠 때 서로 냄새를 맡느라 멈춘다. 멈추는 동안은 다른 데를 안 본다.<br>무리를 모이는 데 옆으로 지나게 했다. 그것들이 서로 냄새를 맡을 때마다.<br><br>길을 보는 게 아니라 길 위의 것들이 언제 멈추는지를 봤다. 길에 박자가 있었다. 이제 길을 들으면 박자가 같이 들린다.`,
        ng:`모이는 데를 셋까지 셌다. 넷째는 선반 밑이라 안 보였다.<br><br>무리가 넷째 앞을 지날 때 선반 밑에서 개를 입은 것이 나왔다. 이쪽 다리를 물었다. 개 이빨이다. 안에서 실이 상처를 더듬는다.<br>불로 지졌다. 다리가 탄 냄새를 풍긴다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, spirit:-8 } },
      { l:'② 짐승 길 옆 덤불 화분 사이에 숨어 지나가길 기다린다.', k:'hide', dc:14,
        ok:`큰 화분 사이에 무리와 같이 웅크렸다. 잎이 넓다. 하얀 것이 안 탔다.<br><br>짐승을 입은 것들이 지나갔다. 개, 새, 다시 개. 하나가 화분 앞에서 멈췄다. 냄새를 맡는다. 잎 냄새가 진하다.<br>지나갔다. 다 지나간 뒤에 나왔다.<br><br>잎 냄새가 무리 옷에 배었다. 다음 단에서도 쓸 수 있을 것이다.`,
        ng:`화분 하나가 하얀 것의 둥지였다. 잎 아래가 실이었다.<br><br>웅크린 이쪽 등에 실이 감겼다. 소리를 낼 수 없었다. 짐승을 입은 것들이 지나가는 중이다.<br>다 지나갈 때까지 참았다. 그 뒤에 떼어 냈다. 등에 하얀 자국이 그물처럼 남았다.`,
        win:{ exp:16, dream:2 }, lose:{ mind:-10, spirit:-8 } },
      { l:'③ 무력을 실어 길목의 선반을 무너뜨려 길을 막는다.', k:'break', dc:15, cost:{ might:20 },
        ok:`짐승 길이 모이는 선반 밑 길목을 봤다. 선반을 힘껏 밀었다. 화분째 무너졌다.<br><br>길목이 막혔다. 짐승을 입은 것들이 막힌 데 앞에서 멈췄다. 돌아가는 길을 모른다. 짐승은 버릇대로만 다닌다.<br>무리는 막힌 데 반대편으로 지났다.<br><br>무너진 화분에서 흙이 쏟아졌다. 그 흙에 나물이 몇 포기 섞였다. 그건 안 챙겼다. 실이 감겨 있었다.`,
        ng:`선반이 반만 무너졌다. 소리가 컸다.<br><br>짐승을 입은 것들이 소리 쪽으로 몰려왔다. 길목을 막은 게 아니라 이쪽을 알렸다.<br>무리가 흩어졌다. 이쪽 팔이 새 부리에 찍혔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C4', t:'중앙 돔 입구 — 먼저 들어간 사람',
    x:`중앙 돔 입구에 사람이 서 있다. 등을 보이고. 정원사 옷이 아니다. 이쪽 같은 옷이다.<br><br>
    전에 들어온 무리의 척후다. 허리에 표식 숯이 매달렸다. 돔 안을 보고 있다. 움직이지 않는다.<br>
    그 사람 발밑에서 하얀 실이 올라와 종아리를 감았다. 종아리부터 하얗다.<br><br>
    그 사람이 무엇을 봤는지 알고 싶다. 무엇을 봤기에 멈췄는지.`,
    o:[
      { l:'① 그 사람 옆에 서서 같은 데를 본다.', k:'evade', dc:15,
        doom:{ title:'먼저 간 척후', what:'하얀 실에 감겨 돔 안으로 끌려갑니다', dc:15, sec:60,
          text:`그 사람 옆에 섰다. 같은 데를 봤다. 돔 가운데 큰 갓. 갓 밑에 사람들이 누워 있다. 다 하얗다.<br><br>보는 사이 발밑에서 실이 올라왔다. 종아리를 감았다. 당긴다. 돔 안으로. 옆의 척후가 고개를 돌려 이쪽을 봤다. 얼굴이 하얗다. 입이 움직인다. 아무 소리도 안 난다.<br>끌려간다. 갓 쪽으로. 무리가 입구에서 이쪽 이름을 부른다.<br><br>그 척후가 무엇을 봤는지 이제 안다. 알릴 수 없을 뿐이다.`,
          dieText:`척후병은 남보다 먼저 가서 본다.<br><br>먼저 간 척후 옆에 척후가 하나 더 섰다. 둘 다 같은 데를 본다.<br>다음 무리가 오면 입구에 둘이 서 있을 것이다. 등을 보이고.` },
        ok:`옆에 서지 않았다. 그 사람 등 뒤 세 걸음에서 멈췄다. 그 사람 어깨 너머로 봤다.<br><br>돔 가운데 큰 갓. 갓 밑에 하얀 사람들. 그리고 그 사람 발밑에서 시작된 실이 바닥을 따라 돔 입구 전체에 깔려 있었다. 서는 자리마다 실이 기다린다.<br>무리에게 외쳤다. 입구 바닥 밟지 마라. 무리가 입구 위 틀을 타고 넘었다.<br><br>넘어가며 그 척후 허리의 숯을 챙겼다. 그 사람 대신 표식을 남기기로 했다.`,
        win:{ exp:25, dream:4 } },
      { l:'② 무리와 함께 그 사람을 끌어내 본다.', k:'bond', dc:14,
        ok:`무리와 그 사람 어깨를 잡았다. 셋을 세고 같이 당겼다.<br><br>종아리 실이 끊겼다. 그 사람이 뒤로 넘어졌다. 하얀 데는 종아리까지다. 무릎 위는 아직 사람이다. 눈이 감겼다가 떴다.<br>그 사람이 입을 열었다. 목소리가 갈라졌다. 갓 밑동, 남쪽. 그 말만 하고 다시 눈을 감았다.<br><br>남쪽 밑동. 먼저 간 척후가 본 것을 받았다.`,
        ng:`당기는데 그 사람이 안 움직였다. 실이 종아리가 아니라 그 사람 전부에 이어져 있었다.<br><br>당긴 무리 쪽으로 실이 옮겨 왔다. 이쪽 손목을 감았다. 손을 놓았다. 손목에 하얀 실 뿌리가 남았다.<br>그 사람은 그대로 돔 안을 본다.`,
        win:{ exp:18, dream:2, spirit:5 }, lose:{ hp:-12, spirit:-10 } }
    ] },

  { at:'C', t:'사냥 끝 — 돌아가는 길',
    x:`잡았다. 크다. 무리가 지쳤다. 다친 사람도 있다.<br><br>
    이제 돌아가야 한다. 온 길이 길었다. 굴이 여러 번 갈렸다. 몇 군데는 무너졌다. 사냥하는 동안.<br>
    잡은 것의 피 냄새가 굴을 따라 퍼진다. 다른 것들이 냄새를 맡고 올 것이다.<br><br>
    척후병은 갈 때 본 것으로 돌아올 길을 낸다. 갈 때 무엇을 봤는지가 지금 쓰인다.`,
    o:[
      { l:'① 갈 때 본 것을 거꾸로 짚으며 앞서 간다.', k:'evade', dc:15, wake:1,
        ok:`갈 때 본 것을 하나씩 거꾸로 꺼냈다. 젖은 벽, 꺾인 데, 뼈 무더기. 무너진 데는 갈 때 본 옆 굴로 돌렸다.<br><br>피 냄새를 맡은 것들이 오는 소리가 났다. 오는 쪽이 들어올 때 지나온 큰 굴이다. 큰 굴을 버리고 작은 굴로 꺾었다. 작은 굴은 갈 때 한 번 들여다만 봤다. 한 번이면 됐다.<br>무리가 다 나왔다. 뒤에서 큰 굴이 냄새 맡은 것들로 찼다.<br><br>갈 때 지나치듯 본 것이 돌아올 때 다 길이 됐다. 이제 무엇을 보든 돌아올 길로 같이 본다.`,
        ng:`작은 굴을 골랐는데 갈 때 본 것과 달랐다. 그 사이에 무너졌다.<br><br>막혔다. 되돌아 나오는 동안 냄새 맡은 것들이 따라왔다. 무리 끝에서 맞붙었다.<br>이쪽이 맨 끝이었다. 다리를 물렸다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-8 } },
      { l:'② 무력을 다해 다친 사람을 업고 맨 앞에 선다.', k:'steady', dc:14, cost:{ might:18 },
        ok:`다친 사람을 업었다. 무겁다. 힘을 다 실었다. 맨 앞에 섰다.<br><br>업은 채로 길을 짚었다. 척후는 맨 앞이다. 등에 사람이 있어도.<br>굴 입구에 닿았다. 내려놓았다. 다친 사람이 이쪽 어깨를 두드렸다.<br><br>어깨가 한참 안 올라갔다. 길은 안 틀렸다.`,
        ng:`업고 가다 갈림길에서 헷갈렸다. 등의 무게가 생각을 눌렀다.<br><br>틀린 길로 들어갔다. 되돌아오는 데 힘을 다 썼다. 다리가 풀렸다. 둘이 같이 넘어졌다.<br>무리가 다친 사람을 받아 업었다. 이쪽 무릎이 깨졌다.`,
        win:{ exp:18, dream:2, mind:5 }, lose:{ hp:-14, mind:-8 } }
    ] },

  { at:'C', t:'쉬는 자리 — 망 보기',
    x:`무리가 쉰다. 이쪽이 망을 본다.<br><br>
    쉬는 자리는 굴 세 개가 모이는 데다. 어디로든 달아날 수 있다. 어디서든 올 수 있다.<br>
    불을 못 피운다. 소리로 본다. 세 굴에서 오는 바람 소리가 다 다르다.<br><br>
    밤이 깊다. 바람 소리 하나가 바뀌었다.`,
    o:[
      { l:'① 바람 소리로 어느 굴인지 가린다.', k:'sense', dc:14,
        ok:`세 굴 소리를 처음부터 외워 뒀다. 왼쪽은 휘파람, 가운데는 숨, 오른쪽은 물방울.<br><br>바뀐 것은 가운데다. 숨이 끊겼다 이어진다. 무엇이 굴을 막고 지나가는 중이다. 막혔다 열리는 사이가 길다. 크다.<br>무리를 깨워 오른쪽 굴로 옮겼다. 소리 없이. 가운데 굴에서 그것이 나와 쉬던 자리를 맡았다. 비었다.<br><br>그것이 다시 굴로 들어갈 때까지 숨을 반만 쉬었다.`,
        ng:`가운데라고 생각했다. 왼쪽이었다. 휘파람이 멎은 걸 못 들었다.<br><br>무리를 왼쪽 굴로 옮기려던 참에 왼쪽에서 그것이 나왔다. 맨 앞에 이쪽이 있었다.<br>어깨를 받혔다. 무리가 깨어 막았다. 어깨뼈가 울린다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } },
      { l:'② 소리가 바뀐 굴로 먼저 가 보고 온다.', k:'evade', dc:15,
        ok:`바뀐 굴로 혼자 들어갔다. 스무 걸음.<br><br>그것이 오고 있다. 굴을 꽉 채운 몸. 이쪽을 봤다. 몸을 돌려 뛰었다. 무리에게 닿기 전에 외쳤다. 다들 깨어 있었다.<br>무리가 다른 굴로 빠졌다. 이쪽이 마지막에 들어갔다. 그것이 쉬던 자리를 지나갔다.<br><br>그것은 비어 있는 쉼터를 오래 맡았다. 이쪽 냄새가 제일 진했다.`,
        ng:`스무 걸음 갔는데 그것이 벌써 열 걸음 앞이었다.<br><br>돌아서기 전에 앞발이 닿았다. 가슴이 그어졌다. 뛰었다. 외치는 게 늦었다.<br>무리는 반만 깼다. 다들 짐을 반쯤 두고 왔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C', t:'앞서 간 사람의 표식',
    x:`굴 벽에 숯 표식이 있다. 화살표와 가위표. 이쪽 버릇과 비슷하다.<br><br>
    다른 척후가 남긴 것이다. 언제인지 모른다. 숯이 번지지 않았다. 오래되지 않았다.<br>
    화살표가 굴 깊은 데를 가리킨다. 가위표는 옆 굴에 있다.<br><br>
    남의 표식을 믿을지는 척후가 정한다. 표식은 남긴 사람만큼만 맞다.`,
    o:[
      { l:'① 표식의 높이와 획을 보고 믿을 만한지 가린다.', k:'gaze', dc:14,
        ok:`화살표 획을 봤다. 끝을 꺾을 때 힘이 빠졌다. 서둘러 그었다. 가위표는 획이 고르다. 천천히 그었다.<br><br>천천히 그은 것이 본 것이다. 서둘러 그은 화살표는 쫓기며 그었다. 쫓기는 사람은 도망친 쪽을 화살표로 남긴다. 그 쪽이 안전한지는 모른다.<br>가위표 쪽 굴은 피하고, 화살표 쪽 굴은 반만 믿었다. 한 걸음마다 다시 봤다.<br><br>굴 끝에 숯 조각이 떨어져 있었다. 화살표를 그린 사람의 것이다. 사람은 없었다.`,
        ng:`획을 보는데 표식 아래에 다른 표식이 있었다. 지운 자국.<br><br>누가 표식을 고쳤다. 원래는 반대였다. 그걸 알아내는 동안 시간이 갔다. 옆 굴에서 뭔가 나왔다.<br>무리가 뛰었다. 이쪽은 표식 앞에서 늦었다. 팔을 긁혔다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-12, spirit:-8 } },
      { l:'② 표식 따라 혼자 끝까지 가서 맞는지 본다.', k:'evade', dc:15, wake:1,
        ok:`무리를 두고 화살표를 따라갔다. 표식이 셋 더 나왔다. 넷째에서 끊겼다.<br><br>끊긴 데 너머를 봤다. 바닥에 긁힌 자국. 사람 손톱. 그 너머는 그것들의 굴이다. 표식을 남긴 사람은 거기서 돌아서지 못했다.<br>이쪽은 돌아섰다. 돌아오며 화살표마다 가위표를 덧그었다. 넷째 자리에는 이쪽 표식을 새로 남겼다.<br><br>남의 끝을 보고 와서 이쪽 끝을 조금 뒤로 물렸다. 어디까지 갔다 돌아올지, 발이 먼저 셈하기 시작했다.`,
        ng:`넷째 표식 너머를 보려다 한 걸음 더 갔다.<br><br>바닥이 꺼졌다. 그것들 굴 천장이었다. 반쯤 빠졌다. 아래에서 소리가 몰려온다. 팔꿈치로 버텨 올라왔다.<br>돌아오는 동안 다리에서 피가 흘렀다. 표식은 못 고쳤다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-18, mind:-6 } }
    ] },

  { at:'C', t:'마지막 갈림 — 한 번에 고르기',
    x:`마지막 갈림이다. 둘 중 하나가 나가는 길이다.<br><br>
    무리가 지쳤다. 둘 다 볼 시간이 없다. 뒤에서 무엇이 온다. 하나만 보고 고르거나, 아무것도 안 보고 골라야 한다.<br>
    척후병은 보지 않고 고르는 것을 싫어한다. 그래도 고른다. 고르는 게 척후 일이다.<br><br>
    두 굴 입구가 거의 같다. 거의.`,
    o:[
      { l:'① 두 입구의 거의 다른 데를 찾는다.', k:'sense', dc:15,
        ok:`두 입구를 나란히 봤다. 바닥, 벽, 천장. 천장에서 다른 데가 보였다. 왼쪽 입구 천장에 이끼가 났다. 오른쪽은 없다.<br><br>이끼는 바깥바람을 먹고 자란다. 왼쪽이다.<br>무리를 왼쪽으로 보냈다. 이쪽이 마지막이었다. 뒤에서 오던 것이 갈림에서 멈췄다. 오른쪽으로 들어갔다. 그쪽이 그것의 집이었다.<br><br>굴 끝에 빛이 보였다.`,
        ng:`천장을 봤다. 이끼가 둘 다 났다. 바닥을 봤다. 둘 다 젖었다.<br><br>거의 같은 게 아니라 같았다. 결국 그냥 골랐다. 오른쪽. 막혔다. 되돌아왔다. 뒤에서 오던 것과 갈림에서 마주쳤다.<br>무리가 같이 쳤다. 이쪽 옆구리가 찢겼다.`,
        win:{ exp:20, dream:3 }, lose:{ hp:-16, mind:-8 } },
      { l:'② 무리에게 각자 본 것을 묻고 같이 고른다.', k:'bond', dc:14,
        ok:`무리에게 물었다. 오는 길에 무엇을 봤냐고. 각자 본 것이 다르다.<br><br>하나는 왼쪽 굴에서 새 깃털이 날려 온 걸 봤다. 하나는 오른쪽 굴 앞에서 비린내를 맡았다. 이쪽은 아무것도 못 봤다. 다들 본 것을 합쳤다.<br>왼쪽이다.<br><br>앞에서 본 것만이 척후가 아니었다. 뒤에서 본 것도 모으면 척후다.`,
        ng:`다들 본 것이 엇갈렸다. 왼쪽이라는 사람과 오른쪽이라는 사람이 반반이다.<br><br>정하는 사이 뒤에서 그것이 닿았다. 갈림에서 맞붙었다. 이쪽이 맨 뒤에서 막았다.<br>팔을 물렸다. 결국 왼쪽으로 뛰었다. 맞았다. 늦었다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-14, spirit:-6 } }
    ] }
]);

// ── 투우사 (matador) · 무력 ──────────────────
kJob('matador', 'C', [
  { at:'C', t:'사냥터 — 다리가 여덟인 돌진',
    x:`그것은 다리가 여덟이다. 머리가 어디 붙었는지 모르겠다. 몸 양 끝이 다 똑같이 생겼다.<br><br>
    달려든다. 어느 쪽 끝이 앞인지 모르는 채로.<br>
    투우사는 머리를 본다. 머리가 숙는 박자에 비킨다. 숙일 머리가 안 보이면 비킬 박자도 안 보인다.<br><br>
    다리가 땅을 긁는다. 여덟 개가 다 다른 박자로.`,
    o:[
      { l:'① 다리 여덟의 박자에서 앞을 찾아 비킨다.', k:'evade', dc:15, wake:1,
        ok:`다리를 봤다. 여덟이 다 따로 긁는다. 그런데 두 개가 먼저 멈췄다. 몸이 뛰기 전에 버팀목이 되는 다리다. 버팀 다리 반대가 앞이다.<br><br>천을 앞쪽에 펼쳤다. 그것이 달려왔다. 마지막 한 뼘에 천을 뺐다. 그것이 천을 따라 옆으로 지나갔다. 바위에 부딪혔다.<br>동료들이 덮쳤다. 이쪽은 천을 접었다.<br><br>머리가 없어도 앞은 있다. 달려드는 것은 무엇이든 디딤 다리가 먼저 말한다. 이제 이쪽 눈은 머리보다 발을 먼저 본다.`,
        ng:`버팀 다리를 잘못 봤다. 반대쪽 끝이 앞이었다.<br><br>천을 엉뚱한 데 펼쳤다. 그것이 천 반대편으로 왔다. 이쪽 쪽으로. 허리를 받혔다.<br>날아가 굴렀다. 동료들이 막았다. 허리가 한동안 안 펴졌다.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-18, mind:-6 } },
      { l:'② 무력을 실어 정면에서 받아 옆으로 민다.', k:'steady', dc:15, cost:{ might:18 },
        ok:`어느 쪽이 앞이든 오는 쪽이 앞이다. 몸을 낮추고 기다렸다.<br><br>그것이 닿았다. 두 팔로 받아 힘을 다 실어 옆으로 밀었다. 몸이 비틀렸다. 다리 여덟이 엉켰다. 뒤집혔다.<br>배가 드러났다. 동료들 창이 거기로 갔다.<br><br>팔이 저리다. 투우사의 방식은 아니다. 오늘은 그것도 쓴다.`,
        ng:`받았는데 다리 넷이 이쪽 다리를 감았다.<br><br>같이 넘어졌다. 그것이 이쪽 위에서 버둥댔다. 다리 끝이 등을 긁는다.<br>동료들이 떼어 냈다. 등에 줄이 여럿.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, spirit:-6 } }
    ] },

  { at:'C', t:'굴 — 눈 없는 것',
    x:`굴 안의 것은 눈이 없다. 얼굴 자리에 구멍이 셋. 숨구멍이다.<br><br>
    천을 흔들어도 안 본다. 볼 수가 없다. 대신 바람을 듣는다. 무엇이 움직이면 공기가 밀린다.<br>
    투우사의 천은 눈을 끄는 것이다. 눈이 없으면 천이 쓸모없는가.<br><br>
    천도 공기를 민다. 크게.`,
    o:[
      { l:'① 천을 크게 휘둘러 바람으로 부른다.', k:'evade', dc:15,
        ok:`천을 크게 펼쳐 한 번 휘둘렀다. 천이 공기를 쳤다. 굴 안에 바람이 일었다.<br><br>숨구멍 셋이 이쪽을 향했다. 아니, 천을. 달려왔다. 천을 반대로 빼며 몸을 비켰다. 그것이 천이 일으킨 바람을 쫓아 벽으로 갔다.<br>다시 휘둘렀다. 또 갔다. 셋째에 동료들이 뒤에서 쳤다.<br><br>천은 눈만 끄는 게 아니었다. 오늘 처음 알았다.`,
        ng:`천을 휘둘렀다. 그것이 왔다. 천을 뺐다. 그런데 이쪽 몸도 바람을 냈다.<br><br>그것이 두 바람 중 무거운 쪽을 골랐다. 이쪽이다. 어깨를 받혔다. 벽에 부딪혔다.<br>천을 놓쳤다. 다시 주웠을 때 어깨가 안 올라갔다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 천을 접고 숨을 죽여 지나간다.', k:'hide', dc:14,
        ok:`천을 품에 넣었다. 숨을 반으로 줄였다. 움직이지 않으면 공기가 안 밀린다.<br><br>그것이 굴을 돌았다. 이쪽 앞을 지났다. 숨구멍이 이쪽 얼굴 앞에서 오래 머물렀다. 이쪽은 숨을 안 쉬었다.<br>그것이 지나갔다. 천천히 빠져나왔다.<br><br>천을 안 쓰는 날이 투우사에게도 있다.`,
        ng:`숨을 참다 터졌다.<br><br>숨구멍이 이쪽 쪽으로 돌았다. 덮쳤다. 팔로 막았다. 팔을 물렸다.<br>천을 꺼내 휘둘러 떼어 냈다. 팔에 이빨 자국이 깊다.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-14, spirit:-6 } },
      { l:'③ 무력을 실어 지나가는 숨구멍을 친다.', k:'break', dc:15, cost:{ might:20 },
        ok:`그것이 이쪽 옆을 지나갈 때를 기다렸다. 숨구멍 셋이 이쪽 어깨 높이로 지났다.<br><br>주먹에 힘을 다 실어 가운데 구멍을 쳤다. 그것이 숨이 막혀 멈췄다. 숨구멍 셋에서 한꺼번에 바람이 빠졌다.<br>버둥대다 주저앉았다. 동료들이 끝냈다.<br><br>주먹에 그것의 숨이 묻었다. 비리다.`,
        ng:`쳤는데 구멍이 아니라 단단한 데를 쳤다.<br><br>손목이 꺾였다. 그것이 돌아서 이쪽 가슴을 받았다. 넘어졌다.<br>동료들이 막았다. 손목이 부었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-4 } }
    ] },

  { at:'C', t:'사냥 — 둘이 오는 굴',
    x:`굴 양쪽에서 하나씩 온다. 둘 다 크다. 둘 다 이쪽을 향한다.<br><br>
    무리가 둘로 갈려 하나씩 맡으면 둘 다 진다. 둘을 하나로 만들어야 한다.<br>
    투우사는 하나를 상대한다. 둘이면 둘을 서로에게 보낸다.<br><br>
    둘이 마주칠 자리는 이쪽이 정한다.`,
    o:[
      { l:'① 가운데 서서 둘을 한 박자에 부른다.', k:'evade', dc:16, wake:1,
        ok:`굴 가운데에 섰다. 천을 펼쳐 앞뒤로 다 보이게 들었다. 앞이 조금 빨랐다. 천을 앞쪽으로 조금 기울였다. 앞의 것이 천을 보고 속도를 늦췄다. 뒤의 것과 박자가 맞았다.<br><br>둘이 같은 박자로 왔다. 마지막 한 뼘에 천을 위로 던지고 바닥에 엎드렸다. 둘이 이쪽 위에서 부딪쳤다. 굴이 울렸다.<br>둘 다 쓰러졌다. 무리가 덮쳤다.<br><br>오는 것의 박자를 이쪽이 맞췄다. 기다리던 박자가 이제 만드는 박자가 됐다. 천 한 번 기울이는 것으로.`,
        ng:`앞의 것을 늦추다 너무 늦췄다. 뒤의 것이 먼저 닿았다.<br><br>엎드리기 전에 뒤의 것이 이쪽을 받았다. 앞으로 날아갔다. 앞의 것 앞으로. 앞의 것이 이쪽을 밟았다.<br>둘은 결국 부딪쳤다. 그 아래서 이쪽이 기어 나왔다. 갈비가 운다.`,
        win:{ exp:25, dream:3 }, lose:{ hp:-18, mind:-6 } },
      { l:'② 무리를 양 벽에 붙이고 가운데를 비운다.', k:'bond', dc:14,
        ok:`무리를 양쪽 벽으로 붙였다. 다들 숨을 죽였다. 가운데가 비었다.<br><br>둘이 가운데로 왔다. 빈 데를 향해. 서로를 봤다. 멈출 수 없는 속도다. 부딪쳤다.<br>벽에 붙어 있던 무리가 한꺼번에 덮쳤다.<br><br>천은 안 펼쳤다. 무리를 펼쳤다.`,
        ng:`한 사람이 벽에 덜 붙었다. 어깨가 가운데로 나왔다.<br><br>앞의 것이 그 어깨를 보고 방향을 틀었다. 이쪽이 그 사람을 밀쳤다. 이쪽이 받혔다.<br>둘은 안 부딪쳤다. 무리가 둘을 따로 맡았다. 다들 다쳤다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, spirit:-6 } }
    ] },

  { at:'C', t:'좁은 굴 — 비킬 데 없는 돌진',
    x:`굴이 좁다. 양옆 벽이 어깨에 닿는다.<br><br>
    앞에서 그것이 온다. 굴을 꽉 채웠다. 비킬 옆이 없다. 뒤로 가면 무리가 있다.<br>
    투우사는 마지막에 옆으로 비킨다. 옆이 없으면.<br><br>
    위도 낮다. 아래는 있다.`,
    o:[
      { l:'① 마지막 순간에 바닥에 납작 엎드린다.', k:'evade', dc:15,
        ok:`천을 굴 높이 가득 펼쳤다. 그것이 천을 보고 머리를 숙였다. 숙인 머리는 천 높이를 받는다.<br><br>천을 놓고 바닥에 엎드렸다. 그것이 천을 받으며 이쪽 위를 지나갔다. 배가 등을 스쳤다. 다리는 벽을 디디고 있었다. 좁은 굴이라서.<br>지나간 뒤에 일어섰다. 그것이 천을 머리에 쓰고 뒤에서 버둥댄다. 뒤의 무리가 쳤다.<br><br>옆이 없으면 아래도 옆이다.`,
        ng:`엎드렸는데 그것이 머리를 덜 숙였다.<br><br>앞발이 이쪽 등을 밟고 지나갔다. 굴이 좁아서 피할 데가 없었다. 등뼈가 운다.<br>뒤의 무리가 쳤다. 이쪽은 한참 엎드려 있었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-18, mind:-4 } },
      { l:'② 무력을 다해 정면으로 받아 세운다.', k:'steady', dc:15, cost:{ might:20 },
        ok:`발을 벽에 대고 등을 반대 벽에 댔다. 굴 너비가 이쪽 버팀이 됐다. 힘을 다 실었다.<br><br>그것이 닿았다. 이쪽이 밀렸다. 한 뼘. 멈췄다. 굴이 버텼다. 이쪽도.<br>그것이 다시 밀었다. 그 사이 무리가 이쪽 어깨 너머로 창을 내밀었다.<br><br>멈춘 것은 이쪽이 아니라 굴이었다. 이쪽은 굴에 기대 있었을 뿐이다.`,
        ng:`버텼는데 벽 한쪽이 무너졌다.<br><br>버팀이 빠졌다. 그것이 이쪽을 밀고 무리까지 갔다. 다들 넘어졌다.<br>무리가 엉킨 채로 쳤다. 이쪽 무릎이 꺾였다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-18, mind:-6 } }
    ] },

  { at:'C1', t:'계류장 — 다리가 남는 것',
    x:`계류장 칸에서 소가 나온다. 소였다.<br><br>
    잘린 다리가 다시 자랐다. 한 번 잘린 자리에 둘이 났다. 다리가 일곱이다. 뿔도 셋이다. 하나는 옆구리에서 났다.<br>
    그래도 소다. 땅을 긁는다. 고개를 숙인다. 투우사가 아는 짓이다.<br><br>
    다만 옆구리 뿔은 고개를 숙여도 옆을 향한다.`,
    o:[
      { l:'① 천을 펼쳐 맞되 옆구리 뿔 반대로 비킨다.', k:'evade', dc:15, wake:1,
        ok:`소가 왔다. 머리 뿔 둘이 천을 겨눈다. 옆구리 뿔은 오른쪽을 겨눈다. 그렇다면 천은 왼쪽으로 뺀다.<br><br>마지막 한 뼘에 천을 왼쪽으로 뺐다. 소가 천을 따라 꺾었다. 옆구리 뿔이 이쪽 반대편 빈 데를 쓸었다.<br>돌아서는 소에게 천을 한 번 더 보였다. 다시 지나갔다. 다리 일곱이 엉켜 넘어졌다. 동료들이 덮쳤다.<br><br>뿔이 몇 개든 어디로 향했든, 천이 갈 데는 뿔이 안 닿는 데다. 몸이 뿔을 세지 않고 빈 데를 먼저 찾았다.`,
        ng:`옆구리 뿔을 봤다. 그런데 소가 꺾으면서 몸을 비틀었다. 옆구리 뿔이 왼쪽을 향했다.<br><br>허벅지를 그었다. 깊다. 쓰러졌다. 소가 돌아섰다.<br>동료들이 소를 막았다. 허벅지를 동여맸다. 피가 많이 났다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-18, mind:-4 } },
      { l:'② 무력을 실어 지나가는 소의 남는 다리를 친다.', k:'break', dc:15, cost:{ might:18 },
        ok:`소가 지나갈 때 다리를 봤다. 새로 난 다리가 약하다. 살만 있고 뼈가 덜 찼다.<br><br>비키며 그 다리를 힘껏 찼다. 꺾였다. 소가 그쪽으로 기울었다. 넘어졌다.<br>넘어진 소는 다시 일어서지 못했다. 다리가 많아서 어느 다리로 설지 모른다.<br><br>무리가 끝내고 고기를 떼어 냈다. 새로 자란 쪽은 버렸다. 원래 소였던 쪽만.`,
        ng:`찼는데 옛 다리였다. 단단하다.<br><br>발이 튕겼다. 소가 이쪽을 들이받았다. 칸막이에 부딪혔다.<br>칸막이째 넘어졌다. 소가 지나갔다. 발목이 부었다.`,
        win:{ exp:18, item:'짐승 고기' }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C1', t:'탕박조 — 뜨거운 탕 앞',
    x:`털 뽑는 탕 앞에서 그것이 이쪽을 노린다. 돼지였다. 지금은 사람 둘 크기다.<br><br>
    탕은 끓는다. 그것은 탕을 안다. 탕 옆으로만 다닌다.<br>
    투우사는 달려드는 것을 원하는 데로 보낸다. 원하는 데가 끓는 물이면.<br><br>
    다만 탕 가장자리는 투우사도 미끄럽다.`,
    o:[
      { l:'① 탕을 등지고 서서 천으로 맞는다.', k:'evade', dc:15,
        doom:{ title:'탕박조', what:'뜨거운 탕 속으로 끌려 들어갑니다', dc:15, sec:55,
          text:`탕을 등지고 섰다. 천을 펼쳤다. 그것이 왔다. 마지막에 천을 빼며 비켰다.<br><br>그것이 천을 따라 탕으로 뛰어들었다. 그런데 앞발 하나가 이쪽 허리띠를 걸었다. 같이 들어갔다.<br>끓는다. 그것이 탕 속에서 버둥대며 이쪽을 끌어안는다. 털 없는 살이 미끄럽다. 놓지 않는다.<br><br>동료들이 탕 가장자리에서 손을 뻗는다. 김 때문에 이쪽이 어디 있는지 모른다.`,
          dieText:`투우사는 달려드는 것을 원하는 데로 보낸다.<br><br>보냈다. 같이 갔다. 같이 가지 않는 법까지 배웠어야 했다.<br>탕 위에 천이 떴다. 끓는 물 위에서 오래 맴돌았다.` },
        ok:`탕을 등지고 섰다. 그런데 한 걸음 옆에. 천은 탕 바로 앞에 펼쳤다. 이쪽 몸은 천 옆이다.<br><br>그것이 천을 겨눴다. 왔다. 천을 놓았다. 천이 탕 위로 날렸다. 그것이 천을 쫓아 그대로 뛰어들었다. 이쪽은 한 걸음 옆에서 그걸 봤다.<br>끓는 소리가 그것의 소리를 덮었다. 조용해졌다.<br><br>천은 건지지 못했다. 그것과 같이 익었다. 새 천을 구해야 한다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 탕 둘레 바닥에서 덜 미끄러운 데를 찾는다.', k:'sense', dc:14,
        ok:`탕 둘레 바닥을 봤다. 기름이 고인 데, 물이 튄 데. 배수 홈 위는 물이 빠져 덜 미끄럽다.<br><br>배수 홈 위에만 섰다. 그것이 왔다. 홈 위에서 비켰다. 발이 안 미끄러졌다. 그것은 기름 바닥을 디뎠다. 미끄러져 탕 가장자리에 부딪혔다.<br>동료들이 밀었다. 탕으로 들어갔다.<br><br>발밑을 먼저 봤다. 천보다 먼저.`,
        ng:`배수 홈인 줄 알았는데 덮개가 녹슬어 빠졌다.<br><br>발이 홈에 빠졌다. 그것이 왔다. 비킬 수 없었다. 어깨를 받혔다. 탕 쪽으로 밀렸다.<br>동료가 허리를 잡았다. 등이 탕 김에 데었다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C1', t:'출하장 — 반장의 정면',
    x:`출하장 끝에 반장이 있다. 팔이 여럿이다. 팔마다 칼과 갈고리.<br><br>
    반장은 앞으로만 온다. 라인처럼. 옆을 안 본다. 앞에 있는 것을 자르고 건다.<br>
    동료들이 옆에서 칠 틈을 노린다. 반장의 앞에 누가 서 있어야 한다. 반장이 앞만 보도록.<br><br>
    투우사는 정면에 선다. 늘 그랬다.`,
    o:[
      { l:'① 반장 정면에서 천을 흔들며 뒷걸음질한다.', k:'evade', dc:16,
        ok:`반장 앞에 섰다. 천을 흔들었다. 반장이 천을 향해 왔다. 칼이 천을 자른다. 천 끝이 잘려 나간다. 이쪽은 한 걸음 물러났다.<br><br>또 한 걸음. 반장이 따라온다. 천만 자른다. 갈고리가 천을 걸려 할 때 천을 놓았다가 다시 잡았다. 반장의 팔들이 천에 엉킨다.<br>옆에서 동료들이 앞치마 끈을 끊었다. 팔들이 늘어졌다.<br><br>천이 반 토막 났다. 그래도 반장은 끝까지 천만 봤다.`,
        ng:`세 걸음째에 뒤꿈치가 라인 레일에 걸렸다.<br><br>넘어졌다. 반장이 앞을 봤다. 앞에 이쪽이 누워 있다. 갈고리가 내려왔다. 굴렀다. 갈고리가 옷을 걸고 찢었다.<br>동료들이 옆에서 덮쳤다. 이쪽 옆구리에 갈고리 자국.`,
        win:{ exp:22, dream:3 }, lose:{ hp:-18, spirit:-6 } },
      { l:'② 반장이 앞을 고르는 법을 본다.', k:'gaze', dc:14,
        ok:`반장을 봤다. 앞에 둘이 있으면 큰 쪽을 먼저 자른다. 라인에 걸린 덩이도 큰 것부터 갔다.<br><br>동료들에게 짐을 높이 쌓게 했다. 이쪽보다 크게. 반장이 짐더미를 먼저 잘랐다. 이쪽은 짐더미 옆에 섰다. 반장 팔들이 짐에 박혔다.<br>동료들이 옆에서 끝냈다.<br><br>앞에 서는 일을 짐에게 맡겼다. 짐은 다치지 않았다. 반쯤 잘렸을 뿐이다.`,
        ng:`큰 것부터라고 봤다. 반장은 움직이는 것부터였다.<br><br>짐더미 옆에서 이쪽이 숨을 쉬었다. 반장이 이쪽을 골랐다. 칼이 어깨를 그었다.<br>동료들이 덮쳤다. 어깨가 깊게 갈라졌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C2', t:'실 감는 방 — 실에 끌려오는 것',
    x:`사람만 한 인형이 달려온다. 실에 매달려서. 발이 바닥에 반만 닿는다.<br><br>
    인형은 천을 안 본다. 눈이 유리다. 실이 끄는 대로 온다. 실 끝의 손이 보고 당긴다.<br>
    투우사의 천은 달려드는 것의 눈을 끈다. 달려드는 것에 눈이 없으면, 눈이 있는 데를 끈다.<br><br>
    실은 천장 구멍으로 올라간다. 거기서 누가 본다.`,
    o:[
      { l:'① 천을 천장 구멍 쪽으로 들어 올려 흔든다.', k:'evade', dc:15, wake:1,
        ok:`천을 인형 앞이 아니라 위로 들었다. 천장 구멍이 보는 높이로. 흔들었다.<br><br>인형이 왔다. 실이 당긴다. 마지막 한 뼘에 천을 옆으로 뺐다. 위에서 보던 손이 천을 따라 실을 당겼다. 인형이 천이 간 쪽으로 꺾였다. 벽에 부딪혀 깨졌다.<br>사기 조각 사이에 이가 흩어졌다.<br><br>달려드는 것과 달려들게 하는 것은 다르다. 천이 이제 뒤에 있는 눈까지 닿는다. 이쪽이 상대하는 것이 하나 늘었다.`,
        ng:`위를 보느라 인형을 놓쳤다.<br><br>인형이 이쪽 가슴에 부딪혔다. 사기 몸이 무겁다. 깨지면서 이가 이쪽 팔에 박혔다.<br>넘어졌다. 실이 이쪽 위로 내려와 더듬었다. 동료가 끊었다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, spirit:-8 } },
      { l:'② 무력을 실어 지나가는 인형의 실을 잡아챈다.', k:'break', dc:14, cost:{ might:18 },
        ok:`인형이 이쪽 옆을 지나갈 때 실을 잡았다. 힘을 다 실어 당겼다.<br><br>위에서 당기던 손이 끌려왔다. 천장 구멍에서 사기 팔이 쑥 나왔다. 실을 놓지 않는다. 더 당겼다. 팔이 어깨까지 나왔다.<br>동료가 그 팔을 쳤다. 실이 끊겼다. 인형이 바닥에 쓰러졌다. 위의 손은 팔 하나를 잃었다.<br><br>손바닥이 실에 베였다. 깊지 않다.`,
        ng:`실을 잡았는데 위에서 더 세게 당겼다.<br><br>이쪽이 들렸다. 발끝이 바닥에서 떨어졌다. 놓았다. 떨어졌다. 무릎으로.<br>인형은 실에 끌려 다시 왔다. 굴러 피했다. 무릎이 깨졌다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, mind:-6 } }
    ] },

  { at:'C2', t:'가마실 — 불 지키는 것',
    x:`가마 앞에 그것이 있다. 큰 삽을 들었다. 사기 인형을 삽에 실어 가마에 넣는다.<br><br>
    가마 앞에 서 있는 것은 다 굽는다. 그것은 이쪽을 굽기 전의 인형으로 본다. 삽을 들고 달려온다.<br>
    삽 끝은 넓다. 비켜도 삽 끝이 따라 쓴다.<br><br>
    투우사는 삽을 뿔처럼 본다. 넓은 뿔이다.`,
    o:[
      { l:'① 삽 앞에 천을 펼쳐 가마 쪽으로 흘린다.', k:'evade', dc:15,
        doom:{ title:'가마', what:'삽에 실려 가마로 들어갑니다', dc:15, sec:55,
          text:`천을 가마 쪽으로 펼쳤다. 그것이 삽을 내밀고 왔다. 마지막에 천을 뺐다. 비켰다.<br><br>삽 끝이 넓었다. 비킨 이쪽 다리를 쓸었다. 삽 위로 넘어졌다. 그것이 삽을 들었다. 이쪽이 실렸다.<br>가마 쪽으로 간다. 불이 가깝다. 삽 위에서 몸을 굴렸다. 삽 가장자리가 높다. 굽기 전 인형이 안 떨어지게 만든 삽이다.<br><br>동료들이 그것의 다리를 친다. 그것은 멈추지 않는다. 가마 문이 열린다.`,
          dieText:`투우사는 삽을 뿔처럼 봤다.<br><br>뿔은 찌른다. 삽은 담는다. 담긴 것은 굽는다.<br>다음 날 가마에서 인형 하나가 나왔다. 천을 든 모양으로 구워졌다.` },
        ok:`천을 가마 쪽으로 펼쳤다. 그것이 삽을 내밀고 왔다. 삽 끝이 넓다는 걸 안다. 비키지 않았다. 대신 삽 끝 위로 뛰었다.<br><br>삽 날을 밟고 넘었다. 그것이 천을 담으려 삽을 내밀었다. 천을 놓았다. 그것은 천을 담고 몸을 돌려 가마에 넣었다. 버릇이다. 가마에 넣으려고 삽을 깊이 밀었다. 몸까지 따라 들어갔다.<br>가마 문이 닫혔다. 안에서 소리가 났다.<br><br>천은 또 잃었다. 이번에는 그것이 천과 같이 갔다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 가마 벽에 등을 대고 삽이 오는 박자를 버틴다.', k:'steady', dc:14,
        ok:`가마 벽에 등을 붙였다. 뜨겁다. 그것은 가마를 안 다치게 한다. 가마 벽 앞에서는 삽을 낮춘다.<br><br>삽이 이쪽 발 앞에서 멈췄다. 그것이 머뭇거렸다. 가마를 다치게 할 수는 없다. 다른 인형을 찾으러 돌아섰다.<br>등이 다 데었다. 동료들이 돌아선 그것의 등을 쳤다.<br><br>뜨거운 것에 기대서 살았다.`,
        ng:`가마 벽이 너무 뜨거웠다. 등이 버티지 못했다. 몸을 뗐다.<br><br>그 순간 삽이 왔다. 정강이를 쳤다. 넘어졌다. 삽 끝이 이쪽 밑으로 들어왔다. 굴러 빠졌다.<br>등은 데었고 정강이는 찢어졌다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C2', t:'도장실 — 물감 냄새',
    x:`도장실은 냄새가 진하다. 꿀을 섞은 물감이다. 달고 끈적하다.<br><br>
    바닥에 물감이 흘렀다. 물감 위를 무엇이 지나간 자국이 있다. 작다. 빠르다. 인형들 중 덜 칠한 것들이 물감을 핥으러 다닌다.<br>
    선반에 꿀 단지가 줄지어 있다. 물감에 섞기 전의 꿀이다.<br><br>
    천에 물감이 묻으면 무겁다. 무거운 천은 늦다.`,
    o:[
      { l:'① 천을 높이 들고 물감 바닥을 비켜 지난다.', k:'evade', dc:14,
        ok:`천을 어깨 위로 들었다. 물감 흐른 데를 피해 디뎠다.<br><br>덜 칠한 인형 하나가 이쪽 발 쪽으로 기어 왔다. 발을 들어 넘겼다. 인형은 물감만 핥는다. 이쪽 발은 물감이 없다.<br>선반 앞에서 꿀 단지 하나를 집었다. 뚜껑이 닫혔다. 천을 안 내렸다.<br><br>나와서 보니 천이 깨끗하다. 오늘 천이 무거워질 일은 없다.`,
        ng:`인형을 넘기는데 천 끝이 내려왔다. 물감 바닥에 닿았다.<br><br>천이 끈적해졌다. 인형들이 천 끝으로 몰려왔다. 핥는다. 이도 쓴다. 천을 당기니 인형들이 매달려 딸려 온다.<br>떼어 내느라 팔을 물렸다. 천에 이 자국과 물감이 같이 남았다.`,
        win:{ exp:16, item:'꿀 한 줌' }, lose:{ hp:-12, spirit:-6 } },
      { l:'② 천에 물감을 묻혀 인형들을 한쪽으로 끈다.', k:'luck', dc:14,
        ok:`일부러 천 끝을 물감에 담갔다. 그리고 반대편 구석으로 끌었다.<br><br>덜 칠한 인형들이 천 끝을 따라 몰려갔다. 냄새를 따라. 구석에 천을 펼쳐 두었다. 인형들이 천 위에 모여 핥는다.<br>그 사이 무리가 선반의 꿀 단지를 챙겼다.<br><br>천을 되찾으러 갈 때가 제일 어려웠다. 인형들이 천을 안 놓는다. 끝 한 귀퉁이를 잘라 두고 왔다.`,
        ng:`천을 끌었는데 인형들이 천이 아니라 이쪽 손을 따라왔다. 손에도 물감이 묻었다.<br><br>손을 물렸다. 천을 버리고 손을 빼냈다. 손가락 사이가 찢겼다.<br>천은 구석에서 인형들 밑에 깔렸다. 한참 뒤에 찾았다.`,
        win:{ exp:15, item:'꿀 한 줌' }, lose:{ hp:-10, mind:-8 } }
    ] },

  { at:'C3', t:'종탑 — 흔들려 오는 종',
    x:`종탑에 큰 종이 매달렸다. 거꾸로. 종 입이 위를 향한다. 그래도 흔들린다.<br><br>
    종이 흔들리며 이쪽으로 온다. 멀어진다. 다시 온다. 올 때마다 종 테두리가 통로를 쓴다. 맞으면 뼈가 남지 않는다.<br>
    투우사는 흔들려 오는 것을 소처럼 본다. 똑바로 오고, 마지막에 못 꺾는다.<br><br>
    소와 다른 데가 있다. 종은 돌아온다.`,
    o:[
      { l:'① 종이 오는 박자에 반 걸음 비켜 통로를 지난다.', k:'evade', dc:15, wake:1,
        ok:`종이 왔다. 반 걸음 비켰다. 테두리가 코앞을 쓸었다. 바람이 눈을 쳤다.<br><br>종이 멀어졌다. 그 사이 세 걸음 나갔다. 종이 돌아왔다. 다시 반 걸음. 또 세 걸음. 종이 오는 박자가 이쪽 걸음 박자가 됐다.<br>통로를 다 지났다. 돌아봤다. 종이 텅 빈 통로를 쓸고 있다.<br><br>돌아오는 것도 달려드는 것이다. 오는 것마다 따로 비키는 게 아니라 오는 박자에 이쪽이 올라탄다. 이제 무엇이 몇 번 오든 같은 춤이다.`,
        ng:`셋째 오는 박자에 종이 조금 더 멀리 흔들렸다.<br><br>반 걸음이 모자랐다. 테두리가 어깨를 스쳤다. 스친 게 아니라 쳤다. 벽까지 날아갔다.<br>종이 다시 왔다. 엎드렸다. 등 위로 지나갔다. 어깨뼈가 운다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-18, mind:-4 } },
      { l:'② 무력을 다해 종 줄을 잡아 흔들림을 멈춘다.', k:'steady', dc:15, cost:{ might:20 },
        ok:`종이 멀어지는 끝에서 종 줄이 이쪽 앞으로 늘어졌다. 잡았다. 힘을 다 실어 버텼다.<br><br>종이 돌아오려 한다. 줄이 이쪽을 끈다. 발을 바닥에 박았다. 종이 반쯤 오다 섰다. 다시 당긴다. 버텼다.<br>종이 멈췄다. 무리가 통로를 지났다. 마지막에 이쪽이 줄을 놓고 뛰었다.<br><br>손바닥에 줄 자국이 깊다. 종이 다시 흔들리기 시작했다. 이쪽 뒤에서.`,
        ng:`줄을 잡았는데 종이 이쪽을 끌었다.<br><br>발이 미끄러졌다. 줄에 매달린 채 종과 같이 흔들렸다. 벽에 부딪혔다. 놓았다.<br>떨어졌다. 무릎이 깨졌다. 무리는 박자를 세며 따로 지났다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C3', t:'회랑 — 밀랍 수사 행렬',
    x:`회랑을 따라 밀랍 수사들이 걸어온다. 줄지어. 촛대를 들고. 거꾸로 선 성당 천장을 밟고.<br><br>
    행렬은 멈추지 않는다. 앞에 있는 것은 행렬에 섞인다. 섞인 것은 촛농을 뒤집어쓰고 수사가 된다.<br>
    회랑이 좁다. 행렬이 회랑을 다 채웠다.<br><br>
    투우사는 몰려오는 것도 갈라 보낸다. 머리를 보면.`,
    o:[
      { l:'① 행렬 맨 앞 수사에게 천을 보여 갈라 보낸다.', k:'evade', dc:14,
        ok:`행렬 맨 앞 수사를 봤다. 촛대를 높이 들었다. 뒤의 수사들은 그 촛불만 본다.<br><br>천을 펼쳐 맨 앞 수사 촛불 앞에 들었다. 촛불이 천에 가렸다. 맨 앞 수사가 천을 피해 왼쪽으로 꺾었다. 뒤가 다 따라 꺾었다.<br>회랑 오른쪽이 비었다. 무리가 오른쪽 벽에 붙어 지났다.<br><br>천에 촛농이 한 방울 떨어졌다. 굳었다. 천이 조금 단단해졌다.`,
        ng:`천을 들었는데 맨 앞 수사가 꺾지 않았다. 천을 향해 왔다. 촛불이 천에 닿았다.<br><br>천에 불이 붙었다. 털어 끄는 사이 행렬이 이쪽을 감쌌다. 촛농이 어깨에 떨어졌다.<br>뜯어내고 빠져나왔다. 어깨가 데었다. 천에 구멍이 났다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-6 } },
      { l:'② 기둥 뒤에 숨어 행렬을 흘려보낸다.', k:'hide', dc:14,
        ok:`회랑 기둥 뒤에 무리와 붙었다. 천으로 다 같이 덮었다. 천이 기둥 색과 비슷하다. 오래 써서.<br><br>행렬이 지나갔다. 촛불이 천 위를 비췄다. 수사들은 촛불만 본다. 천은 그림자다.<br>다 지나간 뒤에 천을 걷었다.<br><br>천은 숨기는 데도 쓴다. 이런 날도 있다.`,
        ng:`천 아래로 동료 발이 나왔다.<br><br>마지막 수사가 그 발을 봤다. 행렬에서 빠져나와 촛대를 내밀었다. 촛농이 동료 발에 떨어졌다. 이쪽이 그 수사를 밀쳤다.<br>수사가 넘어지며 촛대가 이쪽 팔을 지졌다.`,
        win:{ exp:15, dream:1 }, lose:{ hp:-12, mind:-8 } },
      { l:'③ 수사들이 든 초가 무엇으로 됐는지 본다.', k:'gaze', dc:14,
        ok:`촛대 끝을 봤다. 초가 노랗다. 밀랍이다. 꿀벌 밀랍. 수사들 몸과 같은 것이다.<br><br>행렬이 지나간 자리에 촛농이 떨어져 있다. 촛농 사이에 굳은 꿀 덩이가 섞였다. 초를 만들다 덜 걸러진 것이다.<br>행렬이 다 지나간 뒤 촛농 사이에서 꿀 덩이를 주웠다. 달다.<br><br>수사들이 무엇으로 만들어졌는지 알았다. 그건 무리에게 말하지 않았다.`,
        ng:`보는데 수사 하나가 이쪽을 봤다. 촛불을 이쪽 얼굴로 내밀었다.<br><br>눈앞이 하얬다. 촛농이 뺨에 떨어졌다. 물러났다. 뺨이 굳는다.<br>떼어 냈다. 살갗이 같이 떨어졌다.`,
        win:{ exp:16, item:'꿀 한 줌' }, lose:{ hp:-10, spirit:-10 } }
    ] },

  { at:'C3', t:'첨탑 — 홈통에서 나오는 것',
    x:`첨탑 벽 홈통에서 그것이 나온다. 길쭉하다. 돌 짐승 머리 모양의 머리. 몸은 젖은 가죽이다.<br><br>
    홈통 밖으로 몸을 반쯤 내밀고 달려든다. 반은 홈통 안에 남긴다. 물면 홈통 안으로 끌고 들어간다.<br>
    투우사는 달려드는 것을 지나가게 한다. 이것은 지나가지 않는다. 늘 반이 홈통에 있다.<br><br>
    지나가게 할 수 없으면 다 나오게 해야 한다.`,
    o:[
      { l:'① 천을 홈통에서 멀리 펼쳐 끝까지 끌어낸다.', k:'evade', dc:15,
        doom:{ title:'홈통', what:'홈통 속으로 끌려 들어갑니다', dc:15, sec:55,
          text:`천을 홈통에서 멀리 펼쳤다. 그것이 몸을 더 내밀었다. 조금 더. 이쪽도 조금 더 물러났다.<br><br>그것이 몸을 거의 다 내밀었을 때 이쪽 발뒤꿈치가 난간에 닿았다. 더 물러날 데가 없다. 그것이 왔다. 천을 뺐다. 비켰다. 그것은 천이 아니라 이쪽 발목을 물었다.<br>몸을 거두며 당긴다. 홈통 쪽으로. 홈통은 좁다. 그것은 좁은 데로 이쪽을 넣으려 한다.<br><br>동료들이 그것의 몸통을 잡았다. 젖은 가죽이 미끄럽다.`,
          dieText:`투우사는 달려드는 것을 끝까지 끌어낸다.<br><br>끝까지 끌어내려면 이쪽도 끝까지 물러나야 했다. 끝이 있었다.<br>홈통에서 물이 흘러나왔다. 비가 오지 않는데.` },
        ok:`천을 홈통에서 멀리 펼쳤다. 그것이 몸을 더 내밀었다. 이쪽은 물러났다. 물러나기 전에 난간까지 거리를 쟀다. 일곱 걸음.<br><br>여섯 걸음 물러났을 때 그것의 꼬리가 홈통에서 빠졌다. 다 나왔다. 그것이 달려왔다. 천을 뺐다. 그것이 천을 따라 난간을 넘었다.<br>홈통으로 돌아갈 몸이 없다. 아래로 떨어졌다. 소리가 오래 걸려 났다.<br><br>일곱째 걸음은 안 썼다. 남겨 둔 걸음이다.`,
        win:{ exp:24, dream:3 } },
      { l:'② 무력을 실어 홈통 입구 돌 머리를 깨뜨린다.', k:'break', dc:15, cost:{ might:20 },
        ok:`그것이 홈통으로 몸을 거둔 순간 홈통 입구 돌 머리를 쳤다. 힘을 다 실었다.<br><br>돌 머리가 깨졌다. 입구가 넓어졌다. 그것의 몸 반이 홈통 안에서 드러났다. 숨을 데가 없어졌다.<br>동료들이 드러난 몸에 칼을 넣었다. 그것이 홈통 안에서 버둥대다 멈췄다.<br><br>주먹이 터졌다. 돌을 친 값이다.`,
        ng:`돌 머리를 쳤는데 안 깨졌다.<br><br>주먹이 튕겼다. 그것이 그 손을 물었다. 홈통 쪽으로 당긴다. 팔꿈치까지 들어갔다.<br>동료들이 이쪽 허리를 잡아 끌어냈다. 팔에 이빨 자국이 줄을 지었다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-18, mind:-6 } }
    ] },

  { at:'C4', t:'온실 — 멧돼지를 입은 것',
    x:`멧돼지였다. 지금은 하얀 것이 입었다. 엄니 사이로 갓이 비져나왔다.<br><br>
    땅을 긁는다. 고개를 숙인다. 멧돼지 버릇은 그대로다. 다만 부딪칠 때마다 몸에서 가루가 터진다.<br>
    받히지 않아도 스치기만 하면 가루를 뒤집어쓴다. 비켜도 위험하다.<br><br>
    투우사는 한 뼘으로 비킨다. 오늘은 한 뼘이 가깝다.`,
    o:[
      { l:'① 천을 멀리 뻗어 몸과 천 사이를 벌린다.', k:'evade', dc:15, wake:1,
        ok:`천을 팔 끝까지 뻗었다. 천 끝만 쥐었다. 천이 이쪽 몸에서 멀다.<br><br>그것이 천을 향해 왔다. 천을 뺐다. 그것이 지나갔다. 몸에서 가루가 터졌다. 터진 데는 천이 있던 자리다. 이쪽은 한 팔 길이 떨어져 있었다.<br>다시 왔다. 다시 뺐다. 그것이 지나가며 선반을 받았다. 선반이 무너져 그것을 깔았다.<br><br>한 뼘이 꼭 몸에서 재는 한 뼘일 필요는 없었다. 천 끝에서 재면 된다. 이쪽 거리가 팔 하나만큼 늘었다.`,
        ng:`천을 멀리 뻗었는데 그것이 천이 아니라 천을 쥔 손을 봤다.<br><br>손 쪽으로 꺾었다. 엄니가 팔을 스쳤다. 가루가 터졌다. 얼굴까지.<br>물러나 숨을 참았다. 늦었다. 기침에 하얀 것이 섞였다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-14, mind:-10 } },
      { l:'② 그것이 파헤친 흙에서 먹을 것을 찾는다.', k:'sense', dc:13,
        ok:`그것이 땅을 긁은 자리를 봤다. 멧돼지 버릇이다. 먹을 것이 있는 데를 판다.<br><br>그것이 다른 데로 간 사이 판 자리를 봤다. 하얀 실 아래 초록이 있다. 실이 아직 못 덮은 나물이다. 뿌리째 뽑았다.<br>털어 보니 실이 안 감겼다. 땅속 깊은 데서 자란 것이다.<br><br>멧돼지를 입었어도 멧돼지처럼 판다. 판 자리는 쓸모가 있다.`,
        ng:`판 자리에 손을 넣었다. 그것이 돌아왔다. 먹을 것을 지키러.<br><br>엄니가 이쪽 등을 쳤다. 가루가 터졌다. 넘어졌다. 동료들이 끌어냈다.<br>등에서 하얀 것을 털어 내는 데 한참 걸렸다.`,
        win:{ exp:14, item:'산나물' }, lose:{ hp:-12, spirit:-6 } }
    ] },

  { at:'C4', t:'온실 — 천에 앉는 가루',
    x:`단을 내려갈수록 가루가 짙다. 공기가 뿌옇다.<br><br>
    천에 가루가 앉는다. 털어도 다시 앉는다. 가루가 앉은 천은 하얗게 변한다. 하얀 천은 무겁다. 그리고 천 위에서 가루가 자란다.<br>
    앞에서 정원사를 입은 것들이 몰려온다. 천을 써야 한다.<br><br>
    천이 무거워지기 전에.`,
    o:[
      { l:'① 천을 접어 얼굴을 감싸고 몸으로 비킨다.', k:'steady', dc:14,
        ok:`천을 접어 입과 코를 감쌌다. 천이 가루를 먼저 받는다.<br><br>정원사들이 왔다. 천 없이 비켰다. 몸으로. 하나, 둘. 가위가 옆을 지났다. 셋째는 동료들이 맡았다.<br>단을 다 내려왔다. 천을 풀었다. 바깥쪽이 하얗다. 안쪽은 깨끗하다.<br><br>천이 숨을 지켰다. 오늘 천은 그 일을 했다.`,
        ng:`천을 감쌌는데 비키는 데 천이 없으니 박자가 늦었다.<br><br>가위가 팔을 그었다. 넘어지며 천이 풀렸다. 숨을 쉬었다. 가루다.<br>기침하며 기어 나왔다. 팔이 피투성이다.`,
        win:{ exp:16, dream:2, hp:5 }, lose:{ hp:-14, mind:-8 } },
      { l:'② 천을 휘둘러 가루를 쓸며 길을 연다.', k:'evade', dc:15,
        ok:`천을 크게 휘둘렀다. 가루가 쓸려 나갔다. 천이 지나간 자리만 공기가 맑다.<br><br>정원사들이 휘둘린 천을 봤다. 가위를 들고 천을 향해 왔다. 천을 빼며 비켰다. 정원사가 가루 더미에 처박혔다.<br>천을 휘두를 때마다 길이 열렸다. 무리가 그 길로 왔다.<br><br>천이 하얗다. 무겁다. 단 끝에서 천을 털었다. 반은 털렸다.`,
        ng:`세 번 휘두르고 천이 무거워졌다. 가루가 앉아 자랐다.<br><br>네 번째에 천이 늦게 돌았다. 정원사의 가위가 천을 잘랐다. 천과 같이 이쪽 손가락 끝도.<br>천 반을 잃었다. 손끝에서 피가 멈추지 않는다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-16, spirit:-6 } },
      { l:'③ 무력을 실어 천을 물통에 담가 무겁게 휘두른다.', k:'break', dc:15, cost:{ might:20 },
        ok:`화분 물통에 천을 담갔다. 젖은 천은 가루가 안 날린다. 무겁다. 힘을 다 실어 휘둘렀다.<br><br>젖은 천이 정원사 머리를 쳤다. 갓이 꺾였다. 가루가 날리지 않고 천에 붙었다. 젖어서.<br>둘을 그렇게 쳤다. 나머지는 동료들이 맡았다.<br><br>천이 돌덩이처럼 무겁다. 어깨가 빠질 것 같다. 젖은 천은 늦지만 단단하다.`,
        ng:`젖은 천을 휘둘렀는데 너무 무거웠다. 한 번에 어깨가 늘어났다.<br><br>두 번째를 못 휘둘렀다. 정원사가 가까이 왔다. 천으로 막았다. 천이 찢겼다.<br>물러났다. 어깨가 안 올라간다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C4', t:'중앙 돔 — 여왕의 실',
    x:`중앙 돔 가운데 큰 갓이 숨을 쉰다. 갓 둘레에서 굵은 실이 채찍처럼 뻗는다.<br><br>
    실은 움직이는 것을 향한다. 움직이는 것 중 제일 큰 것을. 감으면 갓 밑으로 끌고 간다.<br>
    동료들이 갓 밑동을 베러 가야 한다. 실이 동료들을 보면 안 된다.<br><br>
    돔 안에서 제일 크게 움직이는 것이 되어야 한다. 투우사의 천은 원래 그 일을 한다.`,
    o:[
      { l:'① 천을 펼쳐 돔 안에서 가장 큰 것이 된다.', k:'evade', dc:16, wake:1,
        ok:`돔 한쪽 끝에서 천을 크게 펼쳤다. 휘둘렀다. 돔 안에서 제일 크게 움직이는 것이 됐다.<br><br>실이 왔다. 하나, 둘, 다섯. 다 천을 향한다. 천을 빼면 실이 빈 데를 감는다. 감고 다시 온다. 천을 다시 뺐다. 이쪽은 한 발짝도 안 옮겼다. 천만 돌았다.<br>그 사이 동료들이 반대편으로 돌아 밑동에 닿았다. 칼이 들어갔다. 실들이 한꺼번에 늘어졌다.<br><br>실 다섯이 다 천에 왔다. 천 하나로 다섯을 상대했다. 이쪽이 맞서는 것의 수가 이제 안 중요하다.`,
        ng:`실 셋까지는 천으로 받았다. 넷째가 천이 아니라 이쪽 발을 감았다. 발도 움직이고 있었다.<br><br>끌려갔다. 바닥에 등이 쓸렸다. 천으로 실을 감아 버텼다. 동료 하나가 돌아와 실을 끊었다.<br>밑동은 못 벴다. 다시 해야 한다. 발목에 하얀 실 뿌리가 박혔다.`,
        win:{ exp:25, dream:4 }, lose:{ hp:-18, spirit:-8 } },
      { l:'② 동료들과 번갈아 움직여 실을 갈라 놓는다.', k:'bond', dc:14,
        ok:`무리를 셋으로 나눴다. 한 패가 움직이면 둘은 멈춘다. 실이 움직이는 패를 쫓는다. 그 패가 멈추면 다른 패가 움직인다.<br><br>실이 이리저리 갈렸다. 이쪽이 박자를 외쳤다. 하나, 멈춰. 둘, 가. 셋째 패가 밑동에 닿았다.<br>칼이 들어갔다.<br><br>천은 안 펼쳤다. 무리가 천처럼 움직였다.`,
        ng:`박자를 외치는데 한 패가 늦게 멈췄다.<br><br>실이 두 패를 동시에 봤다. 둘 다 감겼다. 이쪽이 천을 펼쳐 끌었다. 실 하나가 이쪽에게 왔다. 허리를 감았다.<br>다 같이 끊고 물러났다. 다들 하얀 자국이 남았다.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-14, spirit:-8 } }
    ] },

  { at:'C', t:'사냥 — 지친 큰 것',
    x:`큰 것이 지쳤다. 오래 달려들었다. 천을 스무 번 지나갔다.<br><br>
    숨이 거칠다. 고개가 낮다. 앞발이 떨린다. 그래도 또 달려들 것이다. 그것밖에 모른다.<br>
    투우사는 마지막 돌진을 안다. 지친 것의 마지막은 제일 빠르다. 남은 걸 다 쓰니까.<br><br>
    마지막에 비키면 동료들이 끝낸다. 비키지 못하면 이쪽이 끝난다.`,
    o:[
      { l:'① 마지막 돌진을 끝까지 기다려 비킨다.', k:'evade', dc:15,
        ok:`천을 펼치고 기다렸다. 그것이 숨을 몰아쉰다. 한 번, 두 번. 셋째에 숨을 멈췄다. 왔다.<br><br>빠르다. 스무 번 중 제일 빠르다. 마지막 한 뼘에 천을 뺐다. 반 걸음 비켰다. 그것이 지나갔다. 멈추지 못하고 무릎을 꿇었다.<br>동료들이 끝냈다. 그것은 마지막까지 천을 봤다.<br><br>천을 접었다. 무겁다. 스물한 번 지나갔다.`,
        ng:`숨을 멈추는 박자를 하나 일찍 봤다. 먼저 비켰다.<br><br>그것이 따라 꺾었다. 지친 것이 꺾을 줄 몰랐다. 어깨를 받혔다. 같이 넘어졌다.<br>그것이 이쪽 위에서 숨을 거뒀다. 무겁다. 동료들이 굴려 냈다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-18, mind:-6 } },
      { l:'② 무력을 실어 지나가는 목덜미를 친다.', k:'break', dc:16, cost:{ might:22 },
        ok:`그것이 마지막으로 왔다. 비키며 몸을 돌려 목덜미를 쳤다. 힘을 다 실었다. 지나가는 힘에 이쪽 힘을 더했다.<br><br>그것이 고꾸라졌다. 다시 일어서지 않았다.<br>동료들이 다가와 확인했다. 끝났다.<br><br>팔이 떨린다. 지나가게 하는 것과 끝내는 것은 다른 일이다. 오늘은 둘 다 했다.`,
        ng:`목덜미를 쳤는데 그것이 고개를 들었다. 뿔이 이쪽 팔을 걸었다.<br><br>들렸다. 내던져졌다. 바위에 부딪혔다.<br>동료들이 그것을 끝냈다. 이쪽은 한참 숨이 안 쉬어졌다.`,
        win:{ exp:22, dream:2 }, lose:{ hp:-18, spirit:-6 } }
    ] },

  { at:'C', t:'쉬는 자리 — 천 손질',
    x:`쉰다. 천을 펼쳐 본다. 찢긴 데가 많다. 잘린 데, 탄 데, 물린 데.<br><br>
    찢긴 천은 돌 때 바람이 샌다. 바람이 새면 천이 늦게 돈다. 늦게 도는 천은 투우사를 죽인다.<br>
    실과 바늘이 있다. 손질할 시간은 있는지 모른다. 굴 끝에서 뭔가 냄새를 맡고 다닌다.<br><br>
    투우사는 천을 아낀다.`,
    o:[
      { l:'① 찢긴 데를 꿰매 천을 손질한다.', k:'fix', dc:13,
        ok:`찢긴 데를 하나씩 꿰맸다. 잘린 데는 맞대어, 탄 데는 덧대어. 물린 데는 그냥 두었다. 구멍이 작다.<br><br>펼쳐 한 번 돌려 봤다. 바람이 덜 샌다. 천이 손에 맞게 돈다.<br>굴 끝의 것은 이쪽 쪽으로 안 왔다. 바늘 소리는 작다.<br><br>천이 조금 무거워졌다. 꿰맨 만큼.`,
        ng:`꿰매다 바늘에 손가락을 찔렸다. 피가 천에 떨어졌다.<br><br>피 냄새에 굴 끝의 것이 고개를 들었다. 이쪽 쪽으로 왔다. 반쯤 꿰맨 천을 들고 일어섰다.<br>그것은 동료들이 쫓았다. 천은 반만 손질됐다. 손가락이 욱신거린다.`,
        win:{ exp:14, dream:1, spirit:8 }, lose:{ mind:-8, hp:-8 } },
      { l:'② 찢긴 천 그대로 냄새 맡는 것을 맞으러 간다.', k:'evade', dc:14,
        ok:`꿰매지 않고 일어섰다. 냄새 맡는 것이 쉬는 자리로 오기 전에 굴 끝에서 맞았다.<br><br>찢긴 천을 펼쳤다. 바람이 샌다. 천이 늦게 돈다. 늦게 도는 만큼 일찍 뺐다. 그것이 지나갔다. 다시. 또 일찍.<br>그것이 지쳐 돌아갔다. 이쪽 천에 구멍이 하나 늘었다.<br><br>찢긴 천으로도 됐다. 손이 천의 구멍을 세면서 돌렸다.`,
        ng:`일찍 뺐는데 너무 일찍이었다. 그것이 따라 꺾었다.<br><br>찢긴 데로 그것의 머리가 들어왔다. 천째 이쪽을 받았다. 넘어졌다.<br>동료들이 와서 쫓았다. 천에 큰 구멍이 났다. 이쪽 옆구리에도.`,
        win:{ exp:18, dream:2 }, lose:{ hp:-16, mind:-6 } }
    ] },

  { at:'C', t:'사냥 — 천을 보지 않는 것',
    x:`이것은 천을 안 본다. 이쪽 발을 본다.<br><br>
    천을 흔들어도 눈이 발로 간다. 발이 움직이는 쪽으로 온다. 어디서 배웠는지 모른다. 투우사를 먹어 본 것인지도.<br>
    투우사는 발로 비킨다. 발을 보는 것 앞에서는 비키는 순간 들킨다.<br><br>
    발을 안 움직이고 비킬 수 있는가.`,
    o:[
      { l:'① 발은 붙이고 허리와 천으로만 비킨다.', k:'evade', dc:15, wake:1,
        ok:`발을 땅에 붙였다. 무릎을 조금 풀었다. 천을 크게 들었다.<br><br>그것이 왔다. 발을 보며. 발은 안 움직인다. 그것이 발을 겨눈 채 마지막 한 뼘까지 왔다. 그때 허리를 비틀며 천을 그것 눈앞에 던지듯 펼쳤다. 발은 그대로다.<br>그것이 천에 눈이 막혀 이쪽 허리 옆을 스치고 지나갔다. 발을 못 찾은 채로.<br><br>발로 비키던 몸이 발 없이 비켰다. 남는 것은 허리와 천이다. 그거면 충분하다는 걸 몸이 알았다.`,
        ng:`발을 붙였다. 그것이 왔다. 허리를 비틀었다. 그런데 발 하나가 따라 움직였다. 버릇이다.<br><br>그것이 그 발을 봤다. 발목을 물었다. 넘어졌다. 동료들이 덮쳤다.<br>발목에 이빨 자국이 둥글다. 버릇을 떼려면 오래 걸릴 것이다.`,
        win:{ exp:24, dream:3 }, lose:{ hp:-16, mind:-6 } },
      { l:'② 발을 일부러 반대로 움직여 속인다.', k:'steady', dc:14,
        ok:`그것이 발을 본다. 그렇다면 발을 보여 준다. 오른발을 크게 오른쪽으로 내디뎠다.<br><br>그것이 오른쪽으로 꺾었다. 이쪽은 오른발을 축으로 몸을 왼쪽으로 돌렸다. 발은 오른쪽에 있다. 몸은 왼쪽에 있다.<br>그것이 오른발 옆 빈 데를 덮쳤다. 동료들이 옆에서 쳤다.<br><br>발을 보는 것은 발만 본다. 그건 그것의 버릇이다.`,
        ng:`오른발을 내디뎠다. 그것이 오른쪽으로 꺾었다. 몸을 돌렸다. 늦었다.<br><br>그것이 내디딘 오른발을 물었다. 놓지 않는다. 동료들이 쳤다. 놓았다.<br>오른발로 한동안 못 디뎠다.`,
        win:{ exp:16, dream:2 }, lose:{ hp:-16, spirit:-4 } }
    ] },

  { at:'C', t:'끝 무렵 — 마지막 돌진',
    x:`사냥이 끝나 간다. 남은 것은 하나다. 제일 크다.<br><br>
    동료들이 다 지쳤다. 창 끝이 떨린다. 이쪽 천도 무겁다. 찢기고 젖고 꿰맸다.<br>
    그것이 굴 끝에서 땅을 긁는다. 이쪽을 본다. 천을 본다.<br><br>
    투우사는 달려드는 것 앞에 선다. 이번에는 천을 들기 전에 그것이 먼저 고개를 숙였다.`,
    o:[
      { l:'① 무거운 천 그대로 한가운데 선다.', k:'evade', dc:16, wake:1,
        ok:`굴 한가운데 섰다. 천을 펼쳤다. 무겁다. 무거운 천은 늦게 돈다. 늦게 돈다는 걸 안다.<br><br>그것이 왔다. 크다. 굴 전체가 오는 것 같다. 기다렸다. 마지막 한 뼘이 아니라 반 뼘까지. 무거운 천에 맞는 박자다. 천을 뺐다. 천이 늦게, 크게 돌았다. 그것이 그 큰 원을 따라 꺾었다. 벽을 받았다.<br>동료들이 남은 힘으로 덮쳤다. 끝났다.<br><br>가벼운 천이든 무거운 천이든 박자는 이쪽이 맞춘다. 천이 무거워진 만큼 이쪽도 늦게 서는 법을 배웠다. 반 뼘이 이제 한 뼘만큼 넉넉하다.`,
        ng:`반 뼘까지 기다렸다. 천이 늦었다. 반 뼘보다 더 늦었다.<br><br>그것의 머리가 천을 뚫고 이쪽 가슴에 닿았다. 날아갔다. 벽에 부딪혔다.<br>동료들이 끝냈다. 이쪽은 숨이 한참 안 돌아왔다. 천에 큰 구멍이 났다.`,
        win:{ exp:25, dream:4 }, lose:{ hp:-18, mind:-8 } },
      { l:'② 무력을 다해 정면으로 받고 동료들을 부른다.', k:'steady', dc:15, cost:{ might:22 },
        ok:`천을 버렸다. 몸을 낮췄다. 남은 힘을 다 실었다.<br><br>그것이 왔다. 두 팔로 받았다. 밀렸다. 두 걸음. 세 걸음. 섰다. 동료들 이름을 불렀다.<br>동료들이 양옆에서 덮쳤다. 그것이 이쪽 팔 안에서 무너졌다.<br><br>팔이 안 펴진다. 천은 굴 바닥에 떨어져 있었다. 주웠다.`,
        ng:`받았는데 힘이 남아 있지 않았다.<br><br>밀렸다. 넘어졌다. 그것이 위를 지나갔다. 동료들이 뒤에서 막았다.<br>갈비에서 소리가 났다. 천은 그것 발에 밟혀 찢겼다.`,
        win:{ exp:20, dream:2 }, lose:{ hp:-18, spirit:-6 } }
    ] }
]);
